// Enhanced Express application with security best practices
// and comprehensive error handling

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// 1. Set security HTTP headers (Helmet)
app.use(helmet());

// 2. CORS configuration - restrict to trusted origins in production
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || []
    : '*', // Allow all in development
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.',
  skipSuccessfulRequests: false
});
app.use('/api', limiter); // Apply to API routes

// 4. Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ====================
// CUSTOM MIDDLEWARE
// ====================

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url} - ${req.ip}`);
  next();
});

// ====================
// ENVIRONMENT VALIDATION
// ====================

const validateEnvironment = () => {
  const requiredEnvVars = ['NODE_ENV', 'PORT'];
  const missing = requiredEnvVars.filter(varName => !process.env[varName]);

  if (missing.length > 0) {
    console.error(`❌ Missing required environment variables: ${missing.join(', ')}`);
    process.exit(1);
  }

  // Validate NODE_ENV
  const allowedEnvironments = ['development', 'test', 'production'];
  if (!allowedEnvironments.includes(process.env.NODE_ENV)) {
    console.error(`❌ Invalid NODE_ENV: ${process.env.NODE_ENV}. Must be one of: ${allowedEnvironments.join(', ')}`);
    process.exit(1);
  }
};

validateEnvironment();

// ====================
// ROUTES WITH VALIDATION
// ====================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
    uptime: process.uptime()
  });
});

// Users endpoint (example with validation)
app.get('/users', 
  // Input validation middleware
  [
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          status: 'error',
          message: 'Validation failed',
          errors: errors.array()
        });
      }

      // Example database query simulation
      const { page = 1, limit = 10 } = req.query;

      // Simulated data (in real app, this would come from database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Pagination simulation
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = users.slice(startIndex, endIndex);

      res.json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: users.length,
          pages: Math.ceil(users.length / limit)
        }
      });

    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({
        status: 'error',
        message: 'Internal server error'
      });
    }
  }
);

// Example POST endpoint with validation
app.post('/users',
  [
    body('name').notEmpty().trim().escape().withMessage('Name is required'),
    body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
    body('age').optional().isInt({ min: 0, max: 120 }).withMessage('Age must be between 0 and 120')
  ],
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          status: 'error',
          message: 'Validation failed',
          errors: errors.array()
        });
      }

      // In a real application, you would save to database here
      const newUser = {
        id: Date.now(),
        ...req.body,
        createdAt: new Date().toISOString()
      };

      res.status(201).json({
        status: 'success',
        data: newUser,
        message: 'User created successfully'
      });

    } catch (error) {
      console.error('Error in POST /users:', error);
      res.status(500).json({
        status: 'error',
        message: 'Internal server error'
      });
    }
  }
);

// ====================
// ERROR HANDLING MIDDLEWARE
// ====================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.originalUrl} not found`,
    method: req.method
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Log detailed error in development, generic in production
  const errorResponse = {
    status: 'error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  };

  // Add stack trace in non-production environments
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json(errorResponse);
});

// ====================
// GRACEFUL SHUTDOWN
// ====================

const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`✅ Server running in ${process.env.NODE_ENV} mode on port ${process.env.PORT || 3000}`);
});

// Handle graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('✅ HTTP server closed');
    // Clean up other resources here (database connections, etc.)
    console.log('✅ Graceful shutdown completed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('❌ Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Listen for termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

