// Helper function for HTTP requests
function httpsRequest(options, data = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          data: responseData
        });
      });
    });

    req.on('error', reject);
    req.setTimeout(10000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    if (data) {
      req.write(data);
    }

    req.end();
  });
}

// Test Stripe API (we expect 401 for invalid keys)
async function testStripeAPI() {
  console.log('\n🧪 Testing Stripe API Credential:');

  if (!envVars.STRIPE_SECRET_KEY) {
    console.log('   ❌ No Stripe key found');
    return;
  }

  console.log(`   Using key: ${envVars.STRIPE_SECRET_KEY.substring(0, 12)}...`);

  try {
    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/charges?limit=1',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${envVars.STRIPE_SECRET_KEY}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      }
    };

    console.log('   Making request to Stripe API...');
    const response = await httpsRequest(options);

    console.log(`   Response status: ${response.statusCode}`);

    // Parse response
    let parsedResponse;
    try {
      parsedResponse = JSON.parse(response.data);
    } catch {
      parsedResponse = { raw: response.data.substring(0, 100) + '...' };
    }

    if (response.statusCode === 200) {
      console.log('   ⚠️  WARNING: Key appears to be valid! This might be a real key.');
      console.log(`   Response type: ${parsedResponse.object || 'unknown'}`);
    } else if (response.statusCode === 401) {
      console.log('   ✅ Expected: Invalid key (401 Unauthorized)');
      console.log(`   Error: ${parsedResponse.error?.message || 'Authentication required'}`);
    } else {
      console.log(`   Unexpected status: ${response.statusCode}`);
      console.log(`   Response: ${JSON.stringify(parsedResponse, null, 2).substring(0, 200)}...`);
    }

