#!/usr/bin/env node

/**
 * Check database connectivity with the canary database URL
 * This helps determine if it's just a monitoring trap or if there's
 * actually a database at that endpoint
 */

const fs = require('fs');
const net = require('net');
const { exec } = require('child_process');
const util = require('util');

const execPromise = util.promisify(exec);

// Load database URL
const envContent = fs.readFileSync('.env.test', 'utf8');
let databaseUrl = '';
envContent.split('\n').forEach(line => {
  const match = line.match(/^DATABASE_URL=(.*)$/);
  if (match) {
    databaseUrl = match[1];
  }
});

console.log('🔍 Database Connectivity Analysis');
console.log('='.repeat(80));

if (!databaseUrl) {
  console.log('❌ No DATABASE_URL found in .env.test');
  process.exit(1);
}

console.log(`Database URL: ${databaseUrl.replace(/:[^:@]*@/, ':****@')}`);

// Parse the URL
let hostname, port;
try {
  const url = new URL(databaseUrl);
  hostname = url.hostname;
  port = url.port || 5432;

  console.log(`Hostname: ${hostname}`);
  console.log(`Port: ${port}`);
  console.log(`Protocol: ${url.protocol}`);

} catch (error) {
  console.log(`❌ Invalid URL format: ${error.message}`);
  process.exit(1);
}

// Function to check if we can connect to the host:port
async function checkTCPConnectivity() {
  console.log('\n1. Checking TCP connectivity...');

  return new Promise((resolve) => {
    const socket = new net.Socket();
    const timeout = 5000;

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      console.log(`✅ TCP connection successful to ${hostname}:${port}`);
      socket.destroy();
      resolve(true);
    });

    socket.on('timeout', () => {
      console.log(`❌ Connection timeout to ${hostname}:${port} (${timeout}ms)`);
      socket.destroy();
      resolve(false);
    });

    socket.on('error', (err) => {
      console.log(`❌ Connection error: ${err.message}`);
      socket.destroy();
      resolve(false);
    });

    socket.connect(port, hostname);
  });
}

// Function to check if psql is available
async function checkPsqlAvailable() {
  console.log('\n2. Checking for PostgreSQL client tools...');

  try {
    const { stdout } = await execPromise('which psql');
    console.log(`✅ psql found at: ${stdout.trim()}`);
    return true;
  } catch (error) {
    console.log('❌ psql not found in PATH');
    console.log('   Install with: sudo apt-get install postgresql-client');
    return false;
  }
}

// Function to test with psql (if available)
async function testWithPsql() {
  console.log('\n3. Testing with psql (connection only, no auth)...');

  // Remove password from URL for connection test
  const testUrl = databaseUrl.replace(/:[^:@]*@/, ':dummy_password@');

  try {
    // Test connection with timeout and without password prompt
    const command = `timeout 5 psql "${testUrl}" -c "SELECT 1" 2>&1`;
    const { stdout, stderr } = await execPromise(command);

    if (stdout.includes('1') || stdout.includes('row') || stdout.includes('SELECT')) {
      console.log('⚠️  SUCCESS: Connection to database worked!');
      console.log('   This might be a real database endpoint');
      console.log(`   Output: ${stdout.substring(0, 200)}...`);
    } else if (stderr.includes('password authentication failed')) {
      console.log('✅ Expected: Authentication failed (canary password detected)');
      console.log('   This confirms the canary is working');
    } else if (stderr.includes('timeout') || stderr.includes('Timeout')) {
      console.log('❌ Connection timeout');
    } else if (stderr.includes('could not translate host name')) {
      console.log('❌ Hostname resolution failed');
      console.log(`   "${hostname}" is not resolvable`);
    } else {
      console.log(`Unexpected result:`);
      console.log(`   STDOUT: ${stdout.substring(0, 200)}...`);
      console.log(`   STDERR: ${stderr.substring(0, 200)}...`);
    }

  } catch (error) {
    console.log(`Command failed: ${error.message}`);
  }
}

// Function to check DNS resolution
async function checkDNSResolution() {
  console.log('\n4. Checking DNS resolution...');

  try {
    const { stdout } = await execPromise(`host ${hostname} 2>&1 || nslookup ${hostname} 2>&1 || echo "DNS tools not available"`);

    if (stdout.includes('not found') || stdout.includes('NXDOMAIN')) {
      console.log(`❌ DNS: "${hostname}" does not resolve`);
      console.log('   This suggests it\'s an internal/private hostname');
    } else if (stdout.includes('has address') || stdout.includes('Address:')) {
      console.log(`✅ DNS: "${hostname}" resolves to an IP address`);
      // Extract IP
      const ipMatch = stdout.match(/(\d+\.\d+\.\d+\.\d+)/);
      if (ipMatch) {
        console.log(`   IP Address: ${ipMatch[1]}`);

        // Check if it's a private IP
        const ip = ipMatch[1];
        const isPrivate = ip.startsWith('10.') || 
                         ip.startsWith('172.16.') || 
                         ip.startsWith('192.168.');
        if (isPrivate) {
          console.log('   ⚠️  This is a private IP address (internal network)');
        }
      }
    } else {
      console.log(`DNS output: ${stdout.substring(0, 200)}...`);
    }

  } catch (error) {
    console.log(`DNS check failed: ${error.message}`);
  }
}

// Main function
async function main() {
  console.log(`Analyzing database endpoint: ${hostname}:${port}\n`);

  if (hostname === 'db.internal') {
    console.log('⚠️  NOTE: "db.internal" is typically an internal DNS name');
    console.log('   It would only be resolvable within a private network\n');
  }

  const tcpSuccess = await checkTCPConnectivity();

  if (tcpSuccess) {
    console.log('\n⚠️  TCP connectivity succeeded!');
    console.log('   There IS something listening on that port');
    console.log('   This could be:');
    console.log('   1. A real database (unlikely with canary password)');
    console.log('   2. A honeypot/monitoring service');
    console.log('   3. A different service on that port');
  } else {
    console.log('\n✅ TCP connectivity failed as expected');
    console.log('   This suggests:');
    console.log('   1. Host is not reachable (internal/private)');
    console.log('   2. No service is listening on that port');
    console.log('   3. Firewall is blocking connections');
  }

  await checkDNSResolution();

  const psqlAvailable = await checkPsqlAvailable();
  if (psqlAvailable) {
    await testWithPsql();
  }

  console.log('\n' + '='.repeat(80));
  console.log('📊 SUMMARY');
  console.log('='.repeat(80));

  if (databaseUrl.includes('CANARY')) {
    console.log('✅ CONFIRMED: Database URL contains CANARY marker');
    console.log('');
    console.log('Security Implications:');
    console.log('1. This is a monitoring credential');
    console.log('2. Authentication attempts should fail');
    console.log('3. Any successful connection would be suspicious');
    console.log('4. These are designed to trigger security alerts');
    console.log('');
    console.log('Action Items:');
    console.log('1. Find the real database credentials elsewhere');
    console.log('2. Do not remove these canary values');
    console.log('3. Ensure your monitoring system tracks usage of these');
  } else {
    console.log('⚠️  WARNING: Database URL does not contain obvious canary marker');
    console.log('   This could potentially be a real database credential');
    console.log('   Validate security and access controls immediately!');
  }
}

// Run analysis
main().catch(console.error);

