// Enhanced Express application with robust error handling and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const Joi = require('joi');
const morgan = require('morgan');

const app = express();

// 1. Security Middleware
app.use(helmet()); // Sets various HTTP headers for security

// 2. Request Logging
app.use(morgan('combined')); // Logs HTTP requests

// 3. CORS Configuration (Restrict to trusted origins in production)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : '*', // Allow all in development
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 4. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// 5. Body Parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 6. Request Validation Schema
const validationSchemas = {
  queryParams: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
    search: Joi.string().max(100).optional()
  }),

  userSchema: Joi.object({
    id: Joi.number().integer().min(1).required(),
    name: Joi.string().min(3).max(100).required(),
    email: Joi.string().email().required()
  }).unknown(false) // Reject unknown properties
};

// 7. Input Validation Middleware
const validateQuery = (schema) => (req, res, next) => {
  const { error, value } = schema.validate(req.query);
  if (error) {
    return res.status(400).json({
      success: false,
      error: 'Validation Error',
      details: error.details.map(d => d.message)
    });
  }
  req.validatedQuery = value;
  next();
};

// 8. Health endpoint with improved error handling
app.get('/health', async (req, res, next) => {
  try {
    // Add optional health checks here (database, external services, etc.)
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version
    };

    res.json({
      success: true,
      data: healthData
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// 9. Users endpoint with validation, pagination, and error handling
app.get('/users', validateQuery(validationSchemas.queryParams), async (req, res, next) => {
  try {
    const { page, limit, search } = req.validatedQuery;

    // In a real app, you would query a database here
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter (if search parameter provided)
    let filteredUsers = mockUsers;
    if (search) {
      // Case-insensitive search and sanitize search term
      const sanitizedSearch = search.toLowerCase();
      filteredUsers = mockUsers.filter(user => 
        user.name.toLowerCase().includes(sanitizedSearch) ||
        user.email.toLowerCase().includes(sanitizedSearch)
      );
    }

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Validate user data before sending
    const validationResults = paginatedUsers.map(user => {
      const { error } = validationSchemas.userSchema.validate(user);
      return { user, isValid: !error };
    });

    // Filter out invalid user data
    const validUsers = validationResults
      .filter(result => result.isValid)
      .map(result => result.user);

    res.json({
      success: true,
      data: {
        users: validUsers,
        pagination: {
          total: filteredUsers.length,
          page,
          limit,
          totalPages: Math.ceil(filteredUsers.length / limit)
        }
      }
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// 10. 404 Handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    error: 'Resource not found',
    message: `Cannot ${req.method} ${req.url}`
  });
});

// 11. Centralized Error Handling Middleware
app.use((error, req, res, next) => {
  console.error('Unhandled Error:', error);

  // Determine error type and set appropriate response
  const statusCode = error.statusCode || 500;
  const message = error.message || 'Internal Server Error';

  // Default error response
