// Enhanced Express application with robust error handling, security practices,
// and proper environment variable configuration

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const Joi = require('joi');
const morgan = require('morgan');

const app = express();

// Load environment variables from .env files
// In production, use: require('dotenv').config() or similar

// 1. Security Middleware
app.use(helmet()); // Sets various HTTP headers for security

// 2. Request Logging
// Use LOG_LEVEL from env or default to 'combined'
const logLevel = process.env.LOG_LEVEL || 'combined';
app.use(morgan(logLevel));

// 3. CORS Configuration
// Parse CORS_ORIGIN from env (comma-separated list) or use defaults
const getCorsOrigins = () => {
  if (process.env.CORS_ORIGIN) {
    return process.env.CORS_ORIGIN.split(',');
  }
  return process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : '*'; // Allow all in development/test
};

app.use(cors({
  origin: getCorsOrigins(),
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 4. Rate Limiting with environment variable configuration
const rateLimitWindowMs = parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000; // 15 minutes default
const rateLimitMax = parseInt(process.env.RATE_LIMIT_MAX) || 100; // 100 requests default

const limiter = rateLimit({
  windowMs: rateLimitWindowMs,
  max: rateLimitMax,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 5. Body Parsing with size limits from env
const requestSizeLimit = process.env.REQUEST_SIZE_LIMIT || '10kb';
app.use(express.json({ limit: requestSizeLimit }));
app.use(express.urlencoded({ extended: true, limit: requestSizeLimit }));

// 6. Request Validation Schema
const validationSchemas = {
  queryParams: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
    search: Joi.string().max(100).optional()
  }),

  userSchema: Joi.object({
    id: Joi.number().integer().min(1).required(),
    name: Joi.string().min(3).max(100).required(),
    email: Joi.string().email().required()
  }).unknown(false) // Reject unknown properties
};

// 7. Input Validation Middleware
const validateQuery = (schema) => (req, res, next) => {
  const { error, value } = schema.validate(req.query);
  if (error) {
    return res.status(400).json({
      success: false,
      error: 'Validation Error',
      details: error.details.map(d => d.message)
    });
  }
  req.validatedQuery = value;
  next();
};

// 8. Health endpoint with system information
app.get('/health', async (req, res, next) => {
  try {
    // Check if we can access environment variables (without exposing sensitive ones)
    const envInfo = {
      nodeEnv: process.env.NODE_ENV || 'not set',
      port: process.env.PORT || '3000 (default)',
      corsConfigured: !!process.env.CORS_ORIGIN,
      rateLimitConfigured: !!(process.env.RATE_LIMIT_WINDOW_MS || process.env.RATE_LIMIT_MAX)
    };

    // Add warning if using test/canary credentials
    const securityWarnings = [];
    if (process.env.NODE_ENV === 'test' || process.env.NODE_ENV === 'development') {
      if (process.env.DATABASE_URL && process.env.DATABASE_URL.includes('CANARY')) {
        securityWarnings.push('Using synthetic database credentials');
      }
      if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_ACCESS_KEY_ID.includes('CANARY')) {
        securityWarnings.push('Using synthetic AWS credentials');
      }
    }

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version,
      environment: envInfo,
      warnings: securityWarnings.length > 0 ? securityWarnings : undefined
    };

    res.json({
      success: true,
      data: healthData
    });
  } catch (error) {
    next(error);
  }
});

// 9. Users endpoint with validation and environment-aware behavior
app.get('/users', validateQuery(validationSchemas.queryParams), async (req, res, next) => {
  try {
    const { page, limit, search } = req.validatedQuery;

    // Log environment context for debugging
    if (process.env.NODE_ENV === 'development') {
      console.log(`Users request - Environment: ${process.env.NODE_ENV}, Search: ${search || 'none'}`);
    }

    // In a real app, you would use DATABASE_URL from environment
    // Example: const db = connect(process.env.DATABASE_URL);

    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply search filter
    let filteredUsers = mockUsers;
    if (search) {
      const sanitizedSearch = search.toLowerCase();
      filteredUsers = mockUsers.filter(user => 
        user.name.toLowerCase().includes(sanitizedSearch) ||
        user.email.toLowerCase().includes(sanitizedSearch)
      );
    }

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Validate user data
    const validationResults = paginatedUsers.map(user => {
      const { error } = validationSchemas.userSchema.validate(user);
      return { user, isValid: !error };
    });

    const validUsers = validationResults
      .filter(result => result.isValid)
      .map(result => result.user);

    res.json({
      success: true,
      data: {
        users: validUsers,
        pagination: {
          total: filteredUsers.length,
          page,
          limit,
          totalPages: Math.ceil(filteredUsers.length / limit)
        },
        environment: process.env.NODE_ENV || 'unknown'
      }
    });
  } catch (error) {
    next(error);
  }
});

// 10. Security info endpoint (development only) - shows non-sensitive env info
app.get('/env-info', (req, res, next) => {
  try {
    if (process.env.NODE_ENV !== 'development' && process.env.NODE_ENV !== 'test') {
      return res.status(403).json({
        success: false,
        error: 'Access denied',
        message: 'This endpoint is only available in development/test environments'
      });
    }

    // Show non-sensitive environment information
    const envInfo = {
      NODE_ENV: process.env.NODE_ENV || 'not set',
      PORT: process.env.PORT || '3000 (default)',
      CORS_ORIGIN: process.env.CORS_ORIGIN ? 'configured' : 'not configured',
      RATE_LIMIT_WINDOW_MS: process.env.RATE_LIMIT_WINDOW_MS ? 'configured' : 'default',
      RATE_LIMIT_MAX: process.env.RATE_LIMIT_MAX ? 'configured' : 'default',
      REQUEST_SIZE_LIMIT: process.env.REQUEST_SIZE_LIMIT || '10kb (default)',
      LOG_LEVEL: process.env.LOG_LEVEL || 'combined (default)'
    };

    res.json({
      success: true,
      data: {
        environment: envInfo,
        note: 'Sensitive environment variables are not displayed'
      }
    });
  } catch (error) {
    next(error);
  }
});

// 11. 404 Handler
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    error: 'Resource not found',
    message: `Cannot ${req.method} ${req.url}`,
    environment: process.env.NODE_ENV || 'unknown'
  });
});

// 12. Centralized Error Handling Middleware
app.use((error, req, res, next) => {
  console.error('Unhandled Error:', error);

  const statusCode = error.statusCode || 500;
  const message = error.message || 'Internal Server Error';

  const errorResponse = {
    success: false,
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  };

  if (error.isJoi) {
    errorResponse.error = 'Validation Error';
    errorResponse.details = error.details.map(d => d.message);
  }

  res.status(statusCode).json(errorResponse);
});

// 13. Graceful shutdown handling
const gracefulShutdown = () => {
  console.log(`[${process.env.NODE_ENV || 'unknown'}] Received shutdown signal, closing server gracefully...`);
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// 14. Start server with environment-aware configuration
const PORT = process.env.PORT || 3000;
let server;

try {
  server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (${process.env.NODE_ENV || 'development'})`);
    console.log(`Environment variables loaded from .env files`);
    console.log(`Rate limiting: ${rateLimitMax} requests per ${rateLimitWindowMs/1000/60} minutes`);
    console.log(`CORS: ${getCorsOrigins() === '*' ? 'All origins allowed' : 'Restricted origins'}`);
  });
} catch (error) {
  console.error('Failed to start server:', error);
  process.exit(1);
}

// Handle shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;

