#!/usr/bin/env node

/**
 * Test script to check if credentials can connect to actual services
 * This script makes safe, limited test requests to verify connectivity
 */

const https = require('https');
const dns = require('dns');
const { promisify } = require('util');

const dnsLookup = promisify(dns.lookup);

// Parse environment variables from .env.test
const fs = require('fs');
const path = require('path');

function parseEnvFile(filePath) {
  const env = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      if (!line.trim() || line.startsWith('#')) continue;
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        env[match[1].trim()] = match[2].trim();
      }
    }
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
  }
  return env;
}

const envVars = parseEnvFile(path.join(__dirname, '.env.test'));

console.log('🌐 Testing API Connectivity for Credentials');
console.log('=' .repeat(60));

// Helper function to make safe HTTP requests
function makeHttpRequest(options, data = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          data: responseData
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.setTimeout(10000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    if (data) {
      req.write(data);
    }

    req.end();
  });
}

// 1. Test Database Host Resolution
async function testDatabaseHostResolution() {
  console.log('\n1️⃣  Testing Database Host Resolution:');

  const dbUrl = envVars.DATABASE_URL;
  if (!dbUrl) {
    console.log('   No DATABASE_URL found');
    return;
  }

  // Extract host from URL
  const hostMatch = dbUrl.match(/@([^:]+):/);
  if (!hostMatch) {
    console.log('   Could not extract host from DATABASE_URL');
    return;
  }

  const host = hostMatch[1];

  console.log(`   Host: ${host}`);
  console.log(`   Full URL: ${dbUrl.substring(0, 60)}...`);

  try {
    // Try to resolve the hostname
    const startTime = Date.now();
    const address = await dnsLookup(host);
    const resolveTime = Date.now() - startTime;

    console.log(`   ✅ Host resolves to: ${address.address}`);
    console.log(`      Resolution time: ${resolveTime}ms`);

    // Check if it's a local/internal address
    if (host.includes('.internal') || host.includes('localhost') || 
        host.includes('127.0.0.1') || address.address.startsWith('192.168.') ||
        address.address.startsWith('10.') || address.address.startsWith('172.')) {
      console.log(`   ⚠️  NOTE: Internal/private network address detected`);
      console.log(`      This suggests a test/staging environment`);
    }

  } catch (error) {
    console.log(`   ❌ DNS resolution failed: ${error.code || error.message}`);

    // Check common issues
    if (error.code === 'ENOTFOUND') {
      console.log(`      Host "${host}" does not exist in DNS`);
      console.log(`      This could be:`);
      console.log(`      - A synthetic/test hostname`);
      console.log(`      - A private/internal hostname not in public DNS`);
      console.log(`      - A typo in the hostname`);
    }
  }
}

