// 5. Check for Common Issues
async function checkCommonIssues() {
  console.log('\n5️⃣  Checking for Common Issues:');

  const issues = [];

  // Check for expired-looking patterns
  const now = new Date();
  const currentYear = now.getFullYear();

  Object.entries(envVars).forEach(([key, value]) => {
    // Check for dates in values that might indicate age
    const yearMatches = value.match(/(19|20)\d{2}/g);
    if (yearMatches) {
      yearMatches.forEach(year => {
        const yearNum = parseInt(year);
        if (yearNum < currentYear - 2) {
          issues.push(`${key}: Contains year ${yearNum} (potentially old)`);
        }
      });
    }

    // Check for placeholder patterns
    const placeholderPatterns = [
      /CHANGE_ME/i,
      /YOUR_.*_HERE/i,
      /EXAMPLE/i,
      /TODO/i,
      /FIXME/i,
      /REPLACE/i,
      /INSERT/i
    ];

    placeholderPatterns.forEach(pattern => {
      if (pattern.test(value)) {
        issues.push(`${key}: Contains placeholder text "${value.match(pattern)[0]}"`);
      }
    });

    // Check for localhost/internal addresses in URLs
    if (value.includes('://')) {
      if (value.includes('localhost') || value.includes('127.0.0.1')) {
        issues.push(`${key}: Contains localhost/internal address`);
      }
    }
  });

  if (issues.length === 0) {
    console.log(`   ✅ No obvious issues detected`);
  } else {
    console.log(`   ⚠️  Potential issues found:`);
    issues.forEach(issue => {
      console.log(`      • ${issue}`);
    });
  }
}

