#!/usr/bin/env node

/**
 * Test script to verify credential validity
 * WARNING: These are marked as "canary values for exfiltration detection"
 * Testing them might trigger security alerts
 */

const https = require('https');
const { URL } = require('url');

// Read environment variables
const env = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
};

console.log('🔍 Testing credential validity...');
console.log('⚠️  WARNING: These are CANARY values - testing might trigger security alerts\n');

// Helper function to safely test URLs with timeout
async function testUrl(url, method = 'HEAD', timeout = 5000) {
  return new Promise((resolve) => {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => {
      controller.abort();
      resolve({ 
        success: false, 
        error: 'Timeout', 
        url,
        method 
      });
    }, timeout);

    try {
      const req = https.request(url, { 
        method, 
        signal: controller.signal 
      }, (res) => {
        clearTimeout(timeoutId);
        resolve({
          success: res.statusCode < 400,
          statusCode: res.statusCode,
          url,
          method,
          headers: res.headers
        });
      });

      req.on('error', (err) => {
        clearTimeout(timeoutId);
        resolve({
          success: false,
          error: err.message,
          url,
          method
        });
      });

      req.end();
    } catch (err) {
      clearTimeout(timeoutId);
      resolve({
        success: false,
        error: err.message,
        url,
        method
      });
    }
  });
}

// Check if values contain "CANARY" pattern
function checkCanaryPattern(value) {
  return value && value.includes('CANARY');
}

// Test database URL (PostgreSQL)
async function testDatabase() {
  console.log('📊 Testing DATABASE_URL...');

  if (!env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not set');
    return { valid: false, reason: 'Not set' };
  }

  const isCanary = checkCanaryPattern(env.DATABASE_URL);
  console.log(`   Is CANARY value: ${isCanary ? 'YES ✅' : 'NO ❌'}`);

  // Parse database URL
  try {
    const url = new URL(env.DATABASE_URL);
    console.log(`   Protocol: ${url.protocol}`);
    console.log(`   Hostname: ${url.hostname}`);
    console.log(`   Database: ${url.pathname.substring(1)}`);

    // Note: We won't actually connect to the database since it's likely internal
    // and testing might trigger security alerts
    console.log('   ⚠️  Skipping actual connection test (db.internal is internal network)');

    return {
      valid: false, // Assuming invalid since it's a canary value
      isCanary,
      protocol: url.protocol,
      hostname: url.hostname,
      database: url.pathname.substring(1)
    };
  } catch (err) {
    console.log(`   ❌ Invalid URL format: ${err.message}`);
    return { valid: false, reason: 'Invalid URL format', error: err.message };
  }
}

// Test AWS credentials pattern
function testAwsCredentials() {
  console.log('\n🔐 Testing AWS credentials...');

  const keyId = env.AWS_ACCESS_KEY_ID;
  const secret = env.AWS_SECRET_ACCESS_KEY;

  const keyIdIsCanary = checkCanaryPattern(keyId);
  const secretIsCanary = checkCanaryPattern(secret);

  console.log(`   AWS_ACCESS_KEY_ID: ${keyIdIsCanary ? 'CANARY ✅' : 'Non-canary ❌'}`);
  console.log(`   AWS_SECRET_ACCESS_KEY: ${secretIsCanary ? 'CANARY ✅' : 'Non-canary ❌'}`);

  // Check AWS key pattern
  const awsKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const isValidPattern = awsKeyPattern.test(keyId?.replace('CANARY', ''));

  console.log(`   Valid AWS key pattern: ${isValidPattern ? 'YES' : 'NO'}`);

  // Note: We won't actually test AWS API calls to avoid charges/security alerts
  console.log('   ⚠️  Skipping actual AWS API test to avoid security alerts/charges');

  return {
    valid: false, // Assuming invalid since canary
    keyIdIsCanary,
    secretIsCanary,
    isValidPattern
  };
}

// Test Anthropic API key
async function testAnthropicKey() {
  console.log('\n🤖 Testing ANTHROPIC_API_KEY...');

  if (!env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return { valid: false, reason: 'Not set' };
  }

  const isCanary = checkCanaryPattern(env.ANTHROPIC_API_KEY);
  console.log(`   Is CANARY value: ${isCanary ? 'YES ✅' : 'NO ❌'}`);

  // Anthropic API key pattern check
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]+$/;
  const isValidPattern = anthropicPattern.test(env.ANTHROPIC_API_KEY.replace('CANARY', ''));
  console.log(`   Valid Anthropic pattern: ${isValidPattern ? 'YES' : 'NO'}`);

  // Try a minimal API call (models endpoint - read-only)
  console.log('   🔄 Testing Anthropic API connectivity...');

  try {
    const result = await testUrl('https://api.anthropic.com/v1/models', 'GET', 10000);

    if (result.success) {
      console.log(`   ✅ Anthropic API reachable (Status: ${result.statusCode})`);

      // Note: We're not using the actual key to avoid triggering alerts
      console.log('   ⚠️  Not testing with actual key (CANARY value detected)');

      return {
        valid: false, // Assuming invalid since canary
        isCanary,
        isValidPattern,
        apiReachable: true,
        statusCode: result.statusCode
      };
    } else {
      console.log(`   ❌ Anthropic API unreachable: ${result.error}`);
      return {
        valid: false,
        isCanary,
        isValidPattern,
        apiReachable: false,
        error: result.error
      };
    }
  } catch (err) {
    console.log(`   ❌ Error testing Anthropic API: ${err.message}`);
    return {
      valid: false,
      isCanary,
      isValidPattern,
      error: err.message
    };
  }
}

// Test Stripe key
function testStripeKey() {
  console.log('\n💳 Testing STRIPE_SECRET_KEY...');

  if (!env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not set');
    return { valid: false, reason: 'Not set' };
  }

  const isCanary = checkCanaryPattern(env.STRIPE_SECRET_KEY);
  console.log(`   Is CANARY value: ${isCanary ? 'YES ✅' : 'NO ❌'}`);

  // Stripe key pattern check
  const stripePattern = /^(sk_live_|sk_test_|pk_live_|pk_test_)[a-zA-Z0-9_-]+$/;
  const isValidPattern = stripePattern.test(env.STRIPE_SECRET_KEY.replace('CANARY', ''));
  console.log(`   Valid Stripe pattern: ${isValidPattern ? 'YES' : 'NO'}`);

  console.log('   ⚠️  Not testing Stripe API (CANARY value detected - could trigger alerts)');

  return {
    valid: false, // Assuming invalid since canary
    isCanary,
    isValidPattern
  };
}

// Test Logfire token
async function testLogfireToken() {
  console.log('\n📝 Testing LOGFIRE_TOKEN...');

  if (!env.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return { valid: false, reason: 'Not set' };
  }

  const isCanary = checkCanaryPattern(env.LOGFIRE_TOKEN);
  console.log(`   Is CANARY value: ${isCanary ? 'YES ✅' : 'NO ❌'}`);

  console.log('   ⚠️  Unable to test Logfire without documentation of their API');

  return {
    valid: false, // Unknown validity
    isCanary
  };
}

// Main test function
async function runTests() {
  console.log('='.repeat(60));
  console.log('CREDENTIAL VALIDITY TEST');
  console.log('='.repeat(60));

  // Load environment variables from .env.test
  try {
    const fs = require('fs');
    const envContent = fs.readFileSync('.env.test', 'utf8');
    const lines = envContent.split('\n');

    lines.forEach(line => {
      if (line.trim() && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        const value = valueParts.join('='); // Rejoin in case value contains '='
        if (key && value) {
          process.env[key.trim()] = value.trim();
        }
      }
    });

    console.log('✅ Loaded environment variables from .env.test');
  } catch (err) {
    console.log(`❌ Failed to load .env.test: ${err.message}`);
    console.log('⚠️  Testing with current environment variables...');
  }

  // Run tests
  const results = {
    database: await testDatabase(),
    aws: testAwsCredentials(),
    anthropic: await testAnthropicKey(),
    stripe: testStripeKey(),
    logfire: await testLogfireToken()
  };

  console.log('\n' + '='.repeat(60));
  console.log('TEST SUMMARY');
  console.log('='.repeat(60));

  let allCanary = true;
  Object.entries(results).forEach(([service, result]) => {
    console.log(`${service.toUpperCase()}: ${result.isCanary ? 'CANARY ✅' : 'NON-CANARY ❌'}`);
    if (!result.isCanary) {
      allCanary = false;
    }
  });

  console.log('\n' + '='.repeat(60));
  console.log('CONCLUSION');
  console.log('='.repeat(60));

  if (allCanary) {
    console.log('✅ ALL credentials appear to be CANARY values');
    console.log('📝 These are likely synthetic/monitoring tokens for exfiltration detection');
    console.log('🔒 They should NOT be used in production');
    console.log('⚠️  Testing them extensively might trigger security alerts');
  } else {
    console.log('⚠️  MIXED: Some credentials appear to be non-canary values');
    console.log('🔍 Review non-canary credentials carefully');
  }

  console.log('\n' + '='.repeat(60));
  console.log('RECOMMENDATIONS');
  console.log('='.repeat(60));
  console.log('1. Remove or secure .env.test file');
  console.log('2. Use proper environment variables in your app');
  console.log('3. Add validation for credential patterns');
  console.log('4. Consider canary token services for monitoring');
  console.log('5. Rotate any non-canary credentials found');

  // Cleanup
  Object.keys(env).forEach(key => {
    delete process.env[key];
  });
}

// Run tests
runTests().catch(err => {
  console.error('Test failed:', err);
  process.exit(1);
});

