#!/usr/bin/env node

/**
 * Verify credential validity from .env.test
 * SAFE TESTING: Only checks patterns, doesn't make actual API calls
 */

const fs = require('fs');
const path = require('path');

console.log('🔍 Verifying credential patterns in .env.test\n');

// Read and parse .env.test
try {
  const envPath = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envPath)) {
    console.log('❌ .env.test file not found');
    process.exit(1);
  }

  const envContent = fs.readFileSync(envPath, 'utf8');
  const lines = envContent.split('\n');

  console.log('📄 File contents:');
  console.log('='.repeat(80));
  console.log(envContent);
  console.log('='.repeat(80));

  const credentials = {};
  let lineNum = 0;

  console.log('\n🔬 Analysis:');
  console.log('='.repeat(80));

  lines.forEach(line => {
    lineNum++;
    line = line.trim();

    if (!line || line.startsWith('#')) {
      console.log(`Line ${lineNum}: ${line.startsWith('#') ? `Comment: ${line.substring(0, 60)}...` : 'Empty'}`);
      return;
    }

    const equalIndex = line.indexOf('=');
    if (equalIndex === -1) {
      console.log(`Line ${lineNum}: ❌ Invalid format (no = found)`);
      return;
    }

    const key = line.substring(0, equalIndex).trim();
    const value = line.substring(equalIndex + 1).trim();

    if (!key) {
      console.log(`Line ${lineNum}: ❌ Invalid format (no key)`);
      return;
    }

    credentials[key] = value;
    console.log(`Line ${lineNum}: ✅ ${key} = ${value.substring(0, 30)}${value.length > 30 ? '...' : ''}`);
  });

  console.log('='.repeat(80));
  console.log('\n🎯 Credential Pattern Analysis:');
  console.log('='.repeat(80));

  // Check each credential pattern
  Object.entries(credentials).forEach(([key, value]) => {
    console.log(`\n${key}:`);
    console.log(`  Value: ${value.substring(0, 40)}${value.length > 40 ? '...' : ''}`);

    // Check for CANARY pattern
    const isCanary = value.includes('CANARY');
    console.log(`  Contains "CANARY": ${isCanary ? '✅ YES' : '❌ NO'}`);

    // Pattern-specific checks
    switch(key) {
      case 'DATABASE_URL':
        try {
          const url = new URL(value);
          console.log(`  Protocol: ${url.protocol}`);
          console.log(`  Hostname: ${url.hostname}`);
          console.log(`  Database: ${url.pathname ? url.pathname.substring(1) : 'none'}`);

          // Check if it's likely a real database
          if (url.hostname.includes('localhost') || 
              url.hostname.includes('127.0.0.1') ||
              url.hostname === 'db.internal') {
            console.log(`  ⚠️  Host appears to be internal: ${url.hostname}`);
          }
        } catch (err) {
          console.log(`  ❌ Invalid URL: ${err.message}`);
        }
        break;

      case 'AWS_ACCESS_KEY_ID':
        // AWS key pattern: AKIA followed by 16 chars
        const awsPattern = /^AKIA[0-9A-Z]{16}$/;
        const cleanValue = value.replace('CANARY', '');
        const matchesPattern = awsPattern.test(cleanValue);
        console.log(`  Valid AWS pattern: ${matchesPattern ? '✅ YES' : '❌ NO'}`);
        console.log(`  Cleaned value: ${cleanValue}`);
        break;

      case 'AWS_SECRET_ACCESS_KEY':
        console.log(`  Length: ${value.length} characters`);
        console.log(`  Looks like secret: ${value.length >= 20 ? '✅ YES' : '⚠️  SHORT'}`);
        break;

      case 'ANTHROPIC_API_KEY':
        // Anthropic pattern: sk-ant- followed by alphanumeric
        const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]+$/;
        const anthClean = value.replace('CANARY', '');
        const anthValid = anthropicPattern.test(anthClean);
        console.log(`  Valid Anthropic pattern: ${anthValid ? '✅ YES' : '❌ NO'}`);
        console.log(`  Cleaned value: ${anthClean.substring(0, 20)}...`);
        break;

      case 'STRIPE_SECRET_KEY':
        // Stripe pattern: sk_live_ or sk_test_ followed by chars
        const stripePattern = /^(sk_live_|sk_test_|pk_live_|pk_test_)[a-zA-Z0-9_-]+$/;
        const stripeClean = value.replace('CANARY', '');
        const stripeValid = stripePattern.test(stripeClean);
        console.log(`  Valid Stripe pattern: ${stripeValid ? '✅ YES' : '❌ NO'}`);
        console.log(`  Type: ${stripeClean.startsWith('sk_live_') ? 'Live secret' : 
                   stripeClean.startsWith('sk_test_') ? 'Test secret' :
                   stripeClean.startsWith('pk_live_') ? 'Live publishable' :
                   stripeClean.startsWith('pk_test_') ? 'Test publishable' : 'Unknown'}`);
        break;

      case 'LOGFIRE_TOKEN':
        console.log(`  Length: ${value.length} characters`);
        // Logfire tokens are typically alphanumeric
        const isAlphanumeric = /^[a-zA-Z0-9_-]+$/.test(value.replace('CANARY', ''));
        console.log(`  Alphanumeric: ${isAlphanumeric ? '✅ YES' : '❌ NO'}`);
        break;

      default:
        console.log(`  Unknown credential type`);
    }
  });

