#!/usr/bin/env node

/**
 * Credential Verification Script
 * Tests connectivity and validity of credentials in .env.test
 */

const https = require('https');
const { exec } = require('child_process');

// Read environment variables from .env.test
const fs = require('fs');
const path = require('path');

function parseEnvFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
            const match = line.match(/^([^=]+)=(.*)$/);
            if (match) {
                const [, key, value] = match;
                envVars[key.trim()] = value.trim();
            }
        }
    });

    return envVars;
}

// Utility function to make HTTP requests
function makeRequest(url, options = {}) {
    return new Promise((resolve, reject) => {
        const req = https.request(url, options, (res) => {
            let data = '';
            res.on('data', (chunk) => data += chunk);
            res.on('end', () => resolve({ statusCode: res.statusCode, headers: res.headers, body: data }));
        });

        req.on('error', reject);
        req.setTimeout(10000, () => {
            req.destroy();
            reject(new Error('Request timeout'));
        });

        if (options.body) {
            req.write(options.body);
        }
        req.end();
    });
}

// Test database connectivity
async function testDatabaseConnection(dbUrl) {
    console.log('Testing database connection...');

    try {
        // Extract components from PostgreSQL URL
        const match = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
        if (!match) {
            return { valid: false, error: 'Invalid database URL format' };
        }

        const [, username, password, host, port, database] = match;

        console.log(`  Host: ${host}:${port}`);
        console.log(`  Database: ${database}`);
        console.log(`  Username: ${username}`);

        // Try to ping the host
        return new Promise((resolve) => {
            exec(`ping -c 1 ${host}`, (error) => {
                if (error) {
                    resolve({ 
                        valid: false, 
                        error: `Cannot reach host ${host}: ${error.message}`,
                        details: { host, port, database, username }
                    });
                } else {
                    resolve({
                        valid: true,
                        message: `Host ${host} is reachable`,
                        warning: 'NOTE: This only tests host connectivity, not database authentication',
                        details: { host, port, database, username }
                    });
                }
            });
        });

    } catch (error) {
        return { valid: false, error: `Database test failed: ${error.message}` };
    }
}

// Test AWS credentials
async function testAWSCredentials(accessKeyId, secretAccessKey) {
    console.log('Testing AWS credentials format...');

    // Check AWS Access Key ID format (should start with AKIA and be 20 chars)
    const isValidAccessKeyId = /^AKIA[0-9A-Z]{16,}$/.test(accessKeyId);
    const isValidSecretKey = secretAccessKey.length >= 40;

    if (!isValidAccessKeyId) {
        return { 
            valid: false, 
            error: 'Invalid AWS Access Key ID format. Should start with AKIA and be alphanumeric',
            value: accessKeyId
        };
    }

    if (!isValidSecretKey) {
        return {
            valid: false,
            error: 'AWS Secret Access Key appears too short',
            value: '***' + secretAccessKey.slice(-4)
        };
    }

    // Try a basic AWS API call (ListBuckets from S3)
    console.log('  Testing AWS S3 API (read-only operation)...');

    const date = new Date().toUTCString();
    const canonicalRequest = `GET\n/\n\nhost:s3.amazonaws.com\nx-amz-date:${date}\n\nhost;x-amz-date\nUNSIGNED-PAYLOAD`;
    const stringToSign = `AWS4-HMAC-SHA256\n${date}\n${date.slice(0, 8)}/us-east-1/s3/aws4_request\n${require('crypto').createHash('sha256').update(canonicalRequest).digest('hex')}`;

    return {
        valid: true,
        message: 'AWS credentials appear to be in valid format',
        warning: 'NOTE: This tests format only. Actual API calls would verify authentication',
        details: {
            accessKeyId: accessKeyId.slice(0, 8) + '...',
            secretKeyLength: secretAccessKey.length,
            formatValid: true
        }
    };
}

// Test Anthropic API key
async function testAnthropicAPI(key) {
    console.log('Testing Anthropic API key format...');

    // Check if it looks like a valid Anthropic key
    const isValidFormat = /^sk-ant-[a-zA-Z0-9_-]{40,}$/.test(key);

    if (!isValidFormat) {
        return {
            valid: false,
            error: 'Invalid Anthropic API key format',
            value: key.slice(0, 20) + '...'
        };
    }

    // Try to make a minimal API request
    console.log('  Making test request to Anthropic API...');

    try {
        const options = {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': key,
                'anthropic-version': '2023-06-01'
            },
            timeout: 10000
        };

        const requestBody = JSON.stringify({
            model: 'claude-3-haiku-20240307',
            max_tokens: 10,
            messages: [{ role: 'user', content: 'Hello' }]
        });

        const response = await makeRequest('https://api.anthropic.com/v1/messages', {
            ...options,
            headers: { ...options.headers, 'Content-Length': Buffer.byteLength(requestBody) }
        });

        if (response.statusCode === 401 || response.statusCode === 403) {
            return {
                valid: false,
                error: 'Anthropic API key is invalid or expired',
                statusCode: response.statusCode
            };
        }

        return {
            valid: true,
            message: 'Anthropic API key appears to be valid',
            statusCode: response.statusCode,
            details: { keyPrefix: key.slice(0, 20) + '...' }
        };

    } catch (error) {
        // If we get a timeout or connection error, the key might still be valid
        return {
            valid: true,
            warning: 'Could not verify key with API (network/timeout issue)',
            error: error.message,
            details: { keyPrefix: key.slice(0, 20) + '...' }
        };
    }
}

// Test Stripe API key
async function testStripeAPI(key) {
    console.log('Testing Stripe API key format...');

    // Check Stripe key format
    const isTestKey = key.startsWith('sk_test_');
    const isLiveKey = key.startsWith('sk_live_');
    const isValidFormat = (isTestKey || isLiveKey) && key.length > 20;

    if (!isValidFormat) {
        return {
            valid: false,
