        };
    }
}

// Test Logfire token
async function testLogfireToken(token) {
    console.log('Testing Logfire token format...');

    // Basic format check
    const isValidFormat = token.length > 20 && /^[A-Za-z0-9_-]+$/.test(token);

    if (!isValidFormat) {
        return {
            valid: false,
            error: 'Invalid Logfire token format',
            value: token.slice(0, 20) + '...'
        };
    }

    return {
