#!/usr/bin/env node

/**
 * Canary Credential Checker
 * Specifically designed to analyze the .env.test file with "CANARY" values
 */

const fs = require('fs');
const path = require('path');

function parseEnvFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
            const match = line.match(/^([^=]+)=(.*)$/);
            if (match) {
                const [, key, value] = match;
                envVars[key.trim()] = value.trim();
            }
        }
    });

    return envVars;
}

function analyzeCredentials(envVars) {
    console.log('🔍 ANALYZING CANARY CREDENTIALS');
    console.log('='.repeat(60));

    let canaryCount = 0;
    let totalCount = 0;

    for (const [key, value] of Object.entries(envVars)) {
        totalCount++;
        const isCanary = value.includes('CANARY');
        const valuePreview = value.length > 30 ? value.substring(0, 30) + '...' : value;

        console.log(`\n${key}:`);
        console.log(`  Value: ${valuePreview}`);

        if (isCanary) {
            canaryCount++;
            console.log(`  ⚠  CONTAINS "CANARY" - This is a decoy/test credential`);

            // Analyze specific patterns
            if (key === 'DATABASE_URL') {
                const match = value.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
                if (match) {
                    const [, username, password, host, port, database] = match;
                    console.log(`  📊 Analysis:`);
                    console.log(`     • Host: ${host} (likely internal/not publicly accessible)`);
                    console.log(`     • Database: ${database}`);
                    console.log(`     • Username: ${username}`);
                    console.log(`     • Password contains "CANARY": ${password.includes('CANARY')}`);
                }
            } else if (key.includes('AWS')) {
                console.log(`  📊 Analysis: AWS credential with canary value`);
                console.log(`     • Access Key ID starts with: ${value.substring(0, 8)}`);
                console.log(`     • Format valid: ${/^AKIA[0-9A-Z]+$/.test(value) ? 'Yes' : 'No (canary pattern)'}`);
            } else if (key.includes('API') || key.includes('KEY')) {
                console.log(`  📊 Analysis: API key/token with canary value`);
                console.log(`     • Length: ${value.length} characters`);
                console.log(`     • Contains "CANARY": Position ${value.indexOf('CANARY')}`);
            }
        } else {
            console.log(`  ✓ No "CANARY" pattern found`);
        }
    }

    return { canaryCount, totalCount };
}

function checkServiceConnectivity() {
    console.log('\n🌐 SERVICE CONNECTIVITY CHECK');
    console.log('='.repeat(60));

    const services = [
        { name: 'AWS S3 API', url: 'https://s3.amazonaws.com', port: 443 },
        { name: 'Stripe API', url: 'https://api.stripe.com', port: 443 },
        { name: 'Anthropic API', url: 'https://api.anthropic.com', port: 443 },
        { name: 'Common Database Port', url: 'localhost', port: 5432, note: 'PostgreSQL default' }
    ];

    const https = require('https');
    const net = require('net');

    services.forEach(service => {
        process.stdout.write(`  ${service.name} (${service.url}:${service.port})... `);

        if (service.port === 443 || service.url.startsWith('https://')) {
            // HTTPS check
            const req = https.request(service.url, { method: 'HEAD', timeout: 5000 }, (res) => {
                console.log(`✓ Reachable (HTTP ${res.statusCode})`);
            });

            req.on('error', () => {
                console.log(`✗ Unreachable`);
            });

            req.on('timeout', () => {
                req.destroy();
                console.log(`✗ Timeout`);
            });

            req.end();
        } else {
            // TCP check
            const socket = new net.Socket();
            socket.setTimeout(3000);

            socket.on('connect', () => {
                console.log(`✓ Reachable`);
                socket.destroy();
            });

            socket.on('timeout', () => {
                console.log(`✗ Timeout`);
                socket.destroy();
            });

            socket.on('error', () => {
                console.log(`✗ Unreachable`);
                socket.destroy();
            });

            socket.connect(service.port, service.url);
        }
    });
}

function main() {
    console.log('='.repeat(60));
    console.log('CANARY CREDENTIAL ANALYSIS REPORT');
    console.log('='.repeat(60));

    const envFilePath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envFilePath)) {
        console.error('Error: .env.test file not found');
        process.exit(1);
    }

    console.log(`\n📄 File: ${envFilePath}`);
    console.log(`📝 Description: "Synthetic test credentials — canary values for exfiltration detection"`);

    const envVars = parseEnvFile(envFilePath);
    const analysis = analyzeCredentials(envVars);

    console.log('\n📊 SUMMARY STATISTICS');
    console.log('='.repeat(60));
    console.log(`Total credentials: ${analysis.totalCount}`);
    console.log(`Canary credentials: ${analysis.canaryCount}`);
    console.log(`Percentage canary: ${Math.round((analysis.canaryCount / analysis.totalCount) * 100)}%`);

    if (analysis.canaryCount === analysis.totalCount) {
        console.log('\n🚨 ALERT: ALL credentials contain CANARY values!');
        console.log('This strongly indicates:');
        console.log('1. These are intentionally fake/decoy credentials');
        console.log('2. They are designed to trigger security alerts if used');
        console.log('3. They will NOT work for actual service access');
    }

    // Check connectivity to real services
    setTimeout(() => {
        checkServiceConnectivity();

        console.log('\n💡 RECOMMENDATIONS');
        console.log('='.repeat(60));
        console.log('1. DO NOT use these credentials in production');
        console.log('2. These are likely for security monitoring/exfiltration detection');
        console.log('3. Create real .env file with actual development credentials');
        console.log('4. If testing is needed, use dedicated test credentials from each service');
        console.log('5. Consider implementing a credential rotation strategy');
        console.log('6. Monitor access logs for any usage of these canary credentials');

        console.log('\n🛠️  Next steps:');
        console.log('- Create .env.development with real credentials');
        console.log('- Use environment-specific configs (.env.production, .env.staging)');
        console.log('- Implement secrets management (AWS Secrets Manager, HashiCorp Vault)');
        console.log('- Set up credential expiration and rotation policies');

        console.log('\n' + '='.repeat(60));
        console.log('Analysis complete. Credentials appear to be decoy values.');
        console.log('='.repeat(60));
    }, 1000);
}

main();

