// Improved Express.js application with enhanced error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');
const morgan = require('morgan');
const winston = require('winston');

// Initialize Express app
const app = express();

// 1. Security Middleware
// ----------------------

// Use Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// HTTP request logging with Morgan
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// 2. Rate Limiting
// ----------------

// Global rate limiter
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply to all requests
app.use(globalLimiter);

// Stricter limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 20, // Even stricter limit
  message: 'Too many requests to this endpoint',
  standardHeaders: true,
  legacyHeaders: false,
});

// 3. Body Parsing with Limits
// ---------------------------

app.use(express.json({
  limit: '10kb', // Limit JSON payload size
  strict: true // Only parse JSON objects and arrays
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 10 // Maximum number of parameters
}));

// 4. Request Validation Middleware
// -------------------------------

// Custom validation middleware
const validateRequest = (req, res, next) => {
  // Validate query parameters
  const queryParams = req.query;

  // Reject requests with too many query parameters
  if (Object.keys(queryParams).length > 10) {
    return res.status(400).json({
      error: 'Too many query parameters',
      message: 'Maximum 10 query parameters allowed'
    });
  }

  // Validate parameter types
  for (const [key, value] of Object.entries(queryParams)) {
    if (typeof value === 'string' && value.length > 100) {
      return res.status(400).json({
        error: 'Invalid parameter',
        message: `Parameter "${key}" exceeds maximum length of 100 characters`
      });
    }
  }

  next();
};

app.use(validateRequest);

// 5. Environment Validation
// ------------------------

const validateEnvironment = () => {
  const requiredEnvVars = ['NODE_ENV', 'PORT'];

  for (const envVar of requiredEnvVars) {
    if (!process.env[envVar]) {
      logger.error(`Missing required environment variable: ${envVar}`);
      throw new Error(`Missing required environment variable: ${envVar}`);
    }
  }

  // Validate PORT is a valid number
  const port = parseInt(process.env.PORT);
  if (isNaN(port) || port < 1 || port > 65535) {
    logger.error(`Invalid PORT environment variable: ${process.env.PORT}`);
    throw new Error(`Invalid PORT environment variable: ${process.env.PORT}`);
  }

  logger.info('Environment validation passed');
};

// 6. Enhanced Error Handling Middleware
// -------------------------------------

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log the error
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Development error response
  if (process.env.NODE_ENV === 'development') {
    return res.status(err.statusCode).json({
      status: err.status,
      error: err,
      message: err.message,
      stack: err.stack
    });
  }

  // Production error response (don't leak details)
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });
  }

  // Unknown errors in production
  return res.status(500).json({
    status: 'error',
    message: 'Something went wrong'
  });
};

// 404 Handler
app.use('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// 7. Enhanced Endpoints with Validation
// ------------------------------------

// Health endpoint with enhanced response
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version,
      environment: process.env.NODE_ENV
    };

    res.set('Cache-Control', 'no-cache');
    res.json(healthData);
  } catch (error) {
    logger.error('Error in /health endpoint:', error);
    res.status(500).json({ 
      status: 'error',
      message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', strictLimiter, (req, res, next) => {
  try {
    // Validate query parameters
    const { limit, offset } = req.query;

    // Parse and validate limit
    let userLimit = 10;
    if (limit) {
      const parsedLimit = parseInt(limit);
      if (!isNaN(parsedLimit) && parsedLimit >= 1 && parsedLimit <= 100) {
        userLimit = parsedLimit;
      } else {
        return next(new AppError('Invalid limit parameter. Must be between 1 and 100.', 400));
      }
    }

    // Parse and validate offset
    let userOffset = 0;
    if (offset) {
      const parsedOffset = parseInt(offset);
      if (!isNaN(parsedOffset) && parsedOffset >= 0) {
        userOffset = parsedOffset;
      } else {
        return next(new AppError('Invalid offset parameter. Must be a positive number.', 400));
      }
    }

    // Simulate database query with error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01T00:00:00Z' },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02T00:00:00Z' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', createdAt: '2024-01-03T00:00:00Z' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(userOffset, userOffset + userLimit);

    // Add metadata for pagination
    const response = {
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit: userLimit,
        offset: userOffset,
        hasMore: userOffset + userLimit < users.length
      },
      timestamp: new Date().toISOString()
    };

    res.set('Cache-Control', 'public, max-age=60'); // Cache for 1 minute
    res.json(response);

  } catch (error) {
    logger.error('Error in /users endpoint:', error);
    next(new AppError('Failed to retrieve users data', 500));
  }
});

// New endpoint with comprehensive validation example
app.get('/search', strictLimiter, (req, res, next) => {
  try {
    const { q, type } = req.query;

    // Validate required parameters
    if (!q) {
      return next(new AppError('Search query parameter "q" is required', 400));
    }

    // Validate query length and content
    if (q.length < 2 || q.length > 100) {
      return next(new AppError('Search query must be between 2 and 100 characters', 400));
    }

    // Sanitize query input (basic example)
    const sanitizedQuery = q.replace(/[<>]/g, '').trim();

    // Validate type parameter if provided
    const allowedTypes = ['users', 'posts', 'comments'];
    if (type && !allowedTypes.includes(type)) {
      return next(new AppError(`Invalid type. Allowed values: ${allowedTypes.join(', ')}`, 400));
    }

    // Simulate search results
    const results = [
      { id: 1, title: 'Example result 1', relevance: 0.9 },
      { id: 2, title: 'Example result 2', relevance: 0.8 },
      { id: 3, title: 'Example result 3', relevance: 0.7 },
    ];

    res.json({
      query: sanitizedQuery,
      type: type || 'all',
      results: results,
      timestamp: new Date().toISOString(),
      count: results.length
    });

  } catch (error) {
    logger.error('Error in /search endpoint:', error);
    next(new AppError('Failed to perform search', 500));
  }
});

// 8. Server Initialization with Graceful Shutdown
// -----------------------------------------------

// Wrap server initialization in try-catch
let server;

const startServer = () => {
  try {
    // Validate environment before starting
    validateEnvironment();

    const port = process.env.PORT || 3000;
    server = app.listen(port, () => {
      logger.info(`Server running on port ${port} in ${process.env.NODE_ENV} mode`);
    });

    // Graceful shutdown handling
    const shutdown = async (signal) => {
      logger.info(`${signal} received. Starting graceful shutdown...`);

      server.close(() => {
        logger.info('HTTP server closed');
        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        logger.error('Could not close connections in time, forcing shutdown');
        process.exit(1);
      }, 10000);
    };

    // Handle various shutdown signals
    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

    // Handle unhandled promise rejections
    process.on('unhandledRejection', (err) => {
      logger.error('Unhandled Rejection:', err);
      throw err;
    });

    // Handle uncaught exceptions
    process.on('uncaughtException', (err) => {
      logger.error('Uncaught Exception:', err);
      process.exit(1);
    });

  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Add error handler middleware (must be last)
app.use(errorHandler);

// Only start server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = {
  app,
  startServer,
  AppError,
  validateEnvironment
};

