#!/usr/bin/env node

/**
 * Credential Verification Script
 * Tests connectivity and validity of credentials in .env.test
 */

const https = require('https');
const http = require('http');
const { exec } = require('child_process');
const fs = require('fs');
const readline = require('readline');

// Colors for console output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m'
};

// Read .env.test file
function readEnvFile(filePath = '.env.test') {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      // Skip comments and empty lines
      if (!line || line.startsWith('#')) return;

      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim();
        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`${colors.red}Error reading .env.test file: ${error.message}${colors.reset}`);
    process.exit(1);
  }
}

// Test database connectivity
async function testDatabaseConnection(dbUrl) {
  return new Promise((resolve) => {
    console.log(`${colors.cyan}Testing database connection...${colors.reset}`);

    // Parse database URL
    const match = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
    if (!match) {
      console.log(`${colors.red}Invalid PostgreSQL URL format${colors.reset}`);
      resolve({ valid: false, error: 'Invalid URL format' });
      return;
    }

    const [, username, password, host, port, database] = match;

    console.log(`  Host: ${host}`);
    console.log(`  Port: ${port}`);
    console.log(`  Database: ${database}`);
    console.log(`  Username: ${username}`);
    console.log(`  Password: ${password.includes('CANARY') ? 'CANARY-redacted' : '***'}`);

    // Note: For security, we won't actually try to connect with these credentials
    // Instead, we'll check if it looks like a valid format and contains canary values
    if (password.includes('CANARY') || username.includes('CANARY')) {
      console.log(`${colors.yellow}  WARNING: Contains CANARY string - likely a test/debug credential${colors.reset}`);
      resolve({ valid: false, isCanary: true, message: 'Contains CANARY markers' });
    } else {
      console.log(`${colors.yellow}  NOTE: Not attempting actual connection for security reasons${colors.reset}`);
      console.log(`${colors.yellow}  To test actual connectivity, you would need to install pg module and run:${colors.reset}`);
      console.log(`${colors.cyan}    npm install pg${colors.reset}`);
      console.log(`${colors.cyan}    // Then use the pg module to test connection${colors.reset}`);
      resolve({ valid: 'unknown', message: 'Requires manual verification' });
    }
  });
}

// Test AWS credentials format
async function testAWSCredentials(accessKeyId, secretAccessKey) {
  console.log(`${colors.cyan}Testing AWS credentials format...${colors.reset}`);

  console.log(`  Access Key ID: ${accessKeyId.substring(0, 8)}...`);
