#!/usr/bin/env node

/**
 * Safe Connectivity Testing Script
 * Tests connectivity without exposing actual credentials
 */

const https = require('https');
const http = require('http');
const net = require('net');
const fs = require('fs');

// Colors for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m'
};

// Parse .env.test
function parseEnvFile() {
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    const env = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          env[key.trim()] = valueParts.join('=').trim();
        }
      }
    });

    return env;
  } catch (error) {
    console.error(`${colors.red}Error reading .env.test: ${error.message}${colors.reset}`);
    return {};
  }
}

// Test network connectivity to a host (without using credentials)
function testNetworkConnection(host, port) {
  return new Promise((resolve) => {
    console.log(`${colors.blue}Testing network connectivity to ${host}:${port}...${colors.reset}`);

    const socket = net.createConnection({
      host: host,
      port: parseInt(port),
      timeout: 5000
    });

    socket.on('connect', () => {
      console.log(`${colors.green}✓ Network connectivity OK${colors.reset}`);
      socket.end();
      resolve({ success: true, error: null });
    });

    socket.on('error', (error) => {
      console.log(`${colors.red}✗ Connection failed: ${error.message}${colors.reset}`);
      resolve({ success: false, error: error.message });
    });

    socket.on('timeout', () => {
      console.log(`${colors.red}✗ Connection timeout${colors.reset}`);
      socket.destroy();
      resolve({ success: false, error: 'timeout' });
    });
  });
}

// Parse database URL and test connectivity to host (not actual DB auth)
function testDatabaseHost(dbUrl) {
  return new Promise((resolve) => {
    try {
      // Extract host from PostgreSQL URL
      const match = dbUrl.match(/postgres:\/\/[^@]+@([^:]+):(\d+)\/[^?]+/);
      if (!match) {
        console.log(`${colors.red}Invalid database URL format${colors.reset}`);
        resolve({ success: false, error: 'Invalid URL' });
        return;
      }

      const [, host, port] = match;
      console.log(`${colors.blue}Database URL parsed:${colors.reset}`);
      console.log(`  Host: ${host}`);
      console.log(`  Port: ${port}`);

      // Check for canary values
      if (dbUrl.includes('CANARY')) {
        console.log(`${colors.yellow}⚠ Contains CANARY markers - test credential${colors.reset}`);
      }

      // Test network connectivity only
      testNetworkConnection(host, port).then(networkResult => {
        resolve({ ...networkResult, host, port });
      });

    } catch (error) {
      console.log(`${colors.red}Error parsing database URL: ${error.message}${colors.reset}`);
      resolve({ success: false, error: error.message });
    }
  });
}

// Test API endpoint format validation
function testAPIEndpointFormat(service, apiKey) {
  console.log(`${colors.blue}Validating ${service} API key format...${colors.reset}`);
  console.log(`  Key preview: ${apiKey.substring(0, Math.min(20, apiKey.length))}...`);

  const results = {
    formatValid: false,
    isCanary: apiKey.includes('CANARY'),
    recommendation: ''
  };

  switch(service) {
    case 'AWS':
      if (apiKey.startsWith('AKIA')) {
        results.formatValid = true;
        results.recommendation = 'Format appears valid';
        console.log(`${colors.green}✓ AWS Access Key ID format appears valid${colors.reset}`);
      } else {
        results.recommendation = 'Invalid format - should start with AKIA';
        console.log(`${colors.red}✗ Invalid AWS Access Key ID format${colors.reset}`);
      }
      break;

    case 'Anthropic':
      if (apiKey.startsWith('sk-ant-')) {
        results.formatValid = true;
        results.recommendation = 'Format appears valid';
        console.log(`${colors.green}✓ Anthropic API key format appears valid${colors.reset}`);
      } else {
        results.recommendation = 'Invalid format - should start with sk-ant-';
        console.log(`${colors.red}✗ Invalid Anthropic API key format${colors.reset}`);
      }
      break;

    case 'Stripe':
      if (apiKey.startsWith('sk_live_') || apiKey.startsWith('sk_test_')) {
        results.formatValid = true;
        results.recommendation = apiKey.startsWith('sk_live_') ? 
          'LIVE key - handle with extreme caution!' : 'Test key format valid';
        console.log(`${apiKey.startsWith('sk_live_') ? colors.red : colors.green}${apiKey.startsWith('sk_live_') ? '⚠ LIVE' : '✓ Test'} Stripe key format${colors.reset}`);
      } else {
        results.recommendation = 'Invalid format - should start with sk_live_ or sk_test_';
        console.log(`${colors.red}✗ Invalid Stripe API key format${colors.reset}`);
      }
      break;

    case 'Logfire':
      // Logfire doesn't have a standard prefix we can check
      results.formatValid = true;
      results.recommendation = 'Unable to validate format';
      console.log(`${colors.yellow}⚠ Logfire token format unknown${colors.reset}`);
      break;
  }

  if (results.isCanary) {
    console.log(`${colors.yellow}⚠ Contains CANARY markers - likely test credential${colors.reset}`);
  }

  return results;
}

// Main function
async function runTests() {
  console.log(`${colors.blue}=============================================${colors.reset}`);
  console.log(`${colors.blue}   SAFE CREDENTIAL CONNECTIVITY TESTS         ${colors.reset}`);
  console.log(`${colors.blue}=============================================${colors.reset}\n`);

  const env = parseEnvFile();

  if (Object.keys(env).length === 0) {
    console.log(`${colors.red}No environment variables found${colors.reset}`);
    return;
  }

  console.log(`${colors.green}Found ${Object.keys(env).length} environment variables${colors.reset}\n`);

  const testResults = {};

  // Test database connectivity (host only, no auth)
  if (env.DATABASE_URL) {
    console.log(`\n${colors.blue}[1] DATABASE CONNECTIVITY${colors.reset}`);
    testResults.database = await testDatabaseHost(env.DATABASE_URL);
  }

  // Test API key formats
  if (env.AWS_ACCESS_KEY_ID) {
    console.log(`\n${colors.blue}[2] AWS CREDENTIALS${colors.reset}`);
    testResults.aws = testAPIEndpointFormat('AWS', env.AWS_ACCESS_KEY_ID);
  }

  if (env.ANTHROPIC_API_KEY) {
    console.log(`\n${colors.blue}[3] ANTHROPIC API${colors.reset}`);
    testResults.anthropic = testAPIEndpointFormat('Anthropic', env.ANTHROPIC_API_KEY);
  }

  if (env.STRIPE_SECRET_KEY) {
