  }

  // Summary
  console.log(`\n${colors.blue}=============================================${colors.reset}`);
  console.log(`${colors.blue}               TEST SUMMARY                   ${colors.reset}`);
  console.log(`${colors.blue}=============================================${colors.reset}\n`);

  const canaryCredentials = Object.entries(env).filter(([, value]) => 
    value.includes('CANARY')
  ).length;

  console.log(`${colors.cyan}Findings:${colors.reset}`);
  console.log(`  Total credentials: ${Object.keys(env).length}`);
  console.log(`  Credentials with CANARY markers: ${canaryCredentials}`);
  console.log(`  Without CANARY markers: ${Object.keys(env).length - canaryCredentials}`);

  console.log(`\n${colors.cyan}Security Assessment:${colors.reset}`);

  if (canaryCredentials === Object.keys(env).length) {
    console.log(`${colors.green}  ✓ ALL credentials appear to be test/synthetic${colors.reset}`);
    console.log(`${colors.green}  ✓ Low risk - likely intentional canary values${colors.reset}`);
  } else if (canaryCredentials > 0) {
    console.log(`${colors.yellow}  ⚠ Mixed set - some test, some potentially real${colors.reset}`);
    console.log(`${colors.yellow}  ⚠ Review non-canary credentials carefully${colors.reset}`);
  } else {
    console.log(`${colors.red}  ✗ NO canary markers found${colors.reset}`);
    console.log(`${colors.red}  ✗ These may be REAL production credentials${colors.reset}`);
    console.log(`${colors.red}  ✗ HIGH SECURITY RISK if exposed${colors.reset}`);
  }

  console.log(`\n${colors.cyan}Recommended Actions:${colors.reset}`);

  if (canaryCredentials === Object.keys(env).length) {
    console.log(`  1. Keep .env.test for development/testing`);
    console.log(`  2. Create separate .env file for real credentials`);
    console.log(`  3. Add .env to .gitignore`);
  } else {
