    console.log(`  2. Replace with test credentials for development`);
    console.log(`  3. Store real credentials in secure secret manager`);
    console.log(`  4. Ensure .env.test is NOT committed to git`);
  }

  console.log(`\n${colors.blue}=============================================${colors.reset}\n`);
}

// Execute
if (require.main === module) {
  runTests().catch(error => {
    console.error(`${colors.red}Error: ${error.message}${colors.reset}`);
    process.exit(1);
  });
}

module.exports = {
