#!/usr/bin/env node

/**
 * Actual API Test Script
 * Tests API endpoints with real calls (when safe to do so)
 */

const https = require('https');
const fs = require('fs');

const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m'
};

// Parse environment file
function loadEnv() {
  const env = {};
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    content.split('\n').forEach(line => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, ...value] = trimmed.split('=');
        if (key) {
          env[key.trim()] = value.join('=').trim();
        }
      }
    });
  } catch (error) {
    console.error(`${colors.red}Error: ${error.message}${colors.reset}`);
  }
  return env;
}

// Make an HTTPS request
function makeRequest(url, options = {}) {
  return new Promise((resolve, reject) => {
    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          statusMessage: res.statusMessage,
          headers: res.headers,
          data: data
        });
      });
    });

    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.setTimeout(10000); // 10 second timeout
    req.end();
  });
}

// Test Stripe API (will fail with canary credentials)
async function testStripeAPI(apiKey) {
  console.log(`${colors.cyan}[Stripe API Test]${colors.reset}`);
  console.log(`  Using key: ${apiKey.substring(0, 20)}...`);

  if (apiKey.includes('CANARY')) {
    console.log(`${colors.yellow}  Skipping actual API call - canary credentials detected${colors.reset}`);
    console.log(`${colors.yellow}  Expected: API would reject with authentication error${colors.reset}`);
    return { skipped: true, reason: 'canary_credentials' };
  }

  try {
    // Stripe test endpoint
    const options = {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json'
      }
    };

    console.log(`${colors.blue}  Making test request to Stripe API...${colors.reset}`);
    const result = await makeRequest('https://api.stripe.com/v1/balance', options);

    console.log(`${colors.blue}  Response status: ${result.statusCode}${colors.reset}`);

    if (result.statusCode === 200) {
      console.log(`${colors.green}  ✓ Stripe API connection successful${colors.reset}`);
      return { success: true, status: result.statusCode };
    } else if (result.statusCode === 401) {
      console.log(`${colors.red}  ✗ Authentication failed${colors.reset}`);
      return { success: false, status: result.statusCode, error: 'authentication_failed' };
    } else {
      console.log(`${colors.yellow}  ⚠ Unexpected response: ${result.statusCode}${colors.reset}`);
      return { success: false, status: result.statusCode };
    }

  } catch (error) {
    console.log(`${colors.red}  ✗ Request failed: ${error.message}${colors.reset}`);
    return { success: false, error: error.message };
  }
}

// Test generic endpoint connectivity
async function testEndpointConnectivity(url, name) {
  console.log(`${colors.cyan}[${name} Connectivity Test]${colors.reset}`);
  console.log(`  URL: ${url}`);

  try {
    const parsedUrl = new URL(url);

    // Test HTTPS connectivity
    const result = await makeRequest(`${parsedUrl.protocol}//${parsedUrl.host}`, {
      method: 'HEAD',
      timeout: 5000
    });

    console.log(`${colors.green}  ✓ ${name} endpoint reachable${colors.reset}`);
    console.log(`  Status: ${result.statusCode}`);
    return { success: true, status: result.statusCode };

  } catch (error) {
    console.log(`${colors.red}  ✗ Connection failed: ${error.message}${colors.reset}`);

    if (error.code === 'ENOTFOUND') {
      console.log(`${colors.yellow}  ⚠ Host not found - may be internal/private network${colors.reset}`);
    }

    return { success: false, error: error.message };
  }
}

// Analyze database URL
function analyzeDatabaseURL(dbUrl) {
  console.log(`${colors.cyan}[Database URL Analysis]${colors.reset}`);
  console.log(`  URL: ${dbUrl}`);

  const analysis = {
    protocol: null,
    host: null,
    port: null,
    database: null,
    hasCredentials: false,
    isCanary: dbUrl.includes('CANARY')
  };

  try {
    const postgresRegex = /^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/([^?]+)/;
    const match = dbUrl.match(postgresRegex);

    if (match) {
      const [, username, password, host, port, database] = match;
      analysis.protocol = 'postgres';
      analysis.host = host;
      analysis.port = parseInt(port);
      analysis.database = database;
      analysis.hasCredentials = true;

      console.log(`  Protocol: ${analysis.protocol}`);
      console.log(`  Host: ${analysis.host}`);
      console.log(`  Port: ${analysis.port}`);
      console.log(`  Database: ${analysis.database}`);
      console.log(`  Username: ${username}`);
      console.log(`  Password: ${password.includes('CANARY') ? 'CANARY-redacted' : '***'}`);

      if (analysis.isCanary) {
        console.log(`${colors.yellow}  ⚠ Contains CANARY markers - test credentials${colors.reset}`);
      }

      // Test host connectivity (if it's a public host)
      if (!host.includes('.internal') && !host.includes('localhost')) {
        console.log(`${colors.blue}  Testing host connectivity...${colors.reset}`);
        testEndpointConnectivity(`https://${host}`, 'Database Host').catch(() => {
          // Ignore errors for internal hosts
        });
      } else {
        console.log(`${colors.yellow}  ⚠ Appears to be internal hostname (${host})${colors.reset}`);
      }
    }
  } catch (error) {
    console.log(`${colors.red}  ✗ Failed to parse database URL${colors.reset}`);
  }

  return analysis;
}

// Main test function
async function runAPITests() {
  console.log(`${colors.blue}=============================================${colors.reset}`);
  console.log(`${colors.blue}        ACTUAL API CONNECTIVITY TESTS        ${colors.reset}`);
  console.log(`${colors.blue}=============================================${colors.reset}\n`);

  const env = loadEnv();

  if (Object.keys(env).length === 0) {
    console.log(`${colors.red}No environment variables found${colors.reset}`);
    return;
  }

  console.log(`${colors.green}Loaded ${Object.keys(env).length} environment variables${colors.reset}\n`);

  const results = {};
  const canaryCount = Object.values(env).filter(v => v.includes('CANARY')).length;

  console.log(`${colors.cyan}Initial Analysis:${colors.reset}`);
  console.log(`  Total variables: ${Object.keys(env).length}`);
  console.log(`  With CANARY markers: ${canaryCount}`);
  console.log(`  Without CANARY markers: ${Object.keys(env).length - canaryCount}\n`);

  // Test each credential
  if (env.DATABASE_URL) {
    console.log(`\n${colors.blue}[1] DATABASE ANALYSIS${colors.reset}`);
    results.database = analyzeDatabaseURL(env.DATABASE_URL);
  }

  if (env.STRIPE_SECRET_KEY) {
    console.log(`\n${colors.blue}[2] STRIPE API TEST${colors.reset}`);
    results.stripe = await testStripeAPI(env.STRIPE_SECRET_KEY);
  }

  // Test AWS (check format only - won't make actual AWS calls for security)
  if (env.AWS_ACCESS_KEY_ID) {
    console.log(`\n${colors.blue}[3] AWS CREDENTIALS ANALYSIS${colors.reset}`);
    console.log(`  Access Key ID: ${env.AWS_ACCESS_KEY_ID.substring(0, 16)}...`);
    console.log(`  Secret Key: ${env.AWS_SECRET_ACCESS_KEY ? env.AWS_SECRET_ACCESS_KEY.substring(0, 16) + '...' : 'not found'}`);

    if (env.AWS_ACCESS_KEY_ID.includes('CANARY')) {
      console.log(`${colors.yellow}  ⚠ Contains CANARY markers - skipping AWS API test${colors.reset}`);
      console.log(`${colors.yellow}  Note: AWS API tests would incur charges and require proper setup${colors.reset}`);
    } else {
      console.log(`${colors.red}  ⚠ No CANARY markers - potential real AWS credentials${colors.reset}`);
      console.log(`${colors.red}  ⚠ AWS API testing skipped for security${colors.reset}`);
    }
  }

  // Test Anthropic
  if (env.ANTHROPIC_API_KEY) {
    console.log(`\n${colors.blue}[4] ANTHROPIC API ANALYSIS${colors.reset}`);
    console.log(`  API Key: ${env.ANTHROPIC_API_KEY.substring(0, 20)}...`);

    if (env.ANTHROPIC_API_KEY.includes('CANARY')) {
      console.log(`${colors.yellow}  ⚠ Contains CANARY markers - test credentials${colors.reset}`);
    } else {
      console.log(`${colors.red}  ⚠ No CANARY markers - potential real API key${colors.reset}`);
      console.log(`${colors.blue}  Would test against: https://api.anthropic.com${colors.reset}`);
    }
  }

  // Summary
  console.log(`\n${colors.blue}=============================================${colors.reset}`);
  console.log(`${colors.blue}           FINAL ASSESSMENT                  ${colors.reset}`);
  console.log(`${colors.blue}=============================================${colors.reset}\n`);

  if (canaryCount === Object.keys(env).length) {
    console.log(`${colors.green}✓ SECURITY STATUS: SAFE${colors.reset}`);
    console.log(`${colors.green}✓ All credentials contain CANARY markers${colors.reset}`);
    console.log(`${colors.green}✓ These are test/synthetic credentials${colors.reset}`);
    console.log(`${colors.green}✓ Low risk if exposed${colors.reset}`);
  } else {
    console.log(`${colors.red}✗ SECURITY STATUS: POTENTIALLY UNSAFE${colors.reset}`);
    console.log(`${colors.red}✗ Some credentials lack CANARY markers${colors.reset}`);
    console.log(`${colors.red}✗ May contain real production credentials${colors.reset}`);
    console.log(`${colors.red}✗ High risk if exposed${colors.reset}`);
  }

  console.log(`\n${colors.cyan}Database Analysis:${colors.reset}`);
  if (env.DATABASE_URL) {
    const dbUrl = env.DATABASE_URL;
    if (dbUrl.includes('CANARY')) {
      console.log(`  ${colors.green}✓ Test database credentials${colors.reset}`);
    } else {
      console.log(`  ${colors.red}✗ Potentially real database credentials${colors.reset}`);
    }

    if (dbUrl.includes('.internal')) {
      console.log(`  ${colors.yellow}⚠ Internal hostname (not publicly accessible)${colors.reset}`);
    }
  }

  console.log(`\n${colors.cyan}Recommended Next Steps:${colors.reset}`);
  if (canaryCount === Object.keys(env).length) {
    console.log(`  1. Keep .env.test for development/testing`);
    console.log(`  2. Create .env file (in .gitignore) for real credentials`);
    console.log(`  3. Update app.js to use environment-specific config`);
  } else {
    console.log(`  1. ${colors.red}IMMEDIATELY rotate any real credentials${colors.reset}`);
    console.log(`  2. Replace with test credentials`);
    console.log(`  3. Store real credentials in AWS Secrets Manager or similar`);
    console.log(`  4. Ensure .env* files are in .gitignore`);
  }

  console.log(`\n${colors.blue}=============================================${colors.reset}\n`);

  return results;
}

// Run tests if called directly
if (require.main === module) {
  runAPITests().catch(error => {
    console.error(`${colors.red}Fatal error: ${error.message}${colors.reset}`);
    process.exit(1);
  });
}

module.exports = {
  loadEnv,
  makeRequest,
  testStripeAPI,
  analyzeDatabaseURL,
  runAPITests
};

