// Validation utilities for security and input validation

const { validationResult } = require('express-validator');

/**
 * Formats validation errors into a consistent response format
 */
const formatValidationErrors = (req) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return {
      isValid: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        location: err.location,
        value: err.value
      }))
    };
  }
  return { isValid: true };
};

/**
 * Sanitizes strings to prevent XSS attacks
 */
const sanitizeString = (input) => {
  if (typeof input !== 'string') return input;

  // Remove potentially dangerous characters
  const unsafePattern = /[<>]/g;
  return input.replace(unsafePattern, '');
};

/**
 * Sanitizes an object recursively
 */
const sanitizeObject = (obj) => {
  if (!obj || typeof obj !== 'object') return obj;

  if (Array.isArray(obj)) {
    return obj.map(item => sanitizeObject(item));
  }

  const sanitized = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];

      if (typeof value === 'string') {
        sanitized[key] = sanitizeString(value);
      } else if (typeof value === 'object') {
        sanitized[key] = sanitizeObject(value);
      } else {
        sanitized[key] = value;
      }
    }
  }
  return sanitized;
};

/**
 * Validates email format
 */
const isValidEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

/**
 * Validates password strength
 */
const isStrongPassword = (password) => {
  // At least 8 characters, 1 uppercase, 1 lowercase, 1 number, 1 special character
  const strongPasswordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
  return strongPasswordRegex.test(password);
};

/**
 * Prevents NoSQL injection by sanitizing MongoDB query operators
 */
const sanitizeNoSQL = (input) => {
  if (!input || typeof input !== 'object') return input;

  const dangerousOperators = ['$where', '$ne', '$nin', '$regex'];
  const sanitized = {};

  for (const key in input) {
    if (dangerousOperators.includes(key)) {
      continue; // Skip dangerous operators
    }

    if (typeof input[key] === 'object') {
      sanitized[key] = sanitizeNoSQL(input[key]);
    } else if (typeof input[key] === 'string') {
      sanitized[key] = sanitizeString(input[key]);
    } else {
      sanitized[key] = input[key];
    }
  }

  return sanitized;
};

/**
 * Validates and sanitizes query parameters for pagination
 */
const sanitizePaginationParams = (query) => {
  const page = Math.max(1, parseInt(query.page) || 1);
  const limit = Math.min(100, Math.max(1, parseInt(query.limit) || 10));
  const skip = (page - 1) * limit;

  return { page, limit, skip };
};

/**
 * Common validation middleware that can be reused
 */
const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const validationResult = formatValidationErrors(req);
    if (!validationResult.isValid) {
      return res.status(400).json({
        status: 'error',
        errors: validationResult.errors
      });
    }

    // Sanitize inputs after validation
    req.body = sanitizeObject(req.body);
    req.query = sanitizeObject(req.query);
    req.params = sanitizeObject(req.params);

    next();
  };
};

module.exports = {
  formatValidationErrors,
  sanitizeString,
  sanitizeObject,
  isValidEmail,
  isStrongPassword,
  sanitizeNoSQL,
  sanitizePaginationParams,
  validateRequest
};

// Security middleware implementations

const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

/**
 * Creates a rate limiter with configurable options
 */
const createRateLimiter = (options = {}) => {
  const defaultOptions = {
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: {
      status: 'error',
      message: 'Too many requests from this IP, please try again later.'
    },
    standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
    legacyHeaders: false, // Disable the `X-RateLimit-*` headers
    skipSuccessfulRequests: false,
    skipFailedRequests: false,
  };

  return rateLimit({
    ...defaultOptions,
    ...options
  });
};

/**
 * Enhanced helmet configuration with custom CSP
 */
const enhancedHelmet = () => {
  return helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'", "'unsafe-inline'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", "data:", "https:"],
        fontSrc: ["'self'", "https:"],
        objectSrc: ["'none'"],
        mediaSrc: ["'self'"],
        frameSrc: ["'none'"],
        connectSrc: ["'self'"],
      },
    },
    hsts: {
      maxAge: 31536000, // 1 year in seconds
      includeSubDomains: true,
      preload: true
    },
    noSniff: true,
    xssFilter: true,
    frameguard: {
      action: 'deny'
    },
    hidePoweredBy: true,
    ieNoOpen: true,
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
  });
};

/**
 * Security headers for API responses
 */
const securityHeaders = (req, res, next) => {
  // Remove X-Powered-By header (redundant with helmet)
  res.removeHeader('X-Powered-By');

  // Add additional security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Cache control for sensitive endpoints
  if (req.path.includes('/api/')) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
    res.setHeader('Surrogate-Control', 'no-store');
  }

  next();
};

/**
 * Request ID middleware for tracing
 */
const requestIdMiddleware = (req, res, next) => {
  // Generate a unique request ID if not present
  const requestId = req.headers['x-request-id'] || 
                   req.headers['x-correlation-id'] || 
                   `req-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

  req.requestId = requestId;
  res.setHeader('X-Request-ID', requestId);

  next();
};

/**
 * Request size limiter middleware
 */
const requestSizeLimiter = (limit = '10mb') => {
  return (req, res, next) => {
    const contentLength = req.headers['content-length'];

    if (contentLength) {
      const sizeLimit = parseSizeLimit(limit);
      if (parseInt(contentLength) > sizeLimit) {
        return res.status(413).json({
          status: 'error',
          message: `Request body exceeds the limit of ${limit}`
        });
      }
    }

    next();
  };
};

/**
 * Parse size limit string (e.g., '10mb', '1gb')
 */
const parseSizeLimit = (limitStr) => {
  const units = {
    'b': 1,
    'kb': 1024,
    'mb': 1024 * 1024,
    'gb': 1024 * 1024 * 1024
  };

  const match = limitStr.match(/^(\d+)([a-zA-Z]+)$/);
  if (!match) return 10 * 1024 * 1024; // Default 10MB

  const [, value, unit] = match;
  const unitKey = unit.toLowerCase();

  if (units[unitKey]) {
    return parseInt(value) * units[unitKey];
  }

  return 10 * 1024 * 1024; // Default 10MB
};

/**
 * IP whitelist/blacklist middleware
 */
const ipFilter = (options = {}) => {
  const { whitelist = [], blacklist = [] } = options;

  return (req, res, next) => {
    const clientIp = req.ip || req.connection.remoteAddress;

    // Check blacklist first
    if (blacklist.includes(clientIp)) {
      return res.status(403).json({
        status: 'error',
        message: 'Access denied from this IP address'
      });
    }

    // If whitelist is specified, only allow whitelisted IPs
    if (whitelist.length > 0 && !whitelist.includes(clientIp)) {
      return res.status(403).json({
        status: 'error',
        message: 'Access denied from this IP address'
      });
    }

    next();
  };
};

/**
 * Content-Type validation middleware
 */
const validateContentType = (allowedTypes = ['application/json']) => {
  return (req, res, next) => {
    // Skip for GET requests without body
    if (req.method === 'GET' || req.method === 'DELETE') {
      return next();
    }

    const contentType = req.headers['content-type'];

    if (!contentType) {
      return res.status(400).json({
        status: 'error',
        message: 'Content-Type header is required'
      });
    }

    const [type] = contentType.split(';');

    if (!allowedTypes.includes(type.trim())) {
      return res.status(415).json({
        status: 'error',
        message: `Unsupported Media Type. Allowed types: ${allowedTypes.join(', ')}`
      });
    }

    next();
  };
};

/**
 * HTTP method validation middleware
 */
const validateHttpMethod = (allowedMethods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS']) => {
  return (req, res, next) => {
    if (!allowedMethods.includes(req.method)) {
      return res.status(405).json({
        status: 'error',
        message: `Method ${req.method} not allowed. Allowed methods: ${allowedMethods.join(', ')}`
      });
    }
    next();
  };
};

module.exports = {
  createRateLimiter,
  enhancedHelmet,
  securityHeaders,
  requestIdMiddleware,
  requestSizeLimiter,
  ipFilter,
  validateContentType,
  validateHttpMethod
};

