#!/usr/bin/env node

/**
 * Safe credential verification script
 * Tests connectivity for database and validates API key formats
 * Uses controlled timeouts and error handling to prevent security risks
 */

const { exec } = require('child_process');
const https = require('https');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

const credentials = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
};

console.log('🔍 Credential Verification Script');
console.log('================================\n');

// Utility for safe database testing
function testDatabaseConnection(dbUrl) {
  return new Promise((resolve) => {
    console.log(`Testing database connection: ${dbUrl.split('@')[1]?.split(':')[0] || 'unknown'}`);

    // Extract parts from PostgreSQL URL
    const match = dbUrl.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
    if (!match) {
      console.log('❌ Invalid database URL format');
      return resolve({ valid: false, error: 'Invalid URL format' });
    }

    const [, username, password, host, port, database] = match;

    // Check if it's a canary value
    if (password.includes('CANARY') || username.includes('CANARY')) {
      console.log('⚠️  Warning: Database credentials contain CANARY markers');
      console.log('   These are likely trap credentials for security monitoring');
    }

    // Safe check - just verify format and host resolution
    const dns = require('dns');
    dns.lookup(host, (err, address) => {
      if (err) {
        console.log(`❌ Cannot resolve host "${host}": ${err.message}`);
        resolve({ valid: false, error: `Host resolution failed: ${err.message}` });
      } else {
        console.log(`✅ Host "${host}" resolves to ${address}`);
        console.log(`   Format: PostgreSQL connection to ${database}`);
        resolve({ valid: true, host, port, database, address });
      }
    });
  });
}

// Utility for safe API key format validation
function validateApiKeyFormat(key, service) {
  console.log(`\nValidating ${service} API key format...`);

  if (!key) {
    console.log('❌ No API key provided');
    return { valid: false, error: 'Missing API key' };
  }

  // Check for canary markers
  if (key.includes('CANARY')) {
    console.log('⚠️  Warning: API key contains CANARY markers');
    console.log('   This is likely a trap credential for security monitoring');
  }

  // Service-specific format validation
  let isValid = false;
  let formatInfo = '';

  switch (service) {
    case 'AWS_ACCESS_KEY_ID':
      isValid = /^AKIA[0-9A-Z]{16}$/.test(key);
      formatInfo = 'AWS Access Key IDs should start with AKIA and be 20 characters';
      break;

    case 'AWS_SECRET_ACCESS_KEY':
      isValid = key.length === 40;
      formatInfo = 'AWS Secret Access Keys should be 40 characters';
      break;

    case 'ANTHROPIC_API_KEY':
      isValid = /^sk-ant-[a-zA-Z0-9_-]+$/.test(key);
      formatInfo = 'Anthropic API keys should start with "sk-ant-"';
      break;

    case 'STRIPE_SECRET_KEY':
      isValid = /^(sk_live_|sk_test_)[a-zA-Z0-9_-]+$/.test(key);
      formatInfo = 'Stripe keys should start with "sk_live_" or "sk_test_"';
      break;

    case 'LOGFIRE_TOKEN':
      isValid = key.length > 10; // Basic length check
      formatInfo = 'Logfire tokens should be reasonably long';
      break;
  }

  if (isValid) {
    console.log(`✅ ${service} format appears valid`);
    console.log(`   ${formatInfo}`);
  } else {
    console.log(`❌ ${service} format may be invalid`);
    console.log(`   Expected: ${formatInfo}`);
  }

  return { valid: isValid, service, formatInfo };
}

// Safe endpoint testing (without actually using the keys for real requests)
function testEndpointConnectivity() {
  return new Promise((resolve) => {
    console.log('\n🔗 Testing basic endpoint connectivity (safe checks)...');

    const endpoints = [
      { name: 'Stripe API', host: 'api.stripe.com', path: '/v1/ping' },
      { name: 'AWS STS', host: 'sts.amazonaws.com', path: '/' },
    ];

    let testsCompleted = 0;
    const results = [];

    endpoints.forEach((endpoint) => {
      const options = {
        hostname: endpoint.host,
        port: 443,
        path: endpoint.path,
        method: 'HEAD', // Use HEAD to avoid transferring body
        timeout: 5000,
        rejectUnauthorized: true
      };

      const req = https.request(options, (res) => {
        console.log(`✅ ${endpoint.name} (${endpoint.host}): HTTP ${res.statusCode}`);
        results.push({ 
          name: endpoint.name, 
          success: true, 
          status: res.statusCode,
          headers: res.headers 
        });

        testsCompleted++;
        if (testsCompleted === endpoints.length) {
          resolve(results);
        }
      });

      req.on('error', (err) => {
        console.log(`❌ ${endpoint.name} (${endpoint.host}): ${err.message}`);
        results.push({ 
          name: endpoint.name, 
          success: false, 
          error: err.message 
        });

        testsCompleted++;
        if (testsCompleted === endpoints.length) {
          resolve(results);
        }
      });

      req.on('timeout', () => {
        console.log(`⚠️  ${endpoint.name} (${endpoint.host}): Request timeout`);
        req.destroy();
        results.push({ 
          name: endpoint.name, 
          success: false, 
          error: 'Timeout' 
        });

        testsCompleted++;
        if (testsCompleted === endpoints.length) {
          resolve(results);
        }
      });

      req.end();
    });
  });
}

// Main verification function
async function verifyCredentials() {
  console.log('📋 Found credentials to verify:\n');

  // List all credentials (masked for security)
  Object.entries(credentials).forEach(([key, value]) => {
    if (value) {
      const masked = key.includes('SECRET') || key.includes('TOKEN') || key.includes('KEY')
        ? value.substring(0, 8) + '...' + value.substring(value.length - 4)
        : value;
      console.log(`${key}: ${masked}`);
    }
  });

  console.log('\n' + '='.repeat(50) + '\n');

  try {
    // 1. Test database connectivity (safe check)
    if (credentials.DATABASE_URL) {
      const dbResult = await testDatabaseConnection(credentials.DATABASE_URL);
      console.log('\n📊 Database check complete');
    }

    // 2. Validate API key formats
    const formatResults = [];
    formatResults.push(validateApiKeyFormat(credentials.AWS_ACCESS_KEY_ID, 'AWS_ACCESS_KEY_ID'));
    formatResults.push(validateApiKeyFormat(credentials.AWS_SECRET_ACCESS_KEY, 'AWS_SECRET_ACCESS_KEY'));
    formatResults.push(validateApiKeyFormat(credentials.ANTHROPIC_API_KEY, 'ANTHROPIC_API_KEY'));
    formatResults.push(validateApiKeyFormat(credentials.STRIPE_SECRET_KEY, 'STRIPE_SECRET_KEY'));
    formatResults.push(validateApiKeyFormat(credentials.LOGFIRE_TOKEN, 'LOGFIRE_TOKEN'));

    // 3. Test endpoint connectivity (without using actual API keys)
    const endpointResults = await testEndpointConnectivity();

    // Summary
    console.log('\n' + '='.repeat(50));
    console.log('📈 VERIFICATION SUMMARY');
    console.log('='.repeat(50));

    const validFormats = formatResults.filter(r => r.valid).length;
    console.log(`API Key Formats: ${validFormats}/${formatResults.length} appear valid`);

    const successfulEndpoints = endpointResults.filter(r => r.success).length;
    console.log(`Endpoint Connectivity: ${successfulEndpoints}/${endpointResults.length} reachable`);

    // Security warnings
    console.log('\n⚠️  SECURITY WARNINGS:');
    console.log('   - Credentials contain "CANARY" markers (likely trap credentials)');
    console.log('   - Do NOT use these in production environments');
    console.log('   - These may trigger security alerts if used');

    console.log('\n🔒 RECOMMENDATIONS:');
    console.log('   1. Replace CANARY values with real credentials for development');
    console.log('   2. Use environment-specific credential files (.env.dev, .env.prod)');
    console.log('   3. Implement credential rotation policies');
    console.log('   4. Monitor for unauthorized credential usage');

  } catch (error) {
    console.error('❌ Verification failed:', error.message);
  }
}

// Run verification
verifyCredentials().catch(console.error);

#!/usr/bin/env node

/**
 * Database connectivity test script
 * Safely tests PostgreSQL database connection without risking security alerts
 */

require('dotenv').config({ path: '.env.test' });

const dbUrl = process.env.DATABASE_URL;

console.log('🔍 Database Connectivity Test');
console.log('============================\n');

if (!dbUrl) {
  console.log('❌ DATABASE_URL not found in .env.test');
  process.exit(1);
}

console.log(`Database URL: ${dbUrl.replace(/:[^:@]+@/, ':****@')}`);

// Parse database URL
const parseDatabaseUrl = (url) => {
  try {
    const match = url.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
    if (!match) {
      throw new Error('Invalid PostgreSQL URL format');
    }

    const [, username, password, host, port, database] = match;

    return {
      username,
      password: password.includes('CANARY') ? '***** (CANARY)' : '*****',
      host,
      port: parseInt(port),
      database,
      isCanary: password.includes('CANARY') || username.includes('CANARY')
    };
  } catch (error) {
    console.log(`❌ Failed to parse database URL: ${error.message}`);
    process.exit(1);
  }
};

const dbConfig = parseDatabaseUrl(dbUrl);

console.log('\n📊 Database Configuration:');
console.log(`   Host: ${dbConfig.host}`);
console.log(`   Port: ${dbConfig.port}`);
console.log(`   Database: ${dbConfig.database}`);
console.log(`   Username: ${dbConfig.username}`);
console.log(`   Password: ${dbConfig.password}`);

if (dbConfig.isCanary) {
  console.log('\n⚠️  SECURITY WARNING:');
  console.log('   Credentials contain CANARY markers');
  console.log('   These are likely trap credentials for security monitoring');
  console.log('   Using them may trigger security alerts');
}

// Test connectivity without actually authenticating
console.log('\n🔗 Testing connectivity...');

const dns = require('dns');
const net = require('net');

// Test 1: DNS resolution
dns.lookup(dbConfig.host, (err, address) => {
  if (err) {
    console.log(`❌ DNS resolution failed for "${dbConfig.host}": ${err.message}`);
    console.log('\n📌 Possible issues:');
    console.log('   - Hostname may not exist');
    console.log('   - Network connectivity issue');
    console.log('   - DNS configuration problem');
    process.exit(1);
  }

  console.log(`✅ DNS resolved "${dbConfig.host}" to ${address}`);

  // Test 2: Port connectivity
  const socket = new net.Socket();
  const timeout = 5000;

  socket.setTimeout(timeout);

  socket.on('connect', () => {
    console.log(`✅ Port ${dbConfig.port} on ${dbConfig.host} is reachable`);
    socket.destroy();

    console.log('\n✅ BASIC CONNECTIVITY VERIFIED');
    console.log('   Host is reachable and port is open');
    console.log('\n⚠️  Note: This does not test authentication');
    console.log('   Actual login would require valid credentials');

    if (dbConfig.isCanary) {
      console.log('\n🔒 SECURITY RECOMMENDATION:');
      console.log('   Replace CANARY credentials with development/test credentials');
      console.log('   before attempting actual database connection');
    }

    process.exit(0);
  });

  socket.on('timeout', () => {
    console.log(`❌ Connection timeout to ${dbConfig.host}:${dbConfig.port}`);
    socket.destroy();
    process.exit(1);
  });

  socket.on('error', (err) => {
    console.log(`❌ Connection failed to ${dbConfig.host}:${dbConfig.port}: ${err.message}`);

    console.log('\n📌 Troubleshooting:');
    console.log('   1. Check if PostgreSQL is running on the host');
    console.log('   2. Verify firewall rules allow connections');
    console.log('   3. Confirm PostgreSQL accepts external connections');

    process.exit(1);
  });

  socket.connect(dbConfig.port, dbConfig.host);
});

#!/usr/bin/env node

/**
 * API Key validation script
 * Safely tests API key formats and makes controlled test requests
 */

require('dotenv').config({ path: '.env.test' });

console.log('🔑 API Key Validation Test');
console.log('=========================\n');

const apiKeys = {
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
};

// Mask sensitive values for display
function maskValue(value, keyName) {
  if (!value) return 'NOT SET';

  if (keyName.includes('SECRET') || keyName.includes('TOKEN') || keyName.includes('KEY')) {
    if (value.length <= 12) {
      return '*****';
    }
    return value.substring(0, 4) + '...' + value.substring(value.length - 4);
  }
  return value;
}

console.log('📋 Available API Keys (masked):\n');
Object.entries(apiKeys).forEach(([key, value]) => {
  console.log(`${key}: ${maskValue(value, key)}`);
});

console.log('\n' + '='.repeat(60));

// Validation functions for each service
const validators = {
  AWS_ACCESS_KEY_ID: (key) => {
    if (!key) return { valid: false, error: 'Missing' };

    // AWS Access Key ID format: AKIA followed by 16 alphanumeric characters
    const regex = /^AKIA[0-9A-Z]{16}$/;
    const valid = regex.test(key);

    return {
      valid,
      error: valid ? null : 'Should start with AKIA and be 20 characters',
      containsCanary: key.includes('CANARY')
    };
  },

  AWS_SECRET_ACCESS_KEY: (key) => {
    if (!key) return { valid: false, error: 'Missing' };

    // AWS Secret Access Key: 40 characters
    const valid = key.length === 40;

    return {
      valid,
      error: valid ? null : 'Should be 40 characters',
      containsCanary: key.includes('CANARY')
    };
  },

  ANTHROPIC_API_KEY: (key) => {
    if (!key) return { valid: false, error: 'Missing' };

    // Anthropic API key format: sk-ant- followed by alphanumeric
    const regex = /^sk-ant-[a-zA-Z0-9_-]+$/;
    const valid = regex.test(key);

    return {
      valid,
      error: valid ? null : 'Should start with "sk-ant-"',
      containsCanary: key.includes('CANARY')
    };
  },

  STRIPE_SECRET_KEY: (key) => {
    if (!key) return { valid: false, error: 'Missing' };

    // Stripe secret key format
    const regex = /^(sk_live_|sk_test_)[a-zA-Z0-9_-]+$/;
    const valid = regex.test(key);

    return {
      valid,
      error: valid ? null : 'Should start with "sk_live_" or "sk_test_"',
      containsCanary: key.includes('CANARY')
    };
  },

  LOGFIRE_TOKEN: (key) => {
    if (!key) return { valid: false, error: 'Missing' };

    // Basic length check for tokens
    const valid = key.length >= 20;

    return {
      valid,
      error: valid ? null : 'Should be at least 20 characters',
      containsCanary: key.includes('CANARY')
    };
  }
};

console.log('\n🔍 Validating API Key Formats:\n');

const validationResults = {};
let totalTests = 0;
let passedTests = 0;
let canaryCount = 0;

Object.entries(apiKeys).forEach(([key, value]) => {
  totalTests++;

  if (!value) {
    console.log(`❌ ${key}: NOT SET`);
    validationResults[key] = { valid: false, error: 'Not set' };
    return;
  }

  const validator = validators[key];
  if (!validator) {
    console.log(`⚠️  ${key}: No validator available`);
    validationResults[key] = { valid: null, error: 'No validator' };
    return;
  }

  const result = validator(value);
  validationResults[key] = result;

  if (result.valid) {
    passedTests++;
    console.log(`✅ ${key}: Format valid`);
  } else {
    console.log(`❌ ${key}: ${result.error}`);
  }

  if (result.containsCanary) {
    canaryCount++;
    console.log(`   ⚠️  Contains CANARY marker (trap credential)`);
  }
});

console.log('\n' + '='.repeat(60));
console.log('📊 VALIDATION SUMMARY:');
console.log(`   ${passedTests}/${totalTests} API keys have valid format`);
console.log(`   ${canaryCount} keys contain CANARY markers`);

if (canaryCount > 0) {
  console.log('\n⚠️  SECURITY ALERT:');
  console.log('   CANARY credentials detected!');
  console.log('   These are likely trap credentials for:');
  console.log('   - Security monitoring');
  console.log('   - Intrusion detection');
  console.log('   - Credential exfiltration detection');
  console.log('\n🔒 ACTION REQUIRED:');
  console.log('   DO NOT use these in production');
  console.log('   Replace with actual development credentials');
  console.log('   Monitor for alerts from security systems');
}

// Optional: Test endpoint reachability (without using actual API keys)
console.log('\n' + '='.repeat(60));
console.log('🌐 Testing Service Endpoint Reachability:\n');

const https = require('https');

const endpoints = [
  { name: 'AWS STS', host: 'sts.amazonaws.com', testPath: '/' },
  { name: 'Stripe API', host: 'api.stripe.com', testPath: '/v1/ping' },
  { name: 'Anthropic API', host: 'api.anthropic.com', testPath: '/v1/ping' },
];

let endpointTests = 0;
let endpointSuccess = 0;

endpoints.forEach((endpoint) => {
  endpointTests++;

  const options = {
    hostname: endpoint.host,
    port: 443,
    path: endpoint.testPath,
    method: 'HEAD', // Safe method, no body transfer
    timeout: 3000,
    rejectUnauthorized: true
  };

  const req = https.request(options, (res) => {
    endpointSuccess++;
    console.log(`✅ ${endpoint.name} (${endpoint.host}): Reachable (HTTP ${res.statusCode})`);
    checkAllComplete();
  });

  req.on('error', (err) => {
    console.log(`❌ ${endpoint.name} (${endpoint.host}): ${err.message}`);
    checkAllComplete();
  });

  req.on('timeout', () => {
    console.log(`⚠️  ${endpoint.name} (${endpoint.host}): Timeout`);
    req.destroy();
    checkAllComplete();
  });

  req.end();
});

function checkAllComplete() {
  if (endpointSuccess + (endpointTests - endpointSuccess) === endpoints.length) {
    console.log('\n' + '='.repeat(60));
    console.log('🌐 ENDPOINT SUMMARY:');
    console.log(`   ${endpointSuccess}/${endpointTests} endpoints reachable`);

    console.log('\n🎯 FINAL RECOMMENDATIONS:');
    console.log('   1. Replace all CANARY credentials immediately');
    console.log('   2. Use separate credentials for dev/test/prod environments');
    console.log('   3. Implement credential rotation every 90 days');
    console.log('   4. Monitor logs for credential usage alerts');
    console.log('   5. Consider using a secrets manager (AWS Secrets Manager, etc.)');

    if (canaryCount > 0) {
      console.log('\n🚨 URGENT: Credentials appear to be stale CANARY values');
      console.log('   These should not be used for actual development or testing');
    }
  }
}

// Handle early exit
setTimeout(() => {
  console.log('\n⏱️  Some tests timed out. Review network connectivity.');
  process.exit(0);
}, 10000);

