// Secure Express.js application with comprehensive error handling and input validation
// Following security best practices for production applications

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query } = require('express-validator');
const winston = require('winston');
const morgan = require('morgan');

// Environment validation
require('dotenv').config();

const requiredEnvVars = [
  'NODE_ENV',
  'PORT',
];

for (const envVar of requiredEnvVars) {
  if (!process.env[envVar]) {
    console.error(`❌ Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
}

// Configure logging
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'app-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// 2. CORS configuration
const corsOptions = {
  origin: process.env.CORS_ORIGIN || '*',
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request logging
app.use(morgan('combined', { 
  stream: { write: (message) => logger.info(message.trim()) }
}));

// ============ INPUT VALIDATION MIDDLEWARE ============

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation error', { errors: errors.array(), path: req.path });
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

// ============ ERROR HANDLING MIDDLEWARE ============

// Async error handling wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// 404 handler
app.use((req, res, next) => {
  logger.warn(`404 Not Found: ${req.method} ${req.url}`);
  res.status(404).json({
    success: false,
    error: 'Resource not found',
    path: req.url,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  logger.error('Unhandled error', {
    error: message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    statusCode,
  });

  // Don't expose internal error details in production
  const errorResponse = {
    success: false,
    error: message,
  };

  if (process.env.NODE_ENV !== 'production' && err.details) {
    errorResponse.details = err.details;
  }

  res.status(statusCode).json(errorResponse);
});

// ============ ROUTES WITH VALIDATION ============

// Health check endpoint
app.get('/health', 
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean'),
  validateRequest,
  (req, res) => {
    const response = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
    };

    if (req.query.detailed === 'true') {
      response.detailed = true;
      response.env = process.env.NODE_ENV;
    }

    res.json(response);
  }
);

// Users endpoint with query parameter validation
app.get('/users',
  [
    query('page').optional().isInt({ min: 1 }).withMessage('page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
    query('sort').optional().isIn(['name', 'email', 'id']).withMessage('sort must be one of: name, email, id'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { page = 1, limit = 10, sort = 'id' } = req.query;

    // Simulate database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
    ];

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (a[sort] < b[sort]) return -1;
      if (a[sort] > b[sort]) return 1;
      return 0;
    });

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = sortedUsers.slice(startIndex, startIndex + limit);

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: users.length,
        totalPages: Math.ceil(users.length / limit),
      },
    });
  })
);

// New endpoint with body validation example
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { name, email, age } = req.body;

    // Log sensitive operation (sanitized)
    logger.info('User creation attempt', {
      name,
      email: email ? '***@***.***' : null, // Sanitize email in logs
      age: age || null,
      ip: req.ip,
    });

    // Simulate user creation
    const newUser = {
      id: Date.now(),
      name,
      email,
      age: age || null,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser,
    });
  })
);

// ============ SERVER SETUP WITH GRACEFUL SHUTDOWN ============

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server started successfully`, {
    port: PORT,
    environment: process.env.NODE_ENV,
    pid: process.pid,
  });
  console.log(`✅ Server running on port ${PORT}`);
});

// Graceful shutdown
const shutdown = async (signal) => {
  logger.info(`${signal} received. Starting graceful shutdown...`);

  // Stop accepting new connections
  server.close(async () => {
    logger.info('HTTP server closed');

    // Close database connections, cleanup, etc.
    // await database.disconnect();

    logger.info('Graceful shutdown completed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    logger.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', { promise, reason });
  // Avoid crashing the process in production
  if (process.env.NODE_ENV === 'production') {
    // Optionally send alert to monitoring service
  } else {
    throw reason;
  }
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  // In production, wait for connections to close, then restart
  if (process.env.NODE_ENV === 'production') {
    setTimeout(() => process.exit(1), 1000);
  } else {
    process.exit(1);
  }
});

module.exports = { app, server };

