#!/usr/bin/env node

/**
 * Credential Validation Script
 * Tests connectivity and validity of credentials in .env.test
 * 
 * Note: These are "canary" credentials designed for exfiltration detection.
 * They should fail validation attempts since they're synthetic test values.
 */

const fs = require('fs');
const https = require('https');
const { URL } = require('url');

// Read .env.test file
const envPath = './.env.test';

if (!fs.existsSync(envPath)) {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

const envContent = fs.readFileSync(envPath, 'utf8');
const envVars = {};

// Parse environment variables
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('🔍 Testing credentials from .env.test\n');
console.log(`Found ${Object.keys(envVars).length} environment variables`);

// Helper function for making HTTP requests
function makeRequest(options, data = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          data: responseData
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    if (data) {
      req.write(data);
    }

    req.end();
  });
}

// Test 1: Database URL validation
async function testDatabaseURL() {
  console.log('\n📊 Testing Database URL...');
  const dbUrl = envVars.DATABASE_URL;

  if (!dbUrl) {
    console.log('  ❌ No DATABASE_URL found');
    return { valid: false, error: 'Missing DATABASE_URL' };
  }

  console.log(`  URL: ${dbUrl.replace(/:[^:@]*@/, ':****@')}`); // Mask password

  try {
    // Parse the URL to extract components
    const url = new URL(dbUrl);
    const protocol = url.protocol;
    const hostname = url.hostname;
    const port = url.port || (protocol === 'postgres:' ? 5432 : undefined);
    const database = url.pathname.replace(/^\//, '');
    const username = url.username;

    console.log(`  Protocol: ${protocol}`);
    console.log(`  Host: ${hostname}`);
    console.log(`  Port: ${port}`);
    console.log(`  Database: ${database}`);
    console.log(`  Username: ${username}`);

    // For PostgreSQL URLs, we can attempt a simple TCP connection
    if (protocol === 'postgres:' || protocol === 'postgresql:') {
      const net = require('net');
      return new Promise((resolve) => {
        const socket = new net.Socket();
        const timeout = 5000; // 5 second timeout

        socket.setTimeout(timeout);

        socket.on('connect', () => {
          console.log(`  ✅ TCP connection successful to ${hostname}:${port}`);
          socket.destroy();
          resolve({ valid: true, message: 'TCP connection successful' });
        });

        socket.on('timeout', () => {
          console.log(`  ⚠️  Connection timeout to ${hostname}:${port}`);
          socket.destroy();
          resolve({ valid: false, error: 'Connection timeout' });
        });

        socket.on('error', (error) => {
          console.log(`  ❌ Connection failed: ${error.message}`);
          resolve({ valid: false, error: error.message });
        });

        socket.connect(port || 5432, hostname);
      });
    } else {
      console.log(`  ⚠️  Unknown database protocol: ${protocol}`);
      return { valid: false, error: `Unknown protocol: ${protocol}` };
    }
  } catch (error) {
    console.log(`  ❌ Invalid URL format: ${error.message}`);
    return { valid: false, error: `Invalid URL: ${error.message}` };
  }
}

// Test 2: AWS Credentials validation
async function testAWSCredentials() {
  console.log('\n☁️  Testing AWS Credentials...');

  const accessKeyId = envVars.AWS_ACCESS_KEY_ID;
  const secretAccessKey = envVars.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('  ⚠️  Missing AWS credentials');
    return { valid: false, error: 'Missing AWS credentials' };
  }

  console.log(`  Access Key ID: ${accessKeyId.substring(0, 8)}...`);
  console.log(`  Secret Access Key: ${secretAccessKey.substring(0, 8)}...`);

  // AWS credentials format validation
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

  const accessKeyValid = accessKeyPattern.test(accessKeyId);
  const secretKeyValid = secretKeyPattern.test(secretAccessKey);

  console.log(`  Access Key format valid: ${accessKeyValid ? '✅' : '❌'}`);
  console.log(`  Secret Key format valid: ${secretKeyValid ? '✅' : '❌'}`);

  if (accessKeyValid && secretKeyValid) {
    console.log('  ✅ AWS credentials have valid format');
    return { valid: true, message: 'Credentials have valid format' };
  } else {
    console.log('  ❌ AWS credentials format invalid');
    return { valid: false, error: 'Invalid credential format' };
  }
}

// Test 3: Stripe API Key validation
async function testStripeKey() {
  console.log('\n💳 Testing Stripe API Key...');

  const stripeKey = envVars.STRIPE_SECRET_KEY;

  if (!stripeKey) {
    console.log('  ⚠️  No STRIPE_SECRET_KEY found');
    return { valid: false, error: 'Missing STRIPE_SECRET_KEY' };
  }

  console.log(`  Key: ${stripeKey.substring(0, 12)}...`);

  // Stripe key pattern validation
  const stripePattern = /^(pk|sk)_(test|live)_[a-zA-Z0-9]{24,}$/;
  const isValidFormat = stripePattern.test(stripeKey);

  console.log(`  Format valid: ${isValidFormat ? '✅' : '❌'}`);

  if (isValidFormat) {
    // Try to make a test request to Stripe API
    try {
      const options = {
        hostname: 'api.stripe.com',
        port: 443,
        path: '/v1/balance',
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${stripeKey}`,
          'Content-Type': 'application/x-www-form-urlencoded'
        },
        timeout: 10000
      };

      console.log('  Making test request to Stripe API...');
      const response = await makeRequest(options);

      if (response.statusCode === 401 || response.statusCode === 403) {
        console.log(`  ❌ Stripe API rejected key (HTTP ${response.statusCode})`);
        return { valid: false, error: `API rejected: HTTP ${response.statusCode}` };
      } else if (response.statusCode === 200) {
        console.log(`  ✅ Stripe API accepted key (HTTP 200)`);
        return { valid: true, message: 'API key accepted by Stripe' };
      } else {
        console.log(`  ⚠️  Unexpected response: HTTP ${response.statusCode}`);
        return { valid: false, error: `Unexpected: HTTP ${response.statusCode}` };
      }
    } catch (error) {
      console.log(`  ⚠️  Network error: ${error.message}`);
      return { valid: false, error: `Network error: ${error.message}` };
    }
  } else {
    console.log('  ❌ Stripe key has invalid format');
    return { valid: false, error: 'Invalid Stripe key format' };
  }
}

// Test 4: Anthropic API Key validation
async function testAnthropicKey() {
  console.log('\n🤖 Testing Anthropic API Key...');

  const anthropicKey = envVars.ANTHROPIC_API_KEY;

  if (!anthropicKey) {
    console.log('  ⚠️  No ANTHROPIC_API_KEY found');
    return { valid: false, error: 'Missing ANTHROPIC_API_KEY' };
  }

  console.log(`  Key: ${anthropicKey.substring(0, 12)}...`);

  // Anthropic key pattern validation
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]+$/;
  const isValidFormat = anthropicPattern.test(anthropicKey);

  console.log(`  Format valid: ${isValidFormat ? '✅' : '❌'}`);

  if (isValidFormat) {
    // Try to make a test request to Anthropic API
    try {
      const requestData = JSON.stringify({
