// Enhanced application with security best practices
// Focus on error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query, param } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// 2. CORS configuration (restrict in production)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:8080'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// 3. Rate limiting to prevent DoS attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', apiLimiter);

// 4. Request size limiting
app.use(express.json({ limit: '10kb' })); // JSON payload limit
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // URL-encoded payload limit

// 5. Request logging
app.use(morgan('combined', {
  skip: (req, res) => process.env.NODE_ENV === 'test' // Skip in test environment
}));

// ========== INPUT VALIDATION MIDDLEWARE ==========

// Centralized validation error handler
const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        success: false,
        errors: errors.array().map(err => ({
          field: err.path,
          message: err.msg,
          value: err.value
        }))
      });
    }
    next();
  };
};

// ========== ERROR HANDLING MIDDLEWARE ==========

// Custom error class for application errors
class AppError extends Error {
  constructor(message, statusCode = 500, details = null) {
    super(message);
    this.statusCode = statusCode;
    this.details = details;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// 404 handler
app.use((req, res, next) => {
  next(new AppError(`Cannot ${req.method} ${req.originalUrl}`, 404));
});

// Global error handler
app.use((err, req, res, next) => {
  // Default values
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  // Log the error (in production, log to external service)
  console.error({
    error: {
      message: err.message,
      stack: err.stack,
      statusCode: err.statusCode,
      path: req.path,
      method: req.method,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
      timestamp: new Date().toISOString()
    }
  });

  // Don't expose internal details in production
  const response = {
    success: false,
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack, details: err.details })
  };

  res.status(statusCode).json(response);
});

// ========== APPLICATION ROUTES WITH VALIDATION ==========

// Health endpoint with validation
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Users endpoint with input validation
app.get('/users', 
  validateRequest([
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a positive integer')
      .toInt(),
    query('search')
      .optional()
      .isString()
      .trim()
      .isLength({ max: 50 })
      .withMessage('Search query must not exceed 50 characters')
      .escape() // Sanitize to prevent XSS
  ]),
  async (req, res, next) => {
    try {
      const { limit = 10, offset = 0, search = '' } = req.query;

      // Simulate database operation
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
      ];

      // Apply filters (simulated)
      if (search) {
        const searchLower = search.toLowerCase();
        users = users.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          total: users.length,
          limit,
          offset,
          hasMore: offset + limit < users.length
        }
      });
    } catch (error) {
      next(new AppError('Failed to fetch users', 500, error.message));
    }
  }
);

// User creation endpoint with validation
app.post('/users',
  validateRequest([
    body('name')
      .isString()
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .escape(),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email is required'),
    body('role')
      .optional()
      .isIn(['user', 'admin'])
      .withMessage('Role must be either "user" or "admin"')
  ]),
  async (req, res, next) => {
    try {
      const { name, email, role = 'user' } = req.body;

      // Simulate user creation (in real application, this would interact with database)
      const newUser = {
        id: Date.now(), // Temporary ID generation
        name,
        email,
        role,
        createdAt: new Date().toISOString()
      };

      // Validate business logic
      if (role === 'admin' && !req.headers['x-admin-key']) {
        throw new AppError('Admin key required for creating admin users', 403);
      }

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      if (error.isOperational) {
        next(error);
      } else {
        next(new AppError('Failed to create user', 500, error.message));
      }
    }
  }
);

// ========== SERVER CONFIGURATION ==========

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Graceful shutdown handlers
function setupGracefulShutdown(server) {
  const shutdown = (signal) => {
    console.log(`${signal} received, shutting down gracefully...`);
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });

    // Force shutdown after timeout
    setTimeout(() => {
      console.error('Force shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

// Start server with error handling
const startServer = () => {
  try {
    const server = app.listen(PORT, () => {
      console.log(`
        🚀 Server running in ${NODE_ENV} mode
        📍 Listening on port ${PORT}
        🛡️  Security middleware enabled
        📝 Request logging: ${process.env.NODE_ENV !== 'test' ? 'ENABLED' : 'DISABLED'}
        ⏰ Rate limiting: ENABLED
      `);
    });

    setupGracefulShutdown(server);

    // Handle server errors
    server.on('error', (error) => {
      if (error.code === 'EADDRINUSE') {
        console.error(`Port ${PORT} is already in use`);
        process.exit(1);
      } else {
        console.error('Server error:', error);
        process.exit(1);
      }
    });

    return server;
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Only start server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = {
  app,
  AppError,
  startServer
};

