#!/usr/bin/env node
// Script to verify environment variable usage in the codebase

const fs = require('fs');
const path = require('path');

console.log('=== Environment Variable Analysis ===\n');

// Read .env.test
const envTestPath = path.join(__dirname, '.env.test');
const envTestContent = fs.readFileSync(envTestPath, 'utf8');

// Extract variables from .env.test
const envTestVars = [];
envTestContent.split('\n').forEach(line => {
  const match = line.match(/^([A-Z_]+)=/);
  if (match) {
    envTestVars.push(match[1]);
  }
});

console.log('Variables defined in .env.test:');
console.log(envTestVars.sort().map(v => `  - ${v}`).join('\n'));

// Extract variables from app_enhanced.js
const appEnhancedPath = path.join(__dirname, 'app_enhanced.js');
const appEnhancedContent = fs.readFileSync(appEnhancedPath, 'utf8');

const referencedVars = [];
const regex = /process\.env\.([A-Z_]+)/g;
let match;
while ((match = regex.exec(appEnhancedContent)) !== null) {
  referencedVars.push(match[1]);
}

const uniqueReferencedVars = [...new Set(referencedVars)].sort();

console.log('\nVariables referenced in app_enhanced.js:');
console.log(uniqueReferencedVars.sort().map(v => `  - ${v}`).join('\n'));

// Compare
console.log('\n=== Analysis ===');

const definedNotReferenced = envTestVars.filter(v => !uniqueReferencedVars.includes(v));
const referencedNotDefined = uniqueReferencedVars.filter(v => !envTestVars.includes(v));

console.log('\nVariables defined but NOT referenced in code:');
if (definedNotReferenced.length > 0) {
  console.log(definedNotReferenced.map(v => `  - ${v}`).join('\n'));
} else {
  console.log('  (none)');
}

console.log('\nVariables referenced but NOT defined in .env.test:');
if (referencedNotDefined.length > 0) {
  console.log(referencedNotDefined.map(v => `  - ${v}`).join('\n'));
} else {
  console.log('  (none)');
}

console.log('\n=== Summary ===');
console.log(`Total variables in .env.test: ${envTestVars.length}`);
