async function testCredentialSafety(key, value) {
  console.log(`\n--- Testing: ${key} ---`);

  // Check if it's a canary value
  const isCanary = value.includes('CANARY');
  console.log(`Canary detected: ${isCanary ? 'YES ✓' : 'NO'}`);

  if (isCanary) {
    console.log('⚠  SAFE MODE: Skipping real connectivity test for canary value');
    console.log('   Reason: Fake credentials would trigger authentication errors');
    return { safe: true, reason: 'Canary value - safe to skip' };
  }

  // Perform safe checks based on credential type
  switch (key) {
    case 'DATABASE_URL':
      return await testDatabaseUrl(value);

    case 'AWS_ACCESS_KEY_ID':
    case 'AWS_SECRET_ACCESS_KEY':
      return testAwsCredentials(key, value);

    case 'ANTHROPIC_API_KEY':
      return testApiKeyFormat('Anthropic', value, 'sk-ant-');

    case 'STRIPE_SECRET_KEY':
      return testApiKeyFormat('Stripe', value, 'sk_(live|test)_');

    case 'LOGFIRE_TOKEN':
      return testGenericToken('Logfire', value);

    case 'JWT_SECRET':
    case 'SESSION_SECRET':
      return testSecretLength(key, value, 32);

    default:
      return { safe: true, reason: 'Non-sensitive configuration value' };
  }
}

async function testDatabaseUrl(url) {
  try {
    const parsed = parse(url);
    console.log(`Database type: ${parsed.protocol?.replace(':', '') || 'unknown'}`);
    console.log(`Hostname: ${parsed.hostname || 'none'}`);

    // For internal hosts, we can't resolve them
    if (parsed.hostname && !parsed.hostname.includes('.internal')) {
      try {
        await new Promise((resolve, reject) => {
          dns.lookup(parsed.hostname, (err) => {
            if (err) {
              console.log(`DNS resolution: Cannot resolve ${parsed.hostname}`);
              resolve();
            } else {
              console.log(`DNS resolution: ${parsed.hostname} is resolvable`);
              resolve();
            }
          });
        });
      } catch (dnsError) {
        console.log(`DNS check failed: ${dnsError.message}`);
      }
    } else {
      console.log('Host appears to be internal (.internal) - skipping DNS check');
    }

    return { safe: true, reason: 'Database URL format valid' };
  } catch (error) {
    return { safe: false, reason: `Invalid database URL: ${error.message}` };
  }
}

