  console.log(`AWS ${key.includes('ACCESS_KEY_ID') ? 'Access Key' : 'Secret Key'}`);

  if (key === 'AWS_ACCESS_KEY_ID') {
    const isValidFormat = /^AKIA[0-9A-Z]{16}$/.test(value);
    console.log(`Format valid: ${isValidFormat ? 'YES' : 'NO'}`);

