  if (key.length < 20) {
    return { safe: false, reason: `${service} API key too short` };
  }

  return { safe: true, reason: `${service} API key format valid` };
}

function testGenericToken(service, token) {
  console.log(`Service: ${service}`);
  console.log(`Token length: ${token.length} chars`);

  if (token.length < 16) {
    return { safe: false, reason: `${service} token too short (< 16 chars)` };
