function testSecretLength(key, secret, minLength) {
  console.log(`Secret type: ${key}`);
  console.log(`Length: ${secret.length} chars (minimum: ${minLength})`);

  if (secret.length < minLength) {
    return { safe: false, reason: `${key} too short for security (min ${minLength} chars)` };
  }

  return { safe: true, reason: `${key} length acceptable` };
}

