// Improved Express.js application with security best practices
// Enhanced error handling, input validation, and security configurations

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ============================================================================
// SECURITY MIDDLEWARE CONFIGURATION
// ============================================================================

// 1. Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration - restrict origins in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Configure allowed origins
    : '*', // Be more restrictive in production
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// 3. Rate limiting to prevent brute force attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// 4. Request parsing with size limits
app.use(express.json({
  limit: '10kb' // Prevent large payload attacks
}));
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// 5. Compression for performance
app.use(compression());

// 6. HTTP request logging
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health' // Skip health checks from logs
}));

// ============================================================================
// ENVIRONMENT VALIDATION
// ============================================================================

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
if (process.env.NODE_ENV === 'production') {
  requiredEnvVars.push('DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY');
}

for (const envVar of requiredEnvVars) {
  if (!process.env[envVar]) {
    console.error(`Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
}

// ============================================================================
// CUSTOM MIDDLEWARE
// ============================================================================

// Request validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Global error handler middleware
const errorHandler = (err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  };

  res.status(statusCode).json(response);
};

// 404 handler middleware
const notFoundHandler = (req, res, next) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.path} not found`
  });
};

// ============================================================================
// ROUTES WITH INPUT VALIDATION
// ============================================================================

// Health check endpoint with input validation
app.get('/health', 
  [
    query('detailed').optional().isBoolean().withMessage('detailed must be a boolean'),
    query('services').optional().isArray().withMessage('services must be an array')
  ],
  validateRequest,
  (req, res) => {
    try {
      const response = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        memory: process.memoryUsage(),
        env: process.env.NODE_ENV
      };

      // Add detailed info if requested
      if (req.query.detailed === 'true') {
        response.version = process.version;
        response.platform = process.platform;
        response.arch = process.arch;
      }

      res.json(response);
    } catch (error) {
      next(error);
    }
  }
);

// Users endpoint with enhanced security
app.get('/users',
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a non-negative integer'),
    query('active').optional().isBoolean().withMessage('active must be a boolean')
  ],
  validateRequest,
  (req, res, next) => {
    try {
      // Extract and sanitize query parameters
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;
      const active = req.query.active ? req.query.active === 'true' : null;

      // Simulated user data (in production, this would come from a database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com', active: true },
        { id: 2, name: 'Bob', email: 'bob@example.com', active: true },
        { id: 3, name: 'Charlie', email: 'charlie@example.com', active: false },
        { id: 4, name: 'Diana', email: 'diana@example.com', active: true },
        { id: 5, name: 'Eve', email: 'eve@example.com', active: false }
      ];

      // Filter and paginate users based on query parameters
      let filteredUsers = allUsers;

      if (active !== null) {
        filteredUsers = allUsers.filter(user => user.active === active);
      }

      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      // Sanitize sensitive data before sending response
      const sanitizedUsers = paginatedUsers.map(user => ({
        id: user.id,
        name: user.name,
        email: user.email, // Consider masking email in production
        active: user.active
      }));

      res.json({
        data: sanitizedUsers,
        pagination: {
          total: filteredUsers.length,
          limit,
          offset,
          hasMore: offset + limit < filteredUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example POST endpoint with request body validation
app.post('/users',
  [
    body('name').trim().escape().isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters'),
    body('email').trim().normalizeEmail().isEmail().withMessage('Valid email is required'),
    body('age').optional().isInt({ min: 0, max: 150 }).withMessage('Age must be between 0 and 150')
  ],
  validateRequest,
  (req, res, next) => {
    try {
      // Input has been validated and sanitized
      const { name, email, age } = req.body;

      // In production, you would save to database here
      const newUser = {
        id: Date.now(), // Temporary ID
        name,
        email,
        age: age || null,
        createdAt: new Date().toISOString()
      };

      res.status(201).json({
        message: 'User created successfully',
        user: newUser
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// Apply not found handler for undefined routes
app.use(notFoundHandler);

// Apply global error handler (must be last)
app.use(errorHandler);

// ============================================================================
// GRACEFUL SHUTDOWN HANDLING
// ============================================================================

const gracefulShutdown = (signal) => {
  console.log(`Received ${signal}. Starting graceful shutdown...`);

  // Close server to stop accepting new connections
  if (server) {
    server.close(() => {
      console.log('HTTP server closed');

      // Additional cleanup (close DB connections, etc.)
      // Example: if (database) await database.close();

      console.log('Graceful shutdown complete');
      process.exit(0);
    });

    // Force close after timeout
    setTimeout(() => {
      console.error('Could not close connections in time, forcing shutdown');
      process.exit(1);
    }, 10000);
  }
};

// Handle termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// ============================================================================
// SERVER INITIALIZATION
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log('Security middleware enabled: Helmet, CORS, Rate Limiting');
});

// Export app for testing
module.exports = { app, server };

