// Enhanced version of original app.js with essential security improvements
// Minimal changes while adding crucial security features

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const app = express();

// ============================================================================
// ESSENTIAL SECURITY MIDDLEWARE (minimal setup)
// ============================================================================

// 1. Basic security headers
app.use(helmet());

// 2. Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});
app.use(limiter);

// 3. Basic CORS - adjust for production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? false : '*',
  methods: ['GET']
}));

// 4. Request size limits
app.use(express.json({ limit: '10kb' }));

// ============================================================================
// ENVIRONMENT VALIDATION
// ============================================================================

const PORT = process.env.PORT || 3000;

// Validate port is a valid number
if (isNaN(parseInt(PORT)) || parseInt(PORT) < 1 || parseInt(PORT) > 65535) {
  console.error('Invalid PORT configuration');
  process.exit(1);
}

// ============================================================================
// ENHANCED ROUTES WITH BASIC VALIDATION
// ============================================================================

// Health endpoint with timestamp validation
app.get('/health', (req, res) => {
  try {
    // Basic input validation
    const detailed = req.query.detailed;
    if (detailed && detailed !== 'true' && detailed !== 'false') {
      return res.status(400).json({ error: 'detailed parameter must be "true" or "false"' });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (detailed === 'true') {
      response.memory = process.memoryUsage();
    }

    res.json(response);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with basic pagination and validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    let limit = 10;
    if (req.query.limit) {
      const parsedLimit = parseInt(req.query.limit);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({ 
          error: 'limit must be a number between 1 and 100' 
        });
      }
      limit = parsedLimit;
    }

    let offset = 0;
    if (req.query.offset) {
      const parsedOffset = parseInt(req.query.offset);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({ 
          error: 'offset must be a non-negative number' 
        });
      }
      offset = parsedOffset;
    }

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
        hasMore: offset + limit < allUsers.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// Centralized error handling
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method
  });

  res.status(err.status || 500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `${req.method} ${req.path} not found`
  });
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

let server;

// Graceful shutdown handler
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server...');

  if (server) {
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forcing shutdown...');
      process.exit(1);
    }, 10000);
  }
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// ============================================================================
// SERVER STARTUP
// ============================================================================

server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log('Security features: Helmet, Rate Limiting, CORS');
});

// Handle startup errors
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

module.exports = app;

