#!/usr/bin/env node

/**
 * Basic network connectivity tests
 * Tests if external services are reachable
 */

const https = require('https');
const net = require('net');
const dns = require('dns').promises;

async function testDnsResolution(hostname) {
  try {
    const addresses = await dns.resolve4(hostname);
    return { success: true, addresses };
  } catch (error) {
    try {
      const addresses = await dns.resolve6(hostname);
      return { success: true, addresses };
    } catch (error2) {
      return { success: false, error: error2.message };
    }
  }
}

async function testTcpConnection(hostname, port, timeout = 5000) {
  return new Promise((resolve) => {
    const socket = net.createConnection(port, hostname, () => {
      socket.end();
      resolve({ success: true });
    });

    socket.setTimeout(timeout);

    socket.on('timeout', () => {
      socket.destroy();
      resolve({ success: false, error: 'Connection timeout' });
    });

    socket.on('error', (err) => {
      resolve({ success: false, error: err.message });
    });
  });
}

async function testHttpRequest(url, timeout = 5000) {
  return new Promise((resolve) => {
    const req = https.request(url, { 
      method: 'HEAD',
      timeout 
    }, (res) => {
      res.on('data', () => {});
      res.on('end', () => {
        resolve({ 
          success: true, 
          statusCode: res.statusCode,
          headers: res.headers 
        });
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ success: false, error: 'Request timeout' });
    });

    req.on('error', (err) => {
      resolve({ success: false, error: err.message });
    });

    req.end();
  });
}

async function runConnectivityTests() {
  console.log('🌐 Network Connectivity Tests');
  console.log('='.repeat(50));

  const tests = [
    // DNS resolution tests
    { name: 'DNS: google.com', test: () => testDnsResolution('google.com') },
    { name: 'DNS: github.com', test: () => testDnsResolution('github.com') },
    { name: 'DNS: db.internal', test: () => testDnsResolution('db.internal') },

    // TCP connectivity tests
    { name: 'TCP: google.com:443', test: () => testTcpConnection('google.com', 443) },
    { name: 'TCP: github.com:443', test: () => testTcpConnection('github.com', 443) },
    { name: 'TCP: db.internal:5432', test: () => testTcpConnection('db.internal', 5432) },

    // HTTP/HTTPS tests
    { name: 'HTTPS: google.com', test: () => testHttpRequest('https://google.com') },
    { name: 'HTTPS: api.stripe.com', test: () => testHttpRequest('https://api.stripe.com') },
    { name: 'HTTPS: api.anthropic.com', test: () => testHttpRequest('https://api.anthropic.com') },
    { name: 'HTTPS: s3.amazonaws.com', test: () => testHttpRequest('https://s3.amazonaws.com') },
  ];

  const results = [];

  for (const test of tests) {
    process.stdout.write(`Testing ${test.name}... `);
    try {
      const result = await test.test();
      if (result.success) {
        console.log('✅');
        if (result.addresses) {
          console.log(`   Resolved to: ${result.addresses.slice(0, 2).join(', ')}${result.addresses.length > 2 ? '...' : ''}`);
        } else if (result.statusCode) {
          console.log(`   HTTP ${result.statusCode}`);
        }
      } else {
        console.log('❌');
        console.log(`   Error: ${result.error}`);
      }
      results.push({ name: test.name, ...result });
    } catch (error) {
      console.log('❌');
      console.log(`   Exception: ${error.message}`);
      results.push({ name: test.name, success: false, error: error.message });
    }

    // Brief delay between tests
    await new Promise(resolve => setTimeout(resolve, 500));
  }

  // Generate summary
  console.log('\n' + '='.repeat(50));
  console.log('📊 CONNECTIVITY SUMMARY');
  console.log('='.repeat(50));

  const successful = results.filter(r => r.success).length;
  const total = results.length;

  console.log(`Successful tests: ${successful}/${total} (${Math.round(successful/total*100)}%)`);

  // Analyze specific issues
  const dbInternalTests = results.filter(r => r.name.includes('db.internal'));
  const dbInternalSuccess = dbInternalTests.filter(r => r.success).length;

  if (dbInternalTests.length > 0 && dbInternalSuccess === 0) {
    console.log('\n⚠️  CRITICAL FINDING: db.internal is unreachable');
    console.log('   This confirms that the DATABASE_URL in .env.test is synthetic');
    console.log('   Expected behavior for canary credentials');
  }

  // Check external service connectivity
  const externalServices = ['google.com', 'github.com', 'api.stripe.com', 'api.anthropic.com', 's3.amazonaws.com'];
  const externalSuccess = results.filter(r => 
    externalServices.some(service => r.name.includes(service) && r.success)
  ).length;

  console.log(`\nExternal services reachable: ${externalSuccess}/${externalServices.length}`);

  if (externalSuccess >= 3) {
    console.log('✅ General internet connectivity is good');
  } else {
    console.log('⚠️  Limited internet connectivity detected');
  }

  console.log('\n💡 IMPLICATIONS FOR APP.JS:');
