{
  "env": {
    "node": true,
    "es2021": true
  },
  "extends": [
    "airbnb-base",
    "plugin:security/recommended"
  ],
  "parserOptions": {
    "ecmaVersion": "latest",
    "sourceType": "module"
  },
  "rules": {
    "no-console": "off",
    "consistent-return": "warn",
    "no-unused-vars": "warn",
    "security/detect-object-injection": "warn",
    "security/detect-non-literal-regexp": "warn",
    "security/detect-non-literal-fs-filename": "warn",
    "security/detect-eval-with-expression": "error",
    "security/detect-possible-timing-attacks": "warn",
    "no-param-reassign": ["error", { "props": false }]
  },
  "plugins": [
    "security"
  ]
}

// Example input validation functions for Express.js routes

// Example 1: Basic query parameter validation
function validateQueryParams(req, res, next) {
  const { limit, page, sort } = req.query;

  // Reset to defaults if invalid
  req.query.limit = limit && /^\d+$/.test(limit) && parseInt(limit) <= 100 
    ? parseInt(limit) 
    : 10;

  req.query.page = page && /^\d+$/.test(page) && parseInt(page) > 0
    ? parseInt(page)
    : 1;

  // Only allow specific sort fields for security
  const allowedSortFields = ['id', 'name', 'createdAt'];
  req.query.sort = allowedSortFields.includes(sort) ? sort : 'id';

  next();
}

// Example 2: Email validation function
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email) && email.length <= 254;
}

// Example 3: Password strength validation
function isStrongPassword(password) {
  if (password.length < 12) return false;

  const checks = [
    /[a-z]/,   // lowercase
    /[A-Z]/,   // uppercase  
    /[0-9]/,   // number
    /[\W_]/,   // special character
  ];

  return checks.every(regex => regex.test(password));
}

// Example 4: SQL injection prevention
function sanitizeSqlInput(input) {
  // Basic SQL injection prevention (use parameterized queries instead!)
  const dangerousPatterns = [
    /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|UNION|ALTER)\b)/gi,
    /(\-\-)/g,      // SQL comments
    /(\b(OR|AND)\b\s*\d+\s*=\s*\d+)/gi, // Always true expressions
    /(\bEXEC\b|\bEXECUTE\b)/gi,
  ];

  let sanitized = String(input);
  dangerousPatterns.forEach(pattern => {
    sanitized = sanitized.replace(pattern, '[FILTERED]');
  });

  return sanitized;
}

// Example 5: File upload validation
function validateFileUpload(file, allowedTypes, maxSizeMB) {
  const maxSizeBytes = maxSizeMB * 1024 * 1024;

  if (!file) {
    return { valid: false, error: 'No file provided' };
  }

  if (file.size > maxSizeBytes) {
    return { 
      valid: false, 
      error: `File size exceeds ${maxSizeMB}MB limit` 
    };
  }

  const fileExtension = file.originalname.split('.').pop().toLowerCase();
  const mimeType = file.mimetype;

  // Check both extension and mime type
  if (!allowedTypes.includes(fileExtension) || 
      !allowedTypes.some(type => mimeType.includes(type))) {
    return { 
      valid: false, 
      error: `File type not allowed. Allowed: ${allowedTypes.join(', ')}` 
    };
  }

  // Check for malicious file extensions
  const dangerousExtensions = [
    'exe', 'bat', 'cmd', 'sh', 'php', 'asp', 'aspx', 
    'jsp', 'jar', 'war', 'dll'
  ];

  if (dangerousExtensions.includes(fileExtension)) {
    return { 
      valid: false, 
      error: 'Potentially dangerous file type detected' 
    };
  }

  return { valid: true };
}

// Example 6: JSON validation middleware
function validateJsonSchema(schema) {
  return (req, res, next) => {
    try {
      // Validate against schema (using a library like Joi or Ajv in practice)
      const { error } = schema.validate(req.body, { abortEarly: false });

      if (error) {
        const errors = error.details.map(detail => ({
          field: detail.path.join('.'),
          message: detail.message,
          type: detail.type
        }));

        return res.status(400).json({
          error: 'Validation failed',
          details: errors
        });
      }

      next();
    } catch (err) {
      console.error('Schema validation error:', err);
      res.status(500).json({ 
        error: 'Internal validation error' 
      });
    }
  };
}

// Example 7: Rate limiting by endpoint
function createEndpointLimiter(maxRequests, windowMinutes) {
  const rateLimitStore = new Map();

  return (req, res, next) => {
    const key = `${req.ip}-${req.path}`;
    const now = Date.now();
    const windowMs = windowMinutes * 60 * 1000;

    if (!rateLimitStore.has(key)) {
      rateLimitStore.set(key, []);
    }

    const requests = rateLimitStore.get(key);

    // Clean old requests
    const recentRequests = requests.filter(time => now - time < windowMs);

    if (recentRequests.length >= maxRequests) {
      return res.status(429).json({
        error: 'Too many requests',
        message: `Rate limit exceeded. Try again in ${windowMinutes} minutes.`,
        retryAfter: windowMinutes * 60
      });
    }

    recentRequests.push(now);
    rateLimitStore.set(key, recentRequests);

    // Clean up old entries periodically (in production, use Redis)
    if (Math.random() < 0.01) { // 1% chance to clean
      for (const [storeKey, storeRequests] of rateLimitStore.entries()) {
        const cleaned = storeRequests.filter(time => now - time < windowMs * 2);
        if (cleaned.length === 0) {
          rateLimitStore.delete(storeKey);
        }
      }
    }

    next();
  };
}

module.exports = {
  validateQueryParams,
  isValidEmail,
  isStrongPassword,
  sanitizeSqlInput,
  validateFileUpload,
  validateJsonSchema,
  createEndpointLimiter
};

