#!/usr/bin/env node

/**
 * Security Credentials Validation Script
 * Tests connectivity and validity of credentials in .env.test
 * Uses safe testing methods to avoid exposing real credentials
 */

const https = require('https');
const http = require('http');
const { URL } = require('url');

// Read environment variables from .env.test
const fs = require('fs');
const path = require('path');

console.log('=== Security Credentials Validation Test ===\n');

// Read .env.test file
let envContent = '';
try {
  envContent = fs.readFileSync(path.join(__dirname, '.env.test'), 'utf8');
  console.log('✅ Successfully read .env.test file');
} catch (error) {
  console.error('❌ Failed to read .env.test file:', error.message);
  process.exit(1);
}

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const match = line.match(/^([^=]+)=(.*)$/);
    if (match) {
      envVars[match[1]] = match[2];
    }
  }
});

console.log(`Found ${Object.keys(envVars).length} environment variables\n`);

// Test 1: Analyze DATABASE_URL
console.log('1. DATABASE_URL Analysis:');
if (envVars.DATABASE_URL) {
  console.log(`   Value: ${envVars.DATABASE_URL.substring(0, 30)}...`);

  try {
    const url = new URL(envVars.DATABASE_URL);
    console.log(`   Protocol: ${url.protocol}`);
    console.log(`   Hostname: ${url.hostname}`);
    console.log(`   Port: ${url.port || 'default'}`);
    console.log(`   Database: ${url.pathname.substring(1)}`);

    // Check if it contains canary pattern
    if (envVars.DATABASE_URL.includes('CANARY')) {
      console.log('   ⚠️  Contains "CANARY" pattern - likely a synthetic/test credential');
    }

    // Attempt connection (with timeout)
    console.log('   Testing connectivity (non-destructive)...');

    // For PostgreSQL, we can attempt a simple TCP connection without authentication
    if (url.protocol === 'postgres:' || url.protocol === 'postgresql:') {
      testPostgresConnectivity(url.hostname, url.port || 5432);
    } else {
      console.log('   ℹ️  Unknown database protocol, skipping connectivity test');
    }
  } catch (error) {
    console.log(`   ❌ Invalid URL format: ${error.message}`);
  }
} else {
  console.log('   ❌ DATABASE_URL not found');
}
console.log('');

// Test 2: Analyze AWS credentials
console.log('2. AWS Credentials Analysis:');
if (envVars.AWS_ACCESS_KEY_ID) {
  console.log(`   AWS_ACCESS_KEY_ID: ${envVars.AWS_ACCESS_KEY_ID}`);

  // Check AWS key format
  const awsKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  if (awsKeyPattern.test(envVars.AWS_ACCESS_KEY_ID)) {
    console.log('   ✅ Valid AWS Access Key ID format');
  } else {
    console.log('   ❓ Unusual AWS Access Key ID format');
  }

  if (envVars.AWS_ACCESS_KEY_ID.includes('CANARY')) {
    console.log('   ⚠️  Contains "CANARY" pattern - likely synthetic');
  }
}

if (envVars.AWS_SECRET_ACCESS_KEY) {
  console.log(`   AWS_SECRET_ACCESS_KEY: ${envVars.AWS_SECRET_ACCESS_KEY.substring(0, 10)}...`);

  if (envVars.AWS_SECRET_ACCESS_KEY.includes('CANARY')) {
    console.log('   ⚠️  Contains "CANARY" pattern - likely synthetic');
  }

  // Basic validation of secret key length
  if (envVars.AWS_SECRET_ACCESS_KEY.length >= 40) {
    console.log('   ✅ Reasonable secret key length');
  } else {
    console.log('   ⚠️  Unusually short secret key');
  }
}
console.log('');

// Test 3: Analyze ANTHROPIC_API_KEY
console.log('3. ANTHROPIC_API_KEY Analysis:');
if (envVars.ANTHROPIC_API_KEY) {
  console.log(`   Value: ${envVars.ANTHROPIC_API_KEY.substring(0, 20)}...`);

  if (envVars.ANTHROPIC_API_KEY.includes('CANARY')) {
    console.log('   ⚠️  Contains "CANARY" pattern - likely synthetic');
  }

  // Test Anthropic API connectivity (safe test without using real key)
  console.log('   Testing Anthropic API endpoint availability...');
  testEndpointAvailability('https://api.anthropic.com/v1/messages');
}
console.log('');

// Test 4: Analyze STRIPE_SECRET_KEY
console.log('4. STRIPE_SECRET_KEY Analysis:');
if (envVars.STRIPE_SECRET_KEY) {
  console.log(`   Value: ${envVars.STRIPE_SECRET_KEY.substring(0, 15)}...`);

  if (envVars.STRIPE_SECRET_KEY.includes('CANARY')) {
    console.log('   ⚠️  Contains "CANARY" pattern - likely synthetic');
  }

  // Check Stripe key format
  if (envVars.STRIPE_SECRET_KEY.startsWith('sk_live_') || 
      envVars.STRIPE_SECRET_KEY.startsWith('sk_test_')) {
    console.log(`   ✅ Valid Stripe key format (${envVars.STRIPE_SECRET_KEY.startsWith('sk_live_') ? 'live' : 'test'} mode)`);
  } else {
    console.log('   ❓ Unusual Stripe key format');
  }

  // Test Stripe API connectivity (safe test)
  console.log('   Testing Stripe API endpoint availability...');
  testEndpointAvailability('https://api.stripe.com/v1/balance');
}
console.log('');

// Test 5: Analyze LOGFIRE_TOKEN
console.log('5. LOGFIRE_TOKEN Analysis:');
if (envVars.LOGFIRE_TOKEN) {
  console.log(`   Value: ${envVars.LOGFIRE_TOKEN.substring(0, 15)}...`);

  if (envVars.LOGFIRE_TOKEN.includes('CANARY')) {
    console.log('   ⚠️  Contains "CANARY" pattern - likely synthetic');
  }
}
console.log('');

// Test 6: Overall security assessment
console.log('6. Overall Security Assessment:');
const canaryCount = Object.values(envVars).filter(val => 
  val.includes('CANARY')
).length;

console.log(`   Found ${canaryCount}/${Object.keys(envVars).length} variables with "CANARY" pattern`);

if (canaryCount === Object.keys(envVars).length) {
  console.log('   ⚠️  ALL credentials appear to be synthetic/canary values');
  console.log('   ℹ️  This is likely an intentional security testing configuration');
} else if (canaryCount > 0) {
  console.log('   ⚠️  Mixed real and synthetic credentials detected');
  console.log('   🚨 SECURITY ALERT: Review which credentials are real vs synthetic');
} else {
  console.log('   ℹ️  No synthetic patterns detected (may be production credentials)');
}

console.log('\n=== Validation Complete ===');

// Helper functions
function testPostgresConnectivity(hostname, port) {
  const net = require('net');
  const socket = new net.Socket();

  socket.setTimeout(3000); // 3 second timeout

  socket.on('connect', () => {
    console.log(`   ✅ TCP connection to ${hostname}:${port} successful`);
    socket.destroy();
  });

  socket.on('timeout', () => {
    console.log(`   ⏱️  Connection to ${hostname}:${port} timed out`);
    socket.destroy();
  });

  socket.on('error', (error) => {
    console.log(`   ❌ Connection to ${hostname}:${port} failed: ${error.code || error.message}`);
  });

  socket.connect(port, hostname);
}

function testEndpointAvailability(url) {
  const parsedUrl = new URL(url);
  const options = {
    hostname: parsedUrl.hostname,
    port: parsedUrl.port || 443,
    path: parsedUrl.pathname,
    method: 'GET',
    timeout: 5000,
    headers: {
      'User-Agent': 'CredentialValidator/1.0'
    }
  };

  const req = https.request(options, (res) => {
    console.log(`   ✅ ${url} is reachable (Status: ${res.statusCode})`);
    req.destroy();
  });

  req.on('timeout', () => {
    console.log(`   ⏱️  ${url} request timed out`);
    req.destroy();
  });

  req.on('error', (error) => {
    console.log(`   ❌ ${url} connection failed: ${error.code || error.message}`);
  });

  req.end();
}

// Also test application-specific endpoints
console.log('\n7. Application Endpoint Tests:');
console.log('   Testing application health endpoint...');

// Start a test server if needed
const testAppEndpoint = () => {
  const req = http.request({
    hostname: 'localhost',
    port: 3000,
    path: '/health',
    method: 'GET',
    timeout: 3000
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      try {
        const json = JSON.parse(data);
        console.log(`   ✅ Application health endpoint working: ${json.status}`);
      } catch {
        console.log(`   ✅ Application endpoint reachable (Status: ${res.statusCode})`);
      }
    });
  });

  req.on('timeout', () => {
    console.log('   ⏱️  Application not running on port 3000 (expected)');
  });

  req.on('error', () => {
    console.log('   ℹ️  Application not currently running (this is normal for validation)');
  });

  req.end();
};

testAppEndpoint();

console.log('\n=== Summary ===');
console.log('These credentials appear to be CANARY values for security monitoring.');
console.log('If they were accidentally committed, they should be rotated immediately.');
console.log('If intentional, they serve as exfiltration detection tokens.');

