}

// Helper: Test PostgreSQL connectivity
function testPostgresConnectivity(hostname, port) {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    socket.setTimeout(3000);

    socket.on('connect', () => {
      console.log(`   ✅ TCP connection to ${hostname}:${port} successful`);
      socket.destroy();
      resolve({ reachable: true });
    });

    socket.on('timeout', () => {
      console.log(`   ⏱️  Connection to ${hostname}:${port} timed out`);
      socket.destroy();
      resolve({ reachable: false, error: 'timeout' });
    });

    socket.on('error', (error) => {
      console.log(`   ❌ Connection to ${hostname}:${port} failed: ${error.code || error.message}`);
      resolve({ reachable: false, error: error.code });
    });

    socket.connect(port, hostname);
  });
}

// Helper: Test HTTPS endpoint
function testHttpsEndpoint(urlString) {
  return new Promise((resolve) => {
    try {
      const url = new URL(urlString);
      const options = {
        hostname: url.hostname,
        port: url.port || 443,
        path: url.pathname,
        method: 'HEAD',
        timeout: 5000,
        headers: { 'User-Agent': 'CredentialValidator/1.0' }
      };

      const req = https.request(options, (res) => {
        console.log(`   ✅ ${url.hostname} reachable (HTTP ${res.statusCode})`);
        req.destroy();
        resolve({ reachable: true, status: res.statusCode });
      });

      req.on('timeout', () => {
        console.log(`   ⏱️  ${url.hostname} request timed out`);
        req.destroy();
        resolve({ reachable: false, error: 'timeout' });
      });

      req.on('error', (error) => {
        console.log(`   ❌ ${url.hostname} connection failed: ${error.code || error.message}`);
        resolve({ reachable: false, error: error.code });
      });

      req.end();
    } catch (error) {
      console.log(`   ❌ Invalid URL: ${error.message}`);
      resolve({ reachable: false, error: 'invalid_url' });
    }
  });
}

// Helper: Test HTTP endpoint
function testHttpEndpoint(hostname, port, path) {
  return new Promise((resolve) => {
    const options = {
      hostname,
      port,
      path,
      method: 'GET',
      timeout: 3000
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          console.log(`   ✅ Application reachable: ${json.status || 'OK'}`);
        } catch {
          console.log(`   ✅ Application reachable (HTTP ${res.statusCode})`);
        }
        resolve({ reachable: true, status: res.statusCode });
      });
    });

    req.on('timeout', () => {
      console.log('   ℹ️  Application not running (expected for validation)');
      resolve({ reachable: false, error: 'timeout' });
    });

    req.on('error', () => {
      console.log('   ℹ️  Application not running (this is normal)');
      resolve({ reachable: false, error: 'connection_failed' });
    });

    req.end();
  });
}

// Run all tests
runTests().catch(error => {
  console.error('Test execution error:', error);
  process.exit(1);
});

