const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

// Initialize Express app
const app = express();

// Security Best Practices

// 1. Set security headers
app.use(helmet());

// 2. Enable CORS with secure configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Production allowed origins
    : ['http://localhost:3000', 'http://localhost:3001'], // Development origins
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
  optionsSuccessStatus: 204
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request validation middleware
const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        success: false, 
        errors: errors.array(),
        message: 'Validation failed' 
      });
    }
    next();
  };
};

// Global Error Handling Middleware
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  const response = {
    success: false,
    message: err.message || 'Internal server error'
  };

  // Don't expose error details in production
  if (process.env.NODE_ENV !== 'production') {
    response.error = err.message;
  }

  res.status(statusCode).json(response);
});

// Validate environment variables on startup
const validateEnvironment = () => {
  const requiredEnvVars = ['NODE_ENV'];

  const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.error(`Missing required environment variables: ${missingVars.join(', ')}`);
    process.exit(1);
  }

  // Log sensitive environment variable status (without exposing values)
  const sensitiveVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 
                         'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];

  sensitiveVars.forEach(varName => {
    if (process.env[varName]) {
      console.log(`${varName} is configured`);
    }
  });
};

// Routes with improved error handling and validation

// Health check endpoint with additional monitoring
app.get('/health', async (req, res, next) => {
  try {
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version,
      environment: process.env.NODE_ENV
    };

    // Add database connection check if applicable
    // if (db) {
    //   healthStatus.db = await db.healthCheck();
    // }

    res.json(healthStatus);
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation for future expansion
app.get('/users', 
  // Input validation for query parameters
  [
    // Future query parameter validations could go here
    // Example: query('page').optional().isInt({ min: 1 })
    // Example: query('limit').optional().isInt({ min: 1, max: 100 })
  ],
  async (req, res, next) => {
    try {
      // Input sanitization example
      const { page, limit, sort } = req.query;

      // Return sample user data with pagination support
      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          createdAt: '2023-01-15T10:30:00Z'
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          createdAt: '2023-02-20T14:45:00Z'
        },
      ];

      // Apply filtering/sorting if needed
      let filteredUsers = [...users];

      // Example of safe pagination
      const pageNumber = parseInt(page) || 1;
      const pageSize = parseInt(limit) || 10;
      const startIndex = (pageNumber - 1) * pageSize;
      const endIndex = startIndex + pageSize;

      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          page: pageNumber,
          limit: pageSize,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / pageSize)
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Future POST endpoint example with validation
app.post('/users',
  // Input validation
  validateRequest([
    body('name').trim().notEmpty().withMessage('Name is required'),
    body('email').isEmail().withMessage('Valid email is required'),
    body('age').optional().isInt({ min: 18, max: 100 }).withMessage('Age must be between 18 and 100')
  ]),
  async (req, res, next) => {
    try {
      const { name, email, age } = req.body;

      // Sanitize inputs
      const sanitizedName = name.trim();
      const sanitizedEmail = email.toLowerCase().trim();

      // Business logic here
      const newUser = {
        id: Math.floor(Math.random() * 1000),
        name: sanitizedName,
        email: sanitizedEmail,
        age: age || null,
        createdAt: new Date().toISOString()
      };

      // In a real app: await userService.createUser(newUser);

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      next(error);
    }
  }
);

// 404 Handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Route not found',
    path: req.path
  });
});

// Graceful shutdown handling
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server gracefully...');

  server.close(() => {
    console.log('Server closed');

    // Close database connections or other resources here
    // if (db) {
    //   db.close();
    // }

    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Handle process termination signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Validate environment before starting
validateEnvironment();

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Health check available at http://localhost:${PORT}/health`);
});

module.exports = { app, server };

