    "node": ">=16.0.0"
  }
}

// Enhanced version of app.js with essential security improvements
const express = require('express');
const app = express();

// Essential Security Improvements:

// 1. Add basic input validation example
const validateUserInput = (req, res, next) => {
  // Example: Validate any future query parameters
  const { id } = req.query;

  if (id && !/^\d+$/.test(id)) {
    return res.status(400).json({ 
      error: 'Invalid ID format. Must be a number.' 
    });
  }

  next();
};

// 2. Basic error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    path: req.path,
    timestamp: new Date().toISOString()
  });

  // Don't expose stack traces or sensitive info
  const errorResponse = {
    error: 'Something went wrong'
  };

  // Only show detailed error in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.details = err.message;
  }

  res.status(500).json(errorResponse);
});

// 3. Add basic security headers
app.use((req, res, next) => {
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Basic XSS protection (for modern browsers)
  res.setHeader('X-XSS-Protection', '1; mode=block');

  next();
});

// 4. Request size limits
app.use(express.json({ limit: '2mb' }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '2mb' 
}));

// 5. Environment validation
const validateEnvironment = () => {
  // Check if running in a recognized environment
  const validEnvironments = ['development', 'production', 'test'];
  const currentEnv = process.env.NODE_ENV || 'development';

  if (!validEnvironments.includes(currentEnv)) {
    console.warn(`Warning: Unknown NODE_ENV value: ${currentEnv}`);
  }

  // Log startup environment (without sensitive values)
  console.log(`Starting in ${currentEnv} mode`);
};

// Routes with improved error handling

app.get('/health', (req, res) => {
  try {
    const healthData = { 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    };

    res.json(healthData);
  } catch (error) {
    // Pass to error handling middleware
    throw error;
  }
});

app.get('/users', validateUserInput, (req, res) => {
  try {
    // Simulate potential error
    if (req.query.simulateError === 'true') {
      throw new Error('Simulated error for testing');
    }

    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        // Sanitize/escape data before sending
        sanitizedName: escapeHtml('Alice'),
        createdAt: '2023-01-15T10:30:00Z'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        sanitizedName: escapeHtml('Bob'),
        createdAt: '2023-02-20T14:45:00Z'
      },
    ];

    // Apply query filtering safely
    const userId = req.query.id;
    let responseData = users;

    if (userId) {
      const parsedId = parseInt(userId);
      responseData = users.filter(user => user.id === parsedId);

      // Validate result
      if (responseData.length === 0) {
        return res.status(404).json({ 
          error: 'User not found',
          requestedId: userId
        });
      }
    }

    res.json({
      success: true,
      data: responseData,
      count: responseData.length
    });

  } catch (error) {
    // Pass to error handling middleware
    throw error;
  }
});

// 6. 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path
  });
});

// Basic HTML escaping function for XSS protection
function escapeHtml(text) {
  if (!text) return '';

  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;');
}

// Validate environment on startup
validateEnvironment();

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);

  // Security-related startup messages
  console.log('Basic security measures enabled:');
  console.log('- Request size limits');
  console.log('- Security headers');
  console.log('- Input validation');
  console.log('- Error handling middleware');
  console.log('- Environment validation');
});

module.exports = app;

