#!/usr/bin/env node

const { spawn, execSync } = require('child_process');
const https = require('https');
const { parse } = require('url');

// Parse .env.test file
const fs = require('fs');
const path = require('path');

const envFile = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envFile, 'utf8');

console.log('🔍 Analyzing .env.test credentials...\n');

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (!line || line.startsWith('#')) return;

  const eqIndex = line.indexOf('=');
  if (eqIndex > 0) {
    const key = line.substring(0, eqIndex).trim();
    const value = line.substring(eqIndex + 1).trim();
    envVars[key] = value;
  }
});

console.log(`Found ${Object.keys(envVars).length} environment variables:\n`);

// Test each credential
async function testCredentials() {
  const results = [];

  // 1. Test DATABASE_URL
  if (envVars.DATABASE_URL) {
    console.log('🧪 Testing DATABASE_URL...');
    const dbResult = await testDatabaseConnection(envVars.DATABASE_URL);
    results.push({
      name: 'DATABASE_URL',
      value: maskSensitiveData(envVars.DATABASE_URL),
      status: dbResult.status,
      message: dbResult.message
    });
  }

  // 2. Test AWS credentials (simulate AWS API call)
  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
    console.log('🧪 Testing AWS credentials...');
    const awsResult = await testAWSCredentials(envVars.AWS_ACCESS_KEY_ID);
    results.push({
      name: 'AWS_ACCESS_KEY_ID',
      value: maskSensitiveData(envVars.AWS_ACCESS_KEY_ID),
      status: awsResult.status,
      message: awsResult.message
    });
    results.push({
      name: 'AWS_SECRET_ACCESS_KEY',
      value: '***' + envVars.AWS_SECRET_ACCESS_KEY.slice(-4),
      status: '✅' + (awsResult.status.includes('✅') ? ' (same test)' : '❌'),
      message: awsResult.message
    });
  }

  // 3. Test Anthropic API key
  if (envVars.ANTHROPIC_API_KEY) {
    console.log('🧪 Testing Anthropic API key...');
    const anthropicResult = await testAnthropicAPI(envVars.ANTHROPIC_API_KEY);
    results.push({
      name: 'ANTHROPIC_API_KEY',
      value: maskSensitiveData(envVars.ANTHROPIC_API_KEY),
      status: anthropicResult.status,
      message: anthropicResult.message
    });
  }

  // 4. Test Stripe API key
  if (envVars.STRIPE_SECRET_KEY) {
    console.log('🧪 Testing Stripe API key...');
    const stripeResult = await testStripeAPI(envVars.STRIPE_SECRET_KEY);
    results.push({
      name: 'STRIPE_SECRET_KEY',
      value: maskSensitiveData(envVars.STRIPE_SECRET_KEY),
      status: stripeResult.status,
      message: stripeResult.message
    });
  }

  // 5. Test Logfire token
  if (envVars.LOGFIRE_TOKEN) {
    console.log('🧪 Testing Logfire token...');
    const logfireResult = await testLogfireToken(envVars.LOGFIRE_TOKEN);
    results.push({
      name: 'LOGFIRE_TOKEN',
      value: maskSensitiveData(envVars.LOGFIRE_TOKEN),
      status: logfireResult.status,
      message: logfireResult.message
    });
  }

  // Display results
  console.log('\n' + '═'.repeat(80));
  console.log('📊 CREDENTIAL TEST RESULTS');
  console.log('═'.repeat(80) + '\n');

  results.forEach(result => {
    console.log(`${result.status} ${result.name}:`);
    console.log(`   Value: ${result.value}`);
    console.log(`   Result: ${result.message}`);
    console.log();
  });

  // Summary
  const total = results.length;
  const passed = results.filter(r => r.status.includes('✅')).length;
  const failed = results.filter(r => r.status.includes('❌')).length;
  const warning = results.filter(r => r.status.includes('⚠️')).length;

  console.log('═'.repeat(80));
  console.log('📈 SUMMARY:');
  console.log(`   Total tests: ${total}`);
  console.log(`   ✅ Passed: ${passed}`);
  console.log(`   ⚠️  Warnings: ${warning}`);
  console.log(`   ❌ Failed: ${failed}`);
  console.log('═'.repeat(80));

  // Security assessment
  console.log('\n🔒 SECURITY ASSESSMENT:');
  console.log('   These appear to be CANARY values (synthetic test credentials).');
  console.log('   Real credentials should never contain "CANARY-" patterns.');
  console.log('   This is likely intentional for exfiltration detection.');
}

// Helper function to mask sensitive data
function maskSensitiveData(value) {
  if (!value) return '';

  // Show first 8 chars and last 4 chars for long strings
  if (value.length > 20) {
    const firstPart = value.substring(0, 8);
    const lastPart = value.substring(value.length - 4);
    return `${firstPart}...${lastPart}`;
  }

  // For API keys, show pattern recognition
  if (value.includes('CANARY')) {
    return value.replace(/CANARY-[^-]+-([^-]+-?[^-]*)/, 'CANARY-***-$1');
  }

  if (value.startsWith('sk_')) {
    return value.substring(0, 8) + '...' + value.substring(value.length - 4);
  }

  return value;
}

// Test database connection
async function testDatabaseConnection(dbUrl) {
  try {
    const url = new URL(dbUrl);
    const protocol = url.protocol.replace(':', '');

    console.log(`   Database type: ${protocol}`);
    console.log(`   Host: ${url.hostname}`);
    console.log(`   Port: ${url.port || 'default'}`);
    console.log(`   Database: ${url.pathname.replace('/', '')}`);

    // For PostgreSQL, we can attempt a basic connectivity test
    if (protocol === 'postgres' || protocol === 'postgresql') {
      // Check if we can resolve the host
      const dns = require('dns');

      return new Promise((resolve) => {
        dns.lookup(url.hostname, (err) => {
          if (err) {
            resolve({
              status: '❌ DNS lookup failed',
              message: `Cannot resolve host "${url.hostname}": ${err.message}`
            });
          } else {
            // Note: We're not actually connecting due to security concerns
            resolve({
              status: '⚠️  DNS resolves (no auth test)',
              message: `Host "${url.hostname}" resolves. Actual connection not tested for security.`
            });
          }
        });
      });
    } else {
      return {
        status: '⚠️  Unknown database protocol',
        message: `Protocol "${protocol}" not supported for automatic testing`
      };
    }
  } catch (error) {
    return {
      status: '❌ Invalid URL format',
      message: `Failed to parse database URL: ${error.message}`
    };
  }
}

// Test AWS credentials (simplified check)
async function testAWSCredentials(accessKeyId) {
  // AWS access key ID format validation
  // AWS keys start with AKIA, ASIA, or similar patterns
  const awsKeyPattern = /^(AKIA|ASIA|ABIA|ACCA)[A-Z0-9]{12,}$/;

  if (accessKeyId.includes('CANARY')) {
    return {
      status: '⚠️  Canary key detected',
      message: 'This appears to be a synthetic canary key for monitoring'
    };
  }

  if (awsKeyPattern.test(accessKeyId)) {
    return {
      status: '✅ Format valid',
      message: 'AWS Access Key ID format appears valid (actual authorization not tested)'
    };
  } else {
    return {
      status: '❌ Invalid format',
      message: 'Does not match AWS Access Key ID patterns (AKIA|ASIA|ABIA|ACCA)'
    };
  }
}

// Test Anthropic API key
async function testAnthropicAPI(apiKey) {
  // Anthropic API key pattern: REDACTED_ANTHROPIC_KEY
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9]{32,}$/;

  if (apiKey.includes('CANARY')) {
    return {
      status: '⚠️  Canary key detected',
      message: 'This appears to be a synthetic canary key for monitoring'
    };
  }

  if (anthropicPattern.test(apiKey)) {
    return {
      status: '✅ Format valid',
      message: 'Anthropic API key format appears valid (actual API not called)'
    };
  } else {
    return {
      status: '❌ Invalid format',
      message: 'Does not match Anthropic API key pattern (REDACTED_ANTHROPIC_KEY)'
    };
  }
}

// Test Stripe API key
async function testStripeAPI(apiKey) {
  // Stripe secret key patterns:
  // Test: REDACTED_STRIPE_TEST
  // Live: REDACTED_STRIPE_LIVE
  const stripePattern = /^sk_(test|live)_[a-zA-Z0-9]{24,}$/;

  if (apiKey.includes('CANARY')) {
    return {
      status: '⚠️  Canary key detected',
      message: 'This appears to be a synthetic canary key for monitoring'
    };
  }

  if (stripePattern.test(apiKey)) {
    const isLive = apiKey.startsWith('sk_live_');
    return {
      status: isLive ? '⚠️  Live key detected' : '✅ Format valid',
      message: `Stripe ${isLive ? 'LIVE' : 'test'} key format valid (actual API not called)`
    };
  } else {
    return {
      status: '❌ Invalid format',
      message: 'Does not match Stripe secret key pattern (sk_(test|live)_xxxxxxxxxxxxxxxxxxxxxxxx)'
    };
  }
}

// Test Logfire token
async function testLogfireToken(token) {
  // Logfire token pattern unknown, but check if it's a canary
  if (token.includes('CANARY')) {
    return {
      status: '⚠️  Canary token detected',
      message: 'This appears to be a synthetic canary token for monitoring'
    };
  }

  // Generic token check
  if (token.length >= 20) {
    return {
      status: '✅ Appears valid',
      message: 'Token length sufficient (format unknown, actual API not called)'
    };
  } else {
    return {
      status: '❌ Possibly invalid',
      message: 'Token seems too short for a secure API token'
    };
  }
}

// Run tests
testCredentials().catch(error => {
  console.error('❌ Error running tests:', error.message);
  process.exit(1);
});

#!/usr/bin/env node

const net = require('net');
const dns = require('dns');
const https = require('https');
const { URL } = require('url');

console.log('🔌 Testing Connectivity for .env.test Credentials\n');

// Parse .env.test
const fs = require('fs');
const envContent = fs.readFileSync('.env.test', 'utf8');
const envVars = {};

envContent.split('\n').forEach(line => {
  line = line.trim();
  if (!line || line.startsWith('#')) return;
  const eqIndex = line.indexOf('=');
  if (eqIndex > 0) {
    const key = line.substring(0, eqIndex).trim();
    const value = line.substring(eqIndex + 1).trim();
    envVars[key] = value;
  }
});

async function runTests() {
  console.log('📋 Test Plan:');
  console.log('1. Database URL connectivity test');
  console.log('2. Service endpoint reachability');
  console.log('3. Credential format analysis');
  console.log('4. Security assessment\n');

  // Test 1: Database connectivity
  await testDatabaseConnectivity();

  // Test 2: Service endpoints
  await testServiceEndpoints();

  // Test 3: Credential analysis
