  console.log('5. Monitor for credential exfiltration attempts');
}

async function testDatabaseConnectivity() {
  console.log('\n1. 🗄️  DATABASE CONNECTIVITY TEST');
  console.log('─'.repeat(40));

  const dbUrl = envVars.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ No DATABASE_URL found in .env.test');
    return;
  }

  try {
    const url = new URL(dbUrl);
    console.log(`   Protocol: ${url.protocol.replace(':', '')}`);
