      console.log(`      Purpose: Exfiltration detection monitoring`);
      console.log(`      Action: Should trigger alerts if used`);
    }

  } catch (error) {
    console.log(`   ❌ Error: ${error.message}`);
  }
}

async function testServiceEndpoints() {
  console.log('\n2. 🌐 SERVICE ENDPOINT REACHABILITY');
  console.log('─'.repeat(40));

  // Common service endpoints to test
  const services = [];

  if (envVars.DATABASE_URL) {
    try {
      const url = new URL(envVars.DATABASE_URL);
      services.push({
        name: 'Database Host',
        host: url.hostname,
        port: url.port || 5432
      });
    } catch (e) {
      // Ignore parsing errors
    }
  }

  // Add known service endpoints based on credentials
  if (envVars.AWS_ACCESS_KEY_ID) {
    services.push({
      name: 'AWS STS (Token Service)',
      host: 'sts.amazonaws.com',
      port: 443,
      https: true
    });
  }

  if (envVars.ANTHROPIC_API_KEY) {
    services.push({
      name: 'Anthropic API',
      host: 'api.anthropic.com',
      port: 443,
      https: true
    });
  }

  if (envVars.STRIPE_SECRET_KEY) {
    services.push({
      name: 'Stripe API',
      host: 'api.stripe.com',
      port: 443,
      https: true
    });
  }

  if (envVars.LOGFIRE_TOKEN) {
    services.push({
      name: 'Logfire (Supabase)',
      host: 'logflare.app',
      port: 443,
      https: true
    });
  }

  for (const service of services) {
