    try {
      // DNS test first
      await dnsLookup(service.host);

      // Then port test
      if (service.host !== 'sts.amazonaws.com') { // Skip AWS as it's huge
        await testPortConnection(service.host, service.port);
      } else {
        console.log(`      ✅ Host resolves`);
        console.log(`      ℹ️  AWS endpoint - widespread service`);
      }
    } catch (error) {
      console.log(`      ❌ Failed: ${error.message}`);
    }
  }
}

function analyzeCredentials() {
  console.log('\n3. 🔐 CREDENTIAL FORMAT ANALYSIS');
  console.log('─'.repeat(40));

  const credentials = [
    { key: 'AWS_ACCESS_KEY_ID', pattern: /^(AKIA|ASIA|ABIA|ACCA)[A-Z0-9]{12,}$/, type: 'AWS IAM' },
    { key: 'ANTHROPIC_API_KEY', pattern: /^sk-ant-[a-zA-Z0-9]{32,}$/, type: 'Anthropic' },
    { key: 'STRIPE_SECRET_KEY', pattern: /^sk_(test|live)_[a-zA-Z0-9]{24,}$/, type: 'Stripe' },
    { key: 'LOGFIRE_TOKEN', pattern: null, type: 'Logfire' }
  ];

  for (const cred of credentials) {
    const value = envVars[cred.key];
    if (!value) continue;

    console.log(`\n   ${cred.key}:`);
    console.log(`      Type: ${cred.type}`);
    console.log(`      Length: ${value.length} characters`);

    // Check for canary pattern
    if (value.includes('CANARY')) {
      console.log(`      🔔 CANARY DETECTED: Synthetic monitoring credential`);
      console.log(`         First seen: ${value.substring(0, 20)}...`);
      console.log(`         Pattern: Contains "CANARY-" prefix`);
    } else if (cred.pattern && cred.pattern.test(value)) {
      console.log(`      ✅ Format matches expected pattern`);

      // Additional checks
      if (cred.key === 'STRIPE_SECRET_KEY') {
        const isLive = value.startsWith('sk_live_');
        console.log(`      ${isLive ? '⚠️  LIVE PRODUCTION KEY' : '✅ Test key (safe)'}`);
      }
    } else if (cred.pattern) {
      console.log(`      ❌ Format doesn't match expected pattern`);
    } else {
      console.log(`      ℹ️  No pattern validation available`);
    }

    // Security warning for exposed credentials
    if (value.length < 20 && !value.includes('CANARY')) {
      console.log(`      ⚠️  WARNING: Credential seems too short`);
    }
  }
}

// Helper functions
function dnsLookup(hostname) {
  return new Promise((resolve, reject) => {
    dns.lookup(hostname, (err, address, family) => {
      if (err) {
        reject(new Error(`DNS lookup failed: ${err.message}`));
      } else {
        console.log(`      ✅ DNS resolves to ${address} (IPv${family})`);
        resolve(address);
      }
    });
  });
}

function testPortConnection(hostname, port) {
  return new Promise((resolve, reject) => {
    const socket = new net.Socket();
    const timeout = 5000;

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      console.log(`      ✅ Port ${port} is open`);
      socket.destroy();
      resolve();
    });

    socket.on('timeout', () => {
      socket.destroy();
      reject(new Error(`Connection timeout after ${timeout}ms`));
    });

    socket.on('error', (err) => {
      console.log(`      ❌ Port ${port} connection failed: ${err.code || err.message}`);
      reject(err);
    });

    socket.connect(port, hostname);
  });
}

// Run all tests
runTests().catch(console.error);

