// AWS credential format verification
function verifyAWSCredentialFormat(accessKey, secretKey) {
  const awsKeyPattern = /^(AKIA|ASIA|ABIA|ACCA)[A-Z0-9]{12,}$/;

  if (accessKey.includes('CANARY') || secretKey.includes('CANARY')) {
    return {
      status: '🎯 Canary',
      message: 'Synthetic monitoring credentials detected',
      warning: 'Will not work with actual AWS services'
    };
  }

  const accessKeyValid = awsKeyPattern.test(accessKey);
  const secretKeyValid = secretKey && secretKey.length >= 40; // AWS secrets are typically 40 chars

  if (accessKeyValid && secretKeyValid) {
    return {
      status: '✅ Format valid',
      message: 'AWS credentials format appears correct',
      warning: 'Note: No actual AWS API call made for security'
    };
  } else {
    const issues = [];
    if (!accessKeyValid) issues.push('Access key format invalid');
    if (!secretKeyValid) issues.push('Secret key too short or missing');

    return {
      status: '❌ Invalid format',
      message: `Issues: ${issues.join(', ')}`
    };
  }
}

// Database URL analysis
function analyzeDatabaseUrl(dbUrl) {
  try {
    const url = new URL(dbUrl);

    if (dbUrl.includes('CANARY')) {
      return {
        status: '🎯 Canary',
        message: `Synthetic ${url.protocol.replace(':', '')} URL detected`,
        warning: 'Contains canary password for exfiltration monitoring'
      };
    }

    const hasPassword = url.password && url.password.length > 0;
    const issues = [];

    if (hasPassword) {
      issues.push('Password exposed in URL (security risk)');
    }

    if (url.hostname === 'db.internal' || url.hostname === 'localhost') {
      issues.push('Internal/reserved hostname');
    }

    return {
      status: issues.length > 0 ? '⚠️  Warning' : '✅ Valid format',
      message: `${url.protocol.replace(':', '')} database at ${url.hostname}`,
      warning: issues.length > 0 ? issues.join('; ') : undefined
    };
  } catch (err) {
    return {
      status: '❌ Invalid',
      message: `Failed to parse URL: ${err.message}`
    };
  }
}

// Logfire token analysis
function analyzeLogfireToken(token) {
  if (token.includes('CANARY')) {
    return {
      status: '🎯 Canary',
      message: 'Synthetic monitoring token detected'
    };
  }

  // Logfire tokens are typically UUID-like
  const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  if (uuidPattern.test(token)) {
    return {
      status: '✅ Valid format',
      message: 'UUID format appears valid for Logfire'
    };
  } else if (token.length >= 32) {
    return {
      status: '⚠️  Unknown format',
      message: 'Long token (32+ chars) but not standard UUID'
    };
  } else {
    return {
      status: '❌ Invalid',
      message: 'Token seems too short for secure authentication'
    };
  }
}

// Run verification
main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

