// Enhanced Express application with comprehensive error handling and security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const morgan = require('morgan');
const Joi = require('joi'); // For input validation
const winston = require('winston'); // For structured logging

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"], // Adjust based on your needs
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: false, // Adjust for your needs
}));

// 2. CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Restrict in production
    : '*', // More permissive in development
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Compression
app.use(compression());

// 6. Request logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
  // HTTP request logging
  app.use(morgan('combined'));
}

// ========== INPUT VALIDATION MIDDLEWARE ==========

// User parameter validation schema
const userQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sortBy: Joi.string().valid('id', 'name', 'email').default('id'),
  sortOrder: Joi.string().valid('asc', 'desc').default('asc'),
});

// Health check endpoint schema
const healthQuerySchema = Joi.object({
  detailed: Joi.boolean().default(false),
});

// ========== CUSTOM MIDDLEWARE ==========

// Input validation middleware
const validateQuery = (schema) => (req, res, next) => {
  const { error, value } = schema.validate(req.query, { abortEarly: false });

  if (error) {
    const errorMessages = error.details.map(detail => detail.message);
    return res.status(400).json({
      error: 'Validation Error',
      messages: errorMessages,
      timestamp: new Date().toISOString()
    });
  }

  // Replace query with validated values
  req.validatedQuery = value;
  next();
};

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Don't expose internal errors in production
  const message = process.env.NODE_ENV === 'production' && statusCode === 500
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    error: message,
    timestamp: new Date().toISOString(),
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
};

// 404 handler
const notFoundHandler = (req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested resource ${req.path} was not found`,
    timestamp: new Date().toISOString()
  });
};

// ========== ROUTES WITH IMPROVED VALIDATION ==========

app.get('/health', validateQuery(healthQuerySchema), (req, res, next) => {
  try {
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage(),
      ...(req.validatedQuery.detailed && {
        nodeVersion: process.version,
        platform: process.platform,
        environment: process.env.NODE_ENV || 'development',
      })
    };
    res.json(healthStatus);
  } catch (error) {
    next(error);
  }
});

app.get('/users', validateQuery(userQuerySchema), (req, res, next) => {
  try {
    const { limit, offset, sortBy, sortOrder } = req.validatedQuery;

    // Simulated user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2023-01-01' },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2023-01-02' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', createdAt: '2023-01-03' },
      { id: 4, name: 'David', email: 'david@example.com', createdAt: '2023-01-04' },
      { id: 5, name: 'Eve', email: 'eve@example.com', createdAt: '2023-01-05' },
    ];

    // Apply filtering and sorting (simulated)
    let result = [...users];

    // Sort users
    result.sort((a, b) => {
      if (sortOrder === 'asc') {
        return a[sortBy] > b[sortBy] ? 1 : -1;
      } else {
        return a[sortBy] < b[sortBy] ? 1 : -1;
      }
    });

    // Apply pagination
    const startIndex = offset;
    const endIndex = Math.min(startIndex + limit, result.length);
    const paginatedUsers = result.slice(startIndex, endIndex);

    // Sanitize output (remove sensitive data if needed)
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // Excluding createdAt from response for privacy
    }));

    res.json({
      users: sanitizedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: endIndex < users.length
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    next(error);
  }
});

// ========== ERROR HANDLING ROUTES ==========

// Apply 404 handler for unmatched routes
app.use(notFoundHandler);

// Apply error handler (must be last)
app.use(errorHandler);

// ========== SERVER STARTUP WITH GRACEFUL SHUTDOWN ==========

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server running in ${NODE_ENV} mode on port ${PORT}`);
  console.log(`Server running in ${NODE_ENV} mode on port ${PORT}`);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  logger.info(`${signal} received, starting graceful shutdown`);

  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    logger.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Handle termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

# Security Improvements Plan for app.js

## Current Issues Identified

