// Enhanced application with comprehensive error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');
const cors = require('cors');
const compression = require('compression');
const morgan = require('morgan');
const { body, validationResult, param } = require('express-validator');

// Initialize Express app
const app = express();

// ======================
// 1. SECURITY MIDDLEWARE
// ======================

// Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  }
}));

// Enable CORS with secure defaults (adjust based on your needs)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:8080'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});

// Apply rate limiting to all requests
app.use(limiter);

// ======================
// 2. REQUEST PROCESSING
// ======================

// Parse JSON bodies (with size limit)
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies (with size limit)
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request compression
app.use(compression());

// Request logging
app.use(morgan('combined', {
  skip: (req, res) => process.env.NODE_ENV === 'test'
}));

// ======================
// 3. ERROR HANDLING MIDDLEWARE
// ======================

// Custom error class for API errors
class ApiError extends Error {
  constructor(statusCode, message, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Custom 404 handler
app.use((req, res, next) => {
  const error = new ApiError(404, `Route ${req.originalUrl} not found`);
  next(error);
});

// Global error handler
app.use((error, req, res, next) => {
  const statusCode = error.statusCode || 500;
  const message = error.message || 'Internal Server Error';

  // Log the error
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    statusCode: statusCode,
    message: message,
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

  // Send error response
  res.status(statusCode).json({
    success: false,
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

// ======================
// 4. INPUT VALIDATION MIDDLEWARE
// ======================

// Validation error handler
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    const errorMessages = errors.array().map(err => ({
      field: err.param,
      message: err.msg,
      value: err.value
    }));

    return res.status(400).json({
      success: false,
      message: 'Validation failed',
      errors: errorMessages
    });
  };
};

// ======================
// 5. ROUTES WITH VALIDATION
// ======================

// Health check endpoint with validation
app.get('/health', 
  validate([
    body('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
  ]), 
  (req, res, next) => {
    try {
      const { detailed } = req.query;
      const response = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
      };

      if (detailed === 'true') {
        response.details = {
          memory: process.memoryUsage(),
          nodeVersion: process.version,
          platform: process.platform
        };
      }

      res.json(response);
    } catch (error) {
      next(new ApiError(500, 'Health check failed', true));
    }
  }
);

// Users endpoint with ID validation
app.get('/users/:id?',
  validate([
    param('id').optional().isInt({ min: 1 }).withMessage('User ID must be a positive integer')
  ]),
  (req, res, next) => {
    try {
      const { id } = req.params;
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      if (id) {
        const user = users.find(u => u.id === parseInt(id, 10));
        if (!user) {
          throw new ApiError(404, `User with ID ${id} not found`);
        }
        return res.json(user);
      }

      res.json(users);
    } catch (error) {
      next(error);
    }
  }
);

// Create user endpoint with comprehensive validation
app.post('/users',
  validate([
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]*$/)
      .withMessage('Name can only contain letters and spaces'),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 0, max: 120 })
      .withMessage('Age must be between 0 and 120')
  ]),
  (req, res, next) => {
    try {
      const { name, email, age } = req.body;

      // Sanitize input (additional layer of security)
      const sanitizedName = name.replace(/[<>]/g, '');

      // Simulate user creation
      const newUser = {
        id: Math.floor(Math.random() * 1000) + 3,
        name: sanitizedName,
        email: email.toLowerCase(),
        ...(age && { age }),
        createdAt: new Date().toISOString()
      };

      // In real application, you would save to database here
      console.log('New user created:', newUser);

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      next(new ApiError(500, 'Failed to create user', true));
    }
  }
);

// ======================
// 6. SERVER INITIALIZATION
// ======================

// Validate required environment variables
const validateEnvironment = () => {
  const requiredEnvVars = ['NODE_ENV', 'PORT'];
  const missingEnvVars = [];

  requiredEnvVars.forEach(envVar => {
    if (!process.env[envVar]) {
      missingEnvVars.push(envVar);
    }
  });

  if (missingEnvVars.length > 0) {
    throw new Error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  }

  // Validate NODE_ENV
  const validEnvironments = ['development', 'production', 'test'];
  if (!validEnvironments.includes(process.env.NODE_ENV)) {
    throw new Error(`Invalid NODE_ENV: ${process.env.NODE_ENV}. Must be one of: ${validEnvironments.join(', ')}`);
  }
};

// Start server with comprehensive error handling
const startServer = async () => {
  try {
    // Validate environment
    validateEnvironment();

    const PORT = process.env.PORT || 3000;
    const server = app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV}`);
    });

    // Handle server errors
    server.on('error', (error) => {
      if (error.code === 'EADDRINUSE') {
        console.error(`Port ${PORT} is already in use`);
        process.exit(1);
      } else {
        console.error('Server error:', error);
        process.exit(1);
      }
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('SIGTERM signal received: closing HTTP server');
      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      console.log('SIGINT signal received: closing HTTP server');
      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });
    });

    // Handle unhandled promise rejections
    process.on('unhandledRejection', (reason, promise) => {
      console.error('Unhandled Rejection at:', promise, 'reason:', reason);
      // In production, you might want to log to a service like Sentry
    });

    // Handle uncaught exceptions
    process.on('uncaughtException', (error) => {
      console.error('Uncaught Exception:', error);
      process.exit(1);
    });

  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Export app for testing
module.exports = { app, startServer, ApiError };

// Start server if not in test environment
if (require.main === module && process.env.NODE_ENV !== 'test') {
  startServer();
}

