// Minimal enhancement of app.js with basic error handling and input validation
// No additional dependencies required

const express = require('express');
const app = express();

// ======================
// 1. BASIC SECURITY HEADERS
// ======================

app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.removeHeader('X-Powered-By'); // Remove Express signature

  // CORS headers (adjust as needed)
  res.setHeader('Access-Control-Allow-Origin', 'http://localhost:3000');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  next();
});

// ======================
// 2. INPUT VALIDATION HELPERS
// ======================

/**
 * Validate user ID parameter
 */
const validateUserId = (id) => {
  const numId = parseInt(id, 10);
  return !isNaN(numId) && numId > 0 && numId < 1000000; // Reasonable upper bound
};

/**
 * Sanitize string input (basic XSS protection)
 */
const sanitizeString = (str) => {
  if (typeof str !== 'string') return str;
  return str
    .replace(/[<>]/g, '') // Remove < and > characters
    .trim() // Remove whitespace
    .substring(0, 255); // Limit length
};

/**
 * Validate email format
 */
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

// ======================
// 3. ERROR HANDLING MIDDLEWARE
// ======================

// Custom error handler
app.use((error, req, res, next) => {
  console.error('Error:', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    error: error.message,
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
  });

  // Don't expose internal errors in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : error.message;

  res.status(error.statusCode || 500).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { details: error.message })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.originalUrl} not found`
  });
});

// ======================
// 4. ENHANCED ROUTES WITH VALIDATION
// ======================

app.get('/health', (req, res) => {
  try {
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    // Optional detailed parameter with validation
    if (req.query.detailed === 'true') {
      response.details = {
        uptime: process.uptime(),
        nodeVersion: process.version
      };
    }

    res.json(response);
  } catch (error) {
    // Pass error to error handling middleware
    error.statusCode = 500;
    throw error;
  }
});

app.get('/users/:id?', (req, res, next) => {
  try {
    const { id } = req.params;

    // Input validation for ID parameter
    if (id && !validateUserId(id)) {
      const error = new Error('Invalid user ID. Must be a positive integer.');
      error.statusCode = 400;
      throw error;
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    if (id) {
      const userId = parseInt(id, 10);
      const user = users.find(u => u.id === userId);

      if (!user) {
        const error = new Error(`User with ID ${id} not found`);
        error.statusCode = 404;
        throw error;
      }

      return res.json(user);
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// New POST endpoint with validation (example)
app.post('/users', express.json(), (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || !email) {
      const error = new Error('Name and email are required');
      error.statusCode = 400;
      throw error;
    }

    // Sanitize inputs
    const sanitizedName = sanitizeString(name);
    if (sanitizedName.length < 2) {
      const error = new Error('Name must be at least 2 characters');
      error.statusCode = 400;
      throw error;
    }

    if (!validateEmail(email)) {
      const error = new Error('Invalid email format');
      error.statusCode = 400;
      throw error;
    }

    // Simulate user creation
