async function testTcpConnectivity(host, port, timeout = 5000) {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    let connected = false;

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      connected = true;
      socket.destroy();
      resolve({ success: true, message: `Port ${port} is open` });
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve({ success: false, message: `Connection timeout after ${timeout}ms` });
    });

