    return {
      status: 'error',
      message: `DNS resolution failed: ${dnsError.message}`
    };
  }

  // Attempt TCP connection (without authentication)
  return new Promise((resolve) => {
    const socket = net.createConnection({
      host: dbInfo.hostname,
      port: dbInfo.port,
      timeout: 5000
    });

    socket.setTimeout(5000);

    socket.on('connect', () => {
      console.log(`   ✅ TCP connection successful to ${dbInfo.hostname}:${dbInfo.port}`);
      socket.end();
      resolve({
        status: 'success',
        message: 'TCP connection successful'
      });
