      socket.destroy();
      resolve({
        status: 'error',
        message: 'Connection timeout'
      });
    });

    socket.on('error', (error) => {
      console.log(`   ❌ Connection error: ${error.message}`);
      resolve({
        status: 'error',
        message: error.message
      });
    });
  });
}

// Test AWS key format
function testAwsKeyFormat(accessKeyId, secretKey) {
  console.log('\n🔍 Testing AWS credential format...');

  const results = [];

  // AWS Access Key ID format: AKIA followed by 16 uppercase alphanumeric characters
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  if (accessKeyPattern.test(accessKeyId)) {
    console.log(`   ✅ AWS Access Key ID format appears valid: ${accessKeyId}`);
    results.push({ type: 'AWS_ACCESS_KEY_ID', valid: true });
  } else {
    console.log(`   ⚠️  AWS Access Key ID format may be invalid: ${accessKeyId}`);
    console.log('      Expected format: AKIA followed by 16 uppercase alphanumeric characters');
    results.push({ type: 'AWS_ACCESS_KEY_ID', valid: false });
  }

  // Check if it's a canary value
  if (isCanaryValue(accessKeyId) || isCanaryValue(secretKey)) {
    console.log('   ⚠️  AWS credentials appear to be synthetic CANARY values');
    results.push({ type: 'AWS_CANARY', canary: true });
  }

  // AWS Secret Access Key format: 40-character base64 string
  if (secretKey && secretKey.length === 40) {
    console.log(`   ✅ AWS Secret Key length appears valid: ${secretKey.length} characters`);
    results.push({ type: 'AWS_SECRET_LENGTH', valid: true });
