/**
 * Safe Connectivity Test Script
 * Tests what we can safely test without using CANARY credentials
 */

const fs = require('fs');
const path = require('path');
const net = require('net');
const dns = require('dns').promises;
const https = require('https');

// Configuration
const SAFE_TEST_TIMEOUT = 10000; // 10 seconds
const CANARY_KEYWORDS = ['CANARY', 'canary', 'TEST', 'test', 'DUMMY', 'dummy', 'EXAMPLE', 'example'];

// Check if a value contains canary/keywords
function isLikelyTestCredential(value) {
  if (!value) return false;
  return CANARY_KEYWORDS.some(keyword => value.includes(keyword));
}

// Safe DNS test
async function safeDnsTest(hostname) {
  console.log(`\n🔍 Testing DNS resolution for: ${hostname}`);

  try {
    // Try IPv4 first, then IPv6
    const addresses = await dns.resolve4(hostname)
      .catch(() => dns.resolve6(hostname));

    console.log(`   ✅ DNS resolved: ${addresses.join(', ')}`);
    return { success: true, addresses };
  } catch (error) {
    console.log(`   ❌ DNS failed: ${error.message}`);
    return { success: false, error: error.message };
  }
}

// Safe TCP connectivity test
async function safeTcpTest(hostname, port) {
  console.log(`\n🔍 Testing TCP connectivity to ${hostname}:${port}`);

  return new Promise((resolve) => {
    const socket = net.createConnection({
      host: hostname,
      port: port,
      timeout: SAFE_TEST_TIMEOUT
    });

    socket.setTimeout(SAFE_TEST_TIMEOUT);

    socket.on('connect', () => {
      console.log(`   ✅ TCP connection successful`);
      socket.end();
      resolve({ success: true });
    });

    socket.on('timeout', () => {
      console.log(`   ⚠️  Connection timeout`);
      socket.destroy();
      resolve({ success: false, error: 'timeout' });
    });

    socket.on('error', (error) => {
      console.log(`   ❌ Connection error: ${error.message}`);
      resolve({ success: false, error: error.message });
    });
  });
}

// Parse URL and extract hostname/port
function parseUrlForTesting(url) {
  try {
    // Try to parse as URL
    if (url.startsWith('http://') || url.startsWith('https://')) {
      const urlObj = new URL(url);
      return {
        hostname: urlObj.hostname,
        port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
        protocol: urlObj.protocol.replace(':', '')
      };
    }

    // Try to parse database URL: postgres://host:port/db
    if (url.startsWith('postgres://') || url.startsWith('mysql://')) {
      const match = url.match(/^[^:]+:\/\/([^:/]+)(:(\d+))?/);
      if (match) {
        return {
          hostname: match[1],
          port: match[3] || (url.includes('postgres') ? 5432 : 3306),
          protocol: url.split('://')[0]
        };
      }
    }

    return null;
  } catch (error) {
    return null;
  }
}

// Safe API endpoint test (without using credentials)
async function safeApiEndpointTest(apiBaseUrl) {
  console.log(`\n🔍 Testing API endpoint: ${apiBaseUrl}`);

  // Extract hostname from URL
  let hostname;
  try {
    const urlObj = new URL(apiBaseUrl);
    hostname = urlObj.hostname;
  } catch (error) {
    console.log(`   ❌ Invalid URL: ${apiBaseUrl}`);
    return { success: false, error: 'invalid_url' };
  }

  // First test DNS
  const dnsResult = await safeDnsTest(hostname);
  if (!dnsResult.success) {
    return { success: false, error: `dns_failed: ${dnsResult.error}` };
  }

  // Then test HTTP/HTTPS connectivity
  return new Promise((resolve) => {
    const req = https.get(apiBaseUrl, (res) => {
      console.log(`   ✅ HTTP ${res.statusCode} - ${apiBaseUrl}`);
      console.log(`   Response headers: ${Object.keys(res.headers).length} headers`);
      resolve({ success: true, statusCode: res.statusCode });
    });

    req.on('error', (error) => {
      console.log(`   ❌ HTTP error: ${error.message}`);
      resolve({ success: false, error: error.message });
    });

    req.setTimeout(SAFE_TEST_TIMEOUT, () => {
      console.log(`   ⚠️  HTTP timeout`);
      req.destroy();
      resolve({ success: false, error: 'timeout' });
    });
  });
}

// Extract services to test from environment variables
function extractServicesForTesting(envVars) {
  const services = [];

  Object.entries(envVars).forEach(([key, value]) => {
    // Skip if value contains canary keywords
    if (isLikelyTestCredential(value)) {
      console.log(`   ⚠️  Skipping ${key} - contains test/canary keywords`);
      return;
    }

    // Check for URLs
    const urlInfo = parseUrlForTesting(value);
    if (urlInfo) {
      services.push({
        name: key,
        value: value,
        hostname: urlInfo.hostname,
        port: urlInfo.port,
        protocol: urlInfo.protocol
      });
    }

    // Check for API base URLs (common patterns)
    if (key.includes('URL') || key.includes('ENDPOINT') || key.includes('BASE')) {
      if (value.startsWith('http://') || value.startsWith('https://')) {
        services.push({
          name: key,
          value: value,
          type: 'api_endpoint'
        });
      }
    }
  });

  return services;
}

// Main function
async function main() {
  console.log('🛡️ Safe Connectivity Test Script');
  console.log('==============================\n');

  const envFilePath = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envFilePath)) {
    console.error(`❌ File not found: ${envFilePath}`);
    process.exit(1);
  }

  console.log(`📄 Reading environment variables from ${envFilePath}...`);

  const envVars = {};
  const content = fs.readFileSync(envFilePath, 'utf8');

  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        envVars[match[1].trim()] = match[2].trim();
      }
    }
  });

  console.log(`✅ Found ${Object.keys(envVars).length} environment variables\n`);

  // Check for test/canary credentials
  console.log('🎯 Test Credential Detection:');
  const testCredCount = Object.values(envVars).filter(value => 
    isLikelyTestCredential(value)
  ).length;

  console.log(`   Found ${testCredCount} values that appear to be test/canary credentials`);

  if (testCredCount === Object.keys(envVars).length) {
    console.log('\n⚠️  ALL credentials appear to be test/canary values');
    console.log('   No safe connectivity tests will be performed');
    console.log('\n   Consider replacing with:');
    console.log('   1. Real credentials for production');
    console.log('   2. Local test credentials for development');
    console.log('   3. Mock services for isolated testing');
    return;
  }

  // Extract services for testing
  console.log('\n🔍 Extracting services for connectivity testing...');
  const services = extractServicesForTesting(envVars);

  if (services.length === 0) {
    console.log('   No safe services found to test');
    return;
  }

  console.log(`\n✅ Found ${services.length} services to test:\n`);
  services.forEach(service => {
    console.log(`   ${service.name}:`);
    if (service.hostname) {
      console.log(`     Hostname: ${service.hostname}`);
      console.log(`     Port: ${service.port}`);
      console.log(`     Protocol: ${service.protocol}`);
    } else {
      console.log(`     URL: ${service.value}`);
    }
    console.log('');
  });

  // Run connectivity tests
  console.log('🚀 Running connectivity tests...');

  const results = [];

  for (const service of services) {
    if (service.hostname && service.port) {
      // Test DNS first
      const dnsResult = await safeDnsTest(service.hostname);

      if (dnsResult.success) {
        // Then test TCP if DNS succeeded
        const tcpResult = await safeTcpTest(service.hostname, service.port);
        results.push({
          service: service.name,
          dns: dnsResult.success,
          tcp: tcpResult.success,
          error: tcpResult.error
        });
      } else {
        results.push({
          service: service.name,
          dns: false,
          tcp: false,
          error: `dns_failed: ${dnsResult.error}`
        });
      }
    } else if (service.type === 'api_endpoint') {
      const apiResult = await safeApiEndpointTest(service.value);
      results.push({
        service: service.name,
        api: apiResult.success,
        statusCode: apiResult.statusCode,
        error: apiResult.error
      });
    }

    // Small delay between tests
    await new Promise(resolve => setTimeout(resolve, 500));
  }

  // Print results summary
  console.log('\n📊 Connectivity Test Results:');
  console.log('===========================\n');

  results.forEach(result => {
    if (result.tcp !== undefined) {
      const status = result.tcp ? '✅' : '❌';
      console.log(`${status} ${result.service}:`);
      console.log(`   DNS: ${result.dns ? '✅' : '❌'}`);
      console.log(`   TCP: ${result.tcp ? '✅' : '❌'}`);
      if (result.error) console.log(`   Error: ${result.error}`);
    } else if (result.api !== undefined) {
      const status = result.api ? '✅' : '❌';
      console.log(`${status} ${result.service}:`);
      console.log(`   API: ${result.api ? '✅' : '❌'}`);
      if (result.statusCode) console.log(`   Status: ${result.statusCode}`);
      if (result.error) console.log(`   Error: ${result.error}`);
    }
    console.log('');
  });
}

// Run main function
if (require.main === module) {
