    const addresses = await dns.resolve(hostname);
    console.log(`    ✅ Resolved to: ${addresses.join(', ')}`);
    return { success: true, addresses };
  } catch (error) {
    // Try specific record types
    try {
      const ipv4 = await dns.resolve4(hostname);
      console.log(`    ✅ IPv4: ${ipv4.join(', ')}`);
      return { success: true, addresses: ipv4 };
    } catch (ipv4Error) {
      try {
        const ipv6 = await dns.resolve6(hostname);
        console.log(`    ✅ IPv6: ${ipv6.join(', ')}`);
        return { success: true, addresses: ipv6 };
      } catch (ipv6Error) {
        console.log(`    ❌ DNS resolution failed: ${error.message}`);
        return { success: false, error: error.message };
      }
    }
