async function testTcpConnectivity(hostname, port) {
  console.log(`  🔌 TCP connection to ${hostname}:${port}...`);

  return new Promise((resolve) => {
    const socket = net.createConnection({
      host: hostname,
      port: port,
      timeout: 5000
    });

    socket.setTimeout(5000);

    socket.on('connect', () => {
      console.log(`    ✅ Connection successful`);
      socket.end();
      resolve({ success: true });
    });

    socket.on('timeout', () => {
      console.log(`    ⏱️  Connection timeout (5s)`);
      socket.destroy();
      resolve({ success: false, error: 'timeout' });
    });

    socket.on('error', (error) => {
      // Differentiate between connection refused and other errors
      if (error.code === 'ECONNREFUSED') {
        console.log(`    🔒 Connection refused (port may be closed)`);
      } else if (error.code === 'ENOTFOUND') {
        console.log(`    ❓ Host not found`);
      } else {
        console.log(`    ❌ Connection error: ${error.code}`);
      }
      resolve({ success: false, error: error.code });
    });
  });
}

