// Improved application with proper error handling and security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const app = express();

// Security middleware
app.use(helmet()); // Set security headers
app.use(express.json({ limit: '100kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '100kb' }));

// Request validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      status: 'error',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    status: 'error',
    message: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply to all requests
app.use('/health', apiLimiter);
app.use('/users', apiLimiter);

// Input sanitization helper
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;

  // Basic sanitization - remove potential XSS vectors
  return input
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/`/g, '&#x60;')
    .replace(/=/g, '&#x3D;');
};

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    status: 'error',
    message: isProduction ? 'An error occurred. Please try again later.' : err.message,
    ...(!isProduction && { stack: err.stack })
  });
};

// Health endpoint with basic validation
app.get('/health', [
  // Validation rules (if any query params added later)
], validateRequest, (req, res, next) => {
  try {
    // Add health checks here if needed
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: process.env.NODE_ENV || 'development'
    };

    res.json(healthStatus);
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', [
  // Validate query parameters if any are expected
  // Example: body('page').optional().isInt({ min: 1 }).toInt(),
  // Example: body('limit').optional().isInt({ min: 1, max: 100 }).toInt()
], validateRequest, (req, res, next) => {
  try {
    // Validate and sanitize any query parameters
    const queryParams = {};
    if (req.query) {
      for (const [key, value] of Object.entries(req.query)) {
        queryParams[key] = sanitizeInput(value);
      }
    }

    // Mock user data - in real app, would come from database
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com' 
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com' 
      },
    ];

    // Additional filtering/sorting based on query params
    let filteredUsers = [...users];

    // Example of safe filtering (if ID filter provided)
    if (queryParams.id) {
      const id = parseInt(queryParams.id);
      if (!isNaN(id)) {
        filteredUsers = filteredUsers.filter(user => user.id === id);
      }
    }

    res.json({
      status: 'success',
      data: filteredUsers,
      meta: {
        count: filteredUsers.length,
        timestamp: new Date().toISOString()
      }
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Apply error handler
app.use(errorHandler);

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

