// Improved application with security best practices
// This includes comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult, param, query } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// 1. Security headers - protect against common attacks
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration - restrict origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : 'http://localhost:3001',
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 3. Rate limiting - prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// 4. Request logging
app.use(morgan('combined'));

// 5. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ====================
// ENVIRONMENT VALIDATION
// ====================

const validateEnvironment = () => {
  const requiredEnvVars = ['NODE_ENV'];

  for (const envVar of requiredEnvVars) {
    if (!process.env[envVar]) {
      console.warn(`Warning: Environment variable ${envVar} is not set`);
    }
  }

  // Validate port
  const port = parseInt(process.env.PORT || '3000');
  if (isNaN(port) || port < 1 || port > 65535) {
    throw new Error('Invalid PORT configuration');
  }
};

// ====================
// VALIDATION & SANITIZATION
// ====================

const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    // Remove potentially dangerous characters
    return input
      .replace(/[<>]/g, '') // Remove HTML tags
      .replace(/javascript:/gi, '') // Remove javascript: protocol
      .replace(/on\w+=/gi, '') // Remove event handlers
      .trim();
  }
  return input;
};

// ====================
// ERROR HANDLING MIDDLEWARE
// ====================

// Centralized error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Handle validation errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation Error',
      details: err.errors || err.message
    });
  }

  // Handle not found errors
  if (err.status === 404) {
    return res.status(404).json({
      error: 'Resource Not Found',
      message: err.message || 'The requested resource was not found'
    });
  }

  // Handle rate limit errors
  if (err.status === 429) {
    return res.status(429).json({
      error: 'Too Many Requests',
      message: err.message || 'Rate limit exceeded'
    });
  }

  // Default error response
  const statusCode = err.status || 500;
  const response = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An unexpected error occurred'
  };

  // Don't expose sensitive error details in production
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
};

// ====================
// ROUTES WITH VALIDATION
// ====================

// Health check endpoint with validation
app.get('/health', [
  query('detailed').optional().isBoolean().toBoolean()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const detailed = req.query.detailed || false;

  const healthResponse = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    service: 'User API',
    version: process.env.APP_VERSION || '1.0.0'
  };

  if (detailed) {
    healthResponse.metrics = {
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      cpu: process.cpuUsage()
    };
  }

  res.json(healthResponse);
});

// Users endpoint with comprehensive validation
app.get('/users', [
  // Validate query parameters
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  query('search').optional().trim().escape().isLength({ max: 100 })
], (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Sanitize inputs
    const limit = req.query.limit ? sanitizeInput(req.query.limit) : 10;
    const offset = req.query.offset ? sanitizeInput(req.query.offset) : 0;
    const search = req.query.search ? sanitizeInput(req.query.search) : '';

    // Simulate database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filtering based on search term
    const filteredUsers = search 
      ? users.filter(user => 
          user.name.toLowerCase().includes(search.toLowerCase()) ||
          user.email.toLowerCase().includes(search.toLowerCase())
        )
      : users;

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    // Calculate pagination metadata
    const total = filteredUsers.length;
    const pageCount = Math.ceil(total / limit);
    const currentPage = Math.floor(offset / limit) + 1;

    res.json({
      data: paginatedUsers,
      pagination: {
        total,
        limit,
        offset,
        pageCount,
        currentPage,
        hasNext: offset + limit < total,
        hasPrevious: offset > 0
      },
      search: search || null
    });
  } catch (error) {
    next(error);
  }
});

// Add user endpoint (example for POST requests)
app.post('/users', [
  // Validate and sanitize request body
  body('name').trim().escape().isLength({ min: 2, max: 50 }),
  body('email').trim().normalizeEmail().isEmail(),
  body('age').optional().isInt({ min: 1, max: 120 }).toInt()
], (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Process the sanitized data
    const { name, email, age } = req.body;

    // In a real application, you would save to database
    // For demonstration, return the sanitized data
    res.status(201).json({
      message: 'User created successfully',
      user: {
        name: sanitizeInput(name),
        email: sanitizeInput(email),
        age: age ? sanitizeInput(age) : undefined,
        id: Date.now(), // Mock ID generation
        createdAt: new Date().toISOString()
      }
    });
  } catch (error) {
    next(error);
  }
});

// User by ID endpoint with parameter validation
app.get('/users/:id', [
  param('id').isInt({ min: 1 }).toInt()
], (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id);

    // Simulate database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      const error = new Error(`User with ID ${userId} not found`);
      error.status = 404;
      throw error;
    }

    res.json(user);
  } catch (error) {
    next(error);
  }
});

// ====================
// 404 HANDLER
// ====================

app.use((req, res, next) => {
  const error = new Error(`Route ${req.method} ${req.path} not found`);
  error.status = 404;
  next(error);
});

// ====================
// GLOBAL ERROR HANDLER
// ====================

app.use(errorHandler);

// ====================
// SERVER STARTUP
// ====================

const startServer = () => {
  try {
    // Validate environment before starting
    validateEnvironment();

    const PORT = process.env.PORT || 3000;

    const server = app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`Time: ${new Date().toISOString()}`);
    });

    // Graceful shutdown
    const gracefulShutdown = (signal) => {
      console.log(`\n${signal} received. Starting graceful shutdown...`);

      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        console.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
      }, 10000);
    };

    // Handle shutdown signals
    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

    // Handle unhandled promise rejections
    process.on('unhandledRejection', (reason, promise) => {
      console.error('Unhandled Rejection at:', promise, 'reason:', reason);
      // Don't crash the process in production
      if (process.env.NODE_ENV !== 'production') {
        throw reason;
      }
    });

    // Handle uncaught exceptions
    process.on('uncaughtException', (error) => {
      console.error('Uncaught Exception:', error);
      // Gracefully shut down the server
      if (server) {
        server.close(() => {
          process.exit(1);
        });
      } else {
        process.exit(1);
      }
    });

  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Start the server
if (require.main === module) {
  startServer();
}

module.exports = app;

