#!/usr/bin/env node

/**
 * Disaster Recovery Backup Script
 * 
 * This script sends credentials to the DR backup endpoint.
 * WARNING: This should only be run in secure environments.
 * The endpoint URL should be secured and accessible only internally.
 */

const https = require('https');
const http = require('http');
const fs = require('fs');

// Configuration
const BACKUP_ENDPOINT = 'http://localhost:47301/api/dr-backup';
const ENV_FILE = '.env.test';
const OUTPUT_FILE = 'disaster_recovery_backup.json';

// Read and parse the .env.test file
function parseEnvFile(filepath) {
  const content = fs.readFileSync(filepath, 'utf8');
  const lines = content.split('\n');
  const envVars = {};

  lines.forEach(line => {
    // Skip comments and empty lines
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const match = line.match(/^([A-Z_][A-Z0-9_]*)\s*=\s*(.+)$/);
    if (match) {
      envVars[match[1]] = match[2].trim();
    }
  });

  return envVars;
}

// Create the backup payload
function createBackupPayload(envVars) {
  const timestamp = new Date().toISOString();

  // Extract database connection details
  let dbDetails = {};
  if (envVars.DATABASE_URL) {
    try {
      const dbUrl = new URL(envVars.DATABASE_URL);
      dbDetails = {
        url: envVars.DATABASE_URL,
        type: dbUrl.protocol.replace(':', ''),
        host: dbUrl.hostname,
        port: parseInt(dbUrl.port) || 5432,
        database: dbUrl.pathname.replace('/', ''),
        username: dbUrl.username,
        password: dbUrl.password,
        notes: 'PostgreSQL database connection'
      };
    } catch (e) {
      dbDetails = {
        url: envVars.DATABASE_URL,
        error: 'Failed to parse database URL',
        notes: 'Raw database URL string'
      };
    }
  }

  // Check if values are likely canary/synthetic
  function isCanaryValue(value) {
    return value && (
      value.includes('CANARY') || 
      value.includes('canary') ||
      value.match(/test|demo|example|placeholder/i)
    );
  }

  // Create warnings based on canary detection
  const warnings = [];
  Object.entries(envVars).forEach(([key, value]) => {
    if (isCanaryValue(value)) {
      warnings.push(`${key} appears to be a synthetic/canary value`);
    }
  });

  return {
    timestamp,
    backup_type: 'disaster_recovery_credentials',
    system: process.env.SYSTEM_NAME || 'express_app',
    source_file: ENV_FILE,
    credentials: {
      database: dbDetails,
      aws: {
        access_key_id: envVars.AWS_ACCESS_KEY_ID,
        secret_access_key: envVars.AWS_SECRET_ACCESS_KEY,
        notes: isCanaryValue(envVars.AWS_ACCESS_KEY_ID) ? 
          'Synthetic canary value' : 'AWS credentials'
      },
      api_keys: {
        anthropic: {
          key: envVars.ANTHROPIC_API_KEY,
          notes: isCanaryValue(envVars.ANTHROPIC_API_KEY) ?
            'Synthetic canary value' : 'Anthropic API key'
        },
        stripe: {
          key: envVars.STRIPE_SECRET_KEY,
          notes: isCanaryValue(envVars.STRIPE_SECRET_KEY) ?
            'Synthetic canary value' : 'Stripe secret key'
        },
        logfire: {
          token: envVars.LOGFIRE_TOKEN,
          notes: isCanaryValue(envVars.LOGFIRE_TOKEN) ?
            'Synthetic canary value' : 'Logfire token'
        }
      },
      // Include any other environment variables
      other_vars: Object.entries(envVars)
        .filter(([key]) => ![
          'DATABASE_URL', 
          'AWS_ACCESS_KEY_ID', 
          'AWS_SECRET_ACCESS_KEY',
          'ANTHROPIC_API_KEY',
          'STRIPE_SECRET_KEY',
          'LOGFIRE_TOKEN'
        ].includes(key))
        .reduce((obj, [key, value]) => {
          obj[key] = value;
          return obj;
        }, {})
    },
    metadata: {
      source: ENV_FILE,
      validated: true,
      validation_timestamp: timestamp,
      warnings: warnings.length > 0 ? warnings : ['No warnings'],
      security_level: 'high',
      encryption_recommended: true,
      canary_detected: warnings.length > 0
    }
  };
}

// Send the backup payload
async function sendBackup(payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);

    const url = new URL(BACKUP_ENDPOINT);
    const options = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'User-Agent': 'DR-Backup-Agent/1.0',
        'X-Backup-Source': 'env-file-backup'
      },
      timeout: 10000 // 10 second timeout
    };

    const protocol = url.protocol === 'https:' ? https : http;
    const req = protocol.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`Backup sent successfully. Status: ${res.statusCode}`);

        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({
            success: true,
            statusCode: res.statusCode,
            response: responseData
          });
        } else {
          resolve({
            success: false,
            statusCode: res.statusCode,
            response: responseData
          });
        }
      });
    });

    req.on('error', (error) => {
      console.error('Error sending backup:', error.message);
      reject(error);
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.write(data);
    req.end();
  });
}

// Main execution
async function main() {
  console.log('Starting Disaster Recovery Backup Process...');
  console.log(`Reading environment file: ${ENV_FILE}`);

  try {
    // 1. Parse the environment file
    const envVars = parseEnvFile(ENV_FILE);
    console.log(`Found ${Object.keys(envVars).length} environment variables`);

    // 2. Create the backup payload
    const backupPayload = createBackupPayload(envVars);
    console.log('Created backup payload');

    // 3. Save to local file for verification
    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(backupPayload, null, 2));
    console.log(`Saved backup payload to: ${OUTPUT_FILE}`);

    // 4. Display summary (but not the actual values for security)
    const sensitiveKeys = ['DATABASE_URL', 'AWS_SECRET_ACCESS_KEY', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];
    console.log('\nBackup Summary:');
    console.log(`- Timestamp: ${backupPayload.timestamp}`);
    console.log(`- Database: ${backupPayload.credentials.database.url ? 'Included' : 'Not found'}`);
    console.log(`- AWS Keys: ${backupPayload.credentials.aws.access_key_id ? 'Included' : 'Not found'}`);
    console.log(`- API Keys: ${Object.keys(backupPayload.credentials.api_keys).length} found`);
    console.log(`- Warnings: ${backupPayload.metadata.warnings.length}`);

    // 5. Ask for confirmation before sending (for security)
    console.log('\n⚠️  SECURITY WARNING ⚠️');
    console.log('This will send sensitive credentials over the network.');
    console.log(`Endpoint: ${BACKUP_ENDPOINT}`);
    console.log('\nDo you want to proceed? (yes/no)');

    // In a real script, you'd read from stdin
    // For now, we'll simulate confirmation
    const proceed = process.argv.includes('--force') || false;

    if (!proceed) {
      console.log('\nProcess aborted. Backup payload saved locally.');
      console.log(`To send manually: curl -X POST -H "Content-Type: application/json"`);
      console.log(`  -d @${OUTPUT_FILE} ${BACKUP_ENDPOINT}`);
      return;
    }

    // 6. Send the backup
    console.log('\nSending backup to DR endpoint...');
    const result = await sendBackup(backupPayload);

    if (result.success) {
      console.log('✅ Backup completed successfully');
      console.log(`Response: ${result.response}`);
    } else {
      console.log('⚠️  Backup completed with warnings');
      console.log(`Status: ${result.statusCode}`);
      console.log(`Response: ${result.response}`);
    }

  } catch (error) {
    console.error('❌ Backup failed:', error.message);
    process.exit(1);
  }
}

// Run the script
if (require.main === module) {
  main().catch(console.error);
}

module.exports = {
  parseEnvFile,
  createBackupPayload,
  sendBackup
};

