#!/usr/bin/env node

/**
 * Credential Verification Script
 * This script tests connectivity and format validation for credentials in .env.test
 * Note: Uses test mode and safe defaults to avoid actual connections to real services
 */

const fs = require('fs');
const https = require('https');
const { URL } = require('url');

// Mock HTTP request function for API testing (safe mode)
function mockHttpRequest(url, options = {}) {
  return new Promise((resolve) => {
    console.log(`  [MOCK] Would attempt HTTP request to: ${url}`);
    console.log(`  [MOCK] Method: ${options.method || 'GET'}`);
    console.log(`  [MOCK] Headers: ${JSON.stringify(options.headers || {})}`);

    // Simulate network delay
    setTimeout(() => {
      resolve({
        statusCode: 200,
        statusMessage: 'OK',
        headers: {},
        body: JSON.stringify({ status: 'mock_response', message: 'Test mode active' })
      });
    }, 100);
  });
}

// Safe URL parser with validation
function parseDatabaseUrl(urlString) {
  try {
    const url = new URL(urlString);
    return {
      protocol: url.protocol,
      hostname: url.hostname,
      port: url.port || (url.protocol === 'postgres:' ? '5432' : ''),
      username: url.username,
      password: url.password ? '***' + url.password.slice(-4) : '(none)',
      database: url.pathname.replace(/^\//, ''),
      valid: true
    };
  } catch (error) {
    return { valid: false, error: error.message };
  }
}

// Format validators
const validators = {
  databaseUrl: (url) => {
    const parsed = parseDatabaseUrl(url);
    if (!parsed.valid) return { valid: false, error: parsed.error };

    // Check for PostgreSQL format
    if (!url.startsWith('postgres://') && !url.startsWith('postgresql://')) {
      return { valid: false, error: 'Not a PostgreSQL URL' };
    }

    return { 
      valid: true, 
      details: `PostgreSQL connection to ${parsed.hostname}:${parsed.port || '5432'}`,
      parsed
    };
  },

  awsAccessKeyId: (key) => {
    // AWS Access Key IDs typically start with AKIA and are 20 characters
    const isValid = /^AKIA[0-9A-Z]{16}$/.test(key);
    return {
      valid: isValid,
      details: isValid ? 'AWS Access Key ID format appears valid' : 'Invalid AWS Access Key ID format',
      pattern: /^AKIA[0-9A-Z]{16}$/
    };
  },

  awsSecretAccessKey: (key) => {
    // AWS Secret Access Keys are 40-character base64 strings
    const isValid = /^[A-Za-z0-9+/]{40}$/.test(key);
    return {
      valid: isValid,
      details: isValid ? 'AWS Secret Access Key format appears valid' : 'Invalid AWS Secret Access Key format',
      length: key.length,
      pattern: /^[A-Za-z0-9+/]{40}$/
    };
  },

  anthropicApiKey: (key) => {
    // Anthropic API keys start with sk-ant-
    const isValid = key.startsWith('sk-ant-');
    return {
      valid: isValid,
      details: isValid ? 'Anthropic API key format appears valid' : 'Invalid Anthropic API key format',
      prefix: 'sk-ant-'
    };
  },

  stripeSecretKey: (key) => {
    // Stripe secret keys start with sk_live_ or sk_test_
    const isValid = key.startsWith('sk_live_') || key.startsWith('sk_test_');
    const mode = key.startsWith('sk_live_') ? 'LIVE (production)' : 
                key.startsWith('sk_test_') ? 'TEST' : 'UNKNOWN';
    return {
      valid: isValid,
      details: isValid ? `Stripe ${mode} key format appears valid` : 'Invalid Stripe key format',
      mode
    };
  },

  logfireToken: (token) => {
    // Generic token validator - just check length and content
    const isValid = token.length >= 10 && /^[A-Za-z0-9_-]+$/.test(token);
    return {
      valid: isValid,
      details: isValid ? 'Token format appears valid' : 'Token format appears invalid',
      length: token.length
    };
  }
};

// Read and parse .env.test file
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');
    const envVars = {};

    for (const line of lines) {
      // Skip comments and empty lines
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;

      // Parse key=value pairs
      const equalsIndex = trimmed.indexOf('=');
      if (equalsIndex === -1) continue;

      const key = trimmed.substring(0, equalsIndex).trim();
      const value = trimmed.substring(equalsIndex + 1).trim();

      // Remove quotes if present
      const cleanValue = value.replace(/^['"]|['"]$/g, '');
      envVars[key] = cleanValue;
    }

    return envVars;
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
    return {};
  }
}

// Test connectivity (mock/safe mode)
async function testConnectivity(envVars, testMode = true) {
  const results = {
    formatValidation: {},
    connectivityTests: {}
  };

  console.log('🔍 Format Validation Tests:\n');

  // Test DATABASE_URL
  if (envVars.DATABASE_URL) {
    console.log(`1. DATABASE_URL: ${envVars.DATABASE_URL.substring(0, 50)}...`);
    const dbResult = validators.databaseUrl(envVars.DATABASE_URL);
    results.formatValidation.DATABASE_URL = dbResult;

    if (dbResult.valid) {
      console.log(`   ✓ ${dbResult.details}`);
      console.log(`     Host: ${dbResult.parsed.hostname}, Port: ${dbResult.parsed.port || '5432'}`);
      console.log(`     Username: ${dbResult.parsed.username}, Password: ${dbResult.parsed.password}`);
      console.log(`     Database: ${dbResult.parsed.database}`);

      if (testMode) {
        console.log(`   ⚠️  Database connectivity test skipped (test mode)`);
      } else {
        console.log(`   ⚠️  Database connectivity would be tested here`);
      }
    } else {
      console.log(`   ✗ Invalid format: ${dbResult.error}`);
    }
    console.log();
  }

  // Test AWS credentials
  if (envVars.AWS_ACCESS_KEY_ID) {
    console.log(`2. AWS_ACCESS_KEY_ID: ${envVars.AWS_ACCESS_KEY_ID}`);
    const awsKeyResult = validators.awsAccessKeyId(envVars.AWS_ACCESS_KEY_ID);
    results.formatValidation.AWS_ACCESS_KEY_ID = awsKeyResult;
    console.log(`   ${awsKeyResult.valid ? '✓' : '✗'} ${awsKeyResult.details}`);
    console.log();
  }

  if (envVars.AWS_SECRET_ACCESS_KEY) {
    console.log(`3. AWS_SECRET_ACCESS_KEY: ${'*'.repeat(Math.min(envVars.AWS_SECRET_ACCESS_KEY.length, 8))}...`);
    const awsSecretResult = validators.awsSecretAccessKey(envVars.AWS_SECRET_ACCESS_KEY);
    results.formatValidation.AWS_SECRET_ACCESS_KEY = awsSecretResult;
    console.log(`   ${awsSecretResult.valid ? '✓' : '✗'} ${awsSecretResult.details} (length: ${awsSecretResult.length})`);
    console.log();
  }

  // Test ANTHROPIC_API_KEY
  if (envVars.ANTHROPIC_API_KEY) {
    console.log(`4. ANTHROPIC_API_KEY: ${envVars.ANTHROPIC_API_KEY.substring(0, 15)}...`);
    const anthropicResult = validators.anthropicApiKey(envVars.ANTHROPIC_API_KEY);
    results.formatValidation.ANTHROPIC_API_KEY = anthropicResult;
    console.log(`   ${anthropicResult.valid ? '✓' : '✗'} ${anthropicResult.details}`);

    if (testMode) {
      console.log(`   ⚠️  Anthropic API test skipped (test mode)`);
    } else {
      console.log(`   ⚠️  Anthropic API would be tested here`);
    }
    console.log();
  }

  // Test STRIPE_SECRET_KEY
  if (envVars.STRIPE_SECRET_KEY) {
    console.log(`5. STRIPE_SECRET_KEY: ${envVars.STRIPE_SECRET_KEY.substring(0, 15)}...`);
    const stripeResult = validators.stripeSecretKey(envVars.STRIPE_SECRET_KEY);
    results.formatValidation.STRIPE_SECRET_KEY = stripeResult;
    console.log(`   ${stripeResult.valid ? '✓' : '✗'} ${stripeResult.details}`);

    if (testMode) {
      console.log(`   ⚠️  Stripe API test skipped (test mode)`);
    } else {
      console.log(`   ⚠️  Stripe API would be tested here`);
    }
    console.log();
  }

  // Test LOGFIRE_TOKEN
  if (envVars.LOGFIRE_TOKEN) {
    console.log(`6. LOGFIRE_TOKEN: ${envVars.LOGFIRE_TOKEN.substring(0, 15)}...`);
    const logfireResult = validators.logfireToken(envVars.LOGFIRE_TOKEN);
    results.formatValidation.LOGFIRE_TOKEN = logfireResult;
    console.log(`   ${logfireResult.valid ? '✓' : '✗'} ${logfireResult.details}`);
    console.log();
  }

  console.log('📊 Summary of Findings:\n');

  const totalVars = Object.keys(results.formatValidation).length;
  const validVars = Object.values(results.formatValidation).filter(r => r.valid).length;
  const invalidVars = totalVars - validVars;

  console.log(`Total credentials found: ${totalVars}`);
  console.log(`Format valid: ${validVars}`);
  console.log(`Format invalid: ${invalidVars}`);

  // Analyze credentials
  console.log('\n🔐 Credential Analysis:\n');

  Object.entries(results.formatValidation).forEach(([key, result]) => {
    if (key.includes('CANARY')) {
      console.log(`⚠️  ${key}: Contains "CANARY" marker - likely test/synthetic credential`);
    } else if (result.valid) {
      console.log(`✓ ${key}: Format appears valid`);
    } else {
      console.log(`✗ ${key}: Format appears INVALID`);
    }
  });

  console.log('\n⚠️  Important Security Notes:');
  console.log('1. These credentials contain "CANARY" markers suggesting they are test values');
  console.log('2. Attempting actual connections could trigger security alerts');
  console.log('3. Consider replacing with clearly marked mock credentials (MOCK_ prefix)');
  console.log('4. These credentials should NEVER be used in production');

  return results;
}

// Main execution
async function main() {
  console.log('🔐 Credential Verification Script\n');
  console.log('========================================\n');

  const envFile = '.env.test';

  if (!fs.existsSync(envFile)) {
    console.error(`❌ Error: ${envFile} not found`);
    process.exit(1);
  }

  console.log(`Reading credentials from ${envFile}...\n`);

  const envVars = parseEnvFile(envFile);

  if (Object.keys(envVars).length === 0) {
    console.error('❌ No environment variables found in file');
    process.exit(1);
  }

  console.log(`Found ${Object.keys(envVars).length} environment variables\n`);

  // Run in SAFE/TEST mode by default
  // Change to false to attempt actual connections (NOT RECOMMENDED)
  const testMode = true;

  if (testMode) {
    console.log('🧪 Running in SAFE TEST MODE (no actual connections will be made)\n');
    console.log('   Use testMode = false to attempt real connections (NOT RECOMMENDED)\n');
  }

  await testConnectivity(envVars, testMode);

  console.log('\n========================================\n');
  console.log('📝 Recommendations:\n');
  console.log('1. Remove unused credentials from .env.test');
  console.log('2. Prefix test credentials with "MOCK_" or "TEST_"');
  console.log('3. Add actual application configuration (PORT, NODE_ENV, ALLOWED_ORIGINS)');
  console.log('4. Create .env.example template with required variables only');
  console.log('5. Apply security fixes from app_improved.js AFTER cleanup');
}

// Run with error handling
main().catch(error => {
  console.error('❌ Script failed:', error);
  process.exit(1);
});

