  console.log('\n⚠️  SECURITY WARNING:');
  console.log('This script could attempt actual connections to databases and APIs.');
  console.log('Using CANARY/test credentials may trigger security alerts.');
  console.log('Only proceed in isolated test environments.\n');

  const answer = await askQuestion('Continue with SAFE analysis only? (yes/no): ');

  if (answer !== 'yes' && answer !== 'y') {
    console.log('\n✅ Operation cancelled. No connections attempted.');
    rl.close();
    return;
  }

  console.log('\n📖 Reading environment file...');
  const envVars = parseEnvFile(envFile);

  if (Object.keys(envVars).length === 0) {
    console.error('❌ No environment variables found');
    rl.close();
    process.exit(1);
  }

  // Analyze credentials first
  const analysis = await analyzeCredentials(envVars);

  console.log('\n🔗 Connectivity Tests:\n');
  console.log('Note: Actual connection attempts are DISABLED by default');
  console.log('      for safety when CANARY/MOCK credentials are detected\n');

  // Test database if present
  if (envVars.DATABASE_URL) {
    await testPostgresConnection(envVars.DATABASE_URL);
  }

  // Test Anthropic API if present
  if (envVars.ANTHROPIC_API_KEY) {
    await testHttpApi(
      'https://api.anthropic.com/v1/messages',
      envVars.ANTHROPIC_API_KEY,
      'Anthropic'
    );
  }

  // Test Stripe API if present
  if (envVars.STRIPE_SECRET_KEY) {
    await testHttpApi(
      'https://api.stripe.com/v1/balance',
      envVars.STRIPE_SECRET_KEY,
      'Stripe'
    );
  }

  console.log('\n='.repeat(60));
  console.log('\n📝 FINAL RECOMMENDATIONS:\n');

  if (analysis.canaryCredentials.length > 0) {
    console.log('🚨 URGENT: Replace CANARY credentials with MOCK_ prefixed values');
    console.log('   Example: DATABASE_URL=postgres://mock_user:mock_pass@localhost/db');
    console.log('   Purpose: Clearly distinguish test vs production credentials\n');
  }

  console.log('🛡️  Security Best Practices:');
  console.log('1. Use different credential formats for different environments');
  console.log('2. Never commit real credentials to version control');
  console.log('3. Use .env.local for local development (add to .gitignore)');
  console.log('4. Use environment-specific .env files (.env.test, .env.production)');
  console.log('5. Regularly rotate and audit credentials\n');

  console.log('🔧 Next Steps for This Project:');
  console.log('1. Replace .env.test with cleaned version (see clean_env.test)');
  console.log('2. Verify app.js dependencies match environment variables');
  console.log('3. Apply security improvements from app_improved.js');
  console.log('4. Add missing config (PORT, NODE_ENV, ALLOWED_ORIGINS)');
  console.log('5. Create .env.example template');

  rl.close();
}

// Run with proper error handling
main().catch(error => {
  console.error('\n❌ Script failed:', error);
  if (rl) rl.close();
  process.exit(1);
});
